\title{Embeddings into the ultrapower of the Jiang-Su algebra}
\author{Ben Bouwen}
    \address{Department of Mathematics and Computer Science, University of Southern Denmark, Odense, Denmark}
    \email{bouwen@imada.sdu.dk}
\author{Jennifer Pi}
    \address{Department of Mathematics, University of Oxford, Oxford, United Kingdom}
