\section{Orbifold realization of $\W_{-1}(\so_N,\minO)$}\label{sec2}

\subsection{Preliminary}
Given a vertex superalgebra $V$, let $V=V_{\overline{0}}\oplus V_{\overline{1}}$ be the parity decomposition, $\vac\in V_{\overline{0}}$ the vacuum vector, and
$$Y(\cdot,z)\colon V \rightarrow \mathrm{End}(V)\llbracket z^{\pm1}\rrbracket,\qquad a\mapsto a(z):=\sum_{n \in \Z} a_{(n)}z^{-n-1}$$
the vertex operator.
The translation operator and the normally ordered product are defined by
\begin{align*}
    \pd\colon V \rightarrow V,\ A \mapsto A_{(-2)}\vac,\qquad 
    V \times V\rightarrow V,\ (A,B) \mapsto A_{(-1)}B
\end{align*}
respectively, and the $\lm$-bracket by
\begin{align*}
   [\cdot{}_\lambda \cdot]\colon V\times V \rightarrow V[\lambda],\quad (A,B)\mapsto [A{}_\lambda B]:=\sum_{n=0}^\infty A_{(n)}B \tfrac{\lm^n}{n!}.
\end{align*} 

Let $\g$ be a simple Lie algebra, or the Lie superalgebra $\osp_{1|2n}$, and set $u_i$ ($i=1,\dots, \dim \g$) a basis of $\g$.
Then $V^k(\g)$ denotes the universal affine vertex (super)algebra associated with $\g$ at level $k \in \C$.
It is strongly and freely generated by the fields 
\begin{equation}\label{eq:field_affine_VOA}
u_i(z)=\sum_{n\in\Z}u_{i,(n)}z^{-n-1},\qquad u_{i,(n)}:=u_i\otimes t^n,
\end{equation}
\ie\ the PBW basis given by the monomials
\begin{equation}
    u_{i_1,(-n_1)}u_{i_2,(-n_2)}\dots u_{i_\ell,(-n_\ell)}\vac
\end{equation}
with $i_1\geq i_2\geq\dots\geq i_\ell$ and $n_j\geq n_{j+1}$ if $i_j= i_{j+1}$,
spans $V^k(\g)$.
Their $\lm$-brackets are given by
\begin{align*}
    [u_i{}_\lm u_j]=k(u_i,u_j)\lm + [u_i,u_j]
\end{align*}
where $(\cdot,\cdot)$ is the normalized invariant bilinear form on $\g$. 
In this article, we always assume the level to be \emph{non-critical}, \ie\ $k\neq-h^\vee$ where $h^\vee$ is the dual Coxeter number of $\g$. Then $V^k(\g)$ admits a conformal vector $L$ defined by the Sugawara construction, which satisfies the $\lambda$-bracket 
\begin{align*}
    \lbr{L}{L}=\frac{c_k}{2}\lm^3+2L \lm+ \pd L
\end{align*}
where the scalar $c_k=\frac{k\sdim\g}{k+h^\vee}$ is the central charge of $V^k(\g)$. The field $L$ generates a Virasoro vertex subalgebra at central charge $c_k$, denoted by $\Vir^{c_k}$.
Denote by $L_k(\g)$ the unique simple quotient of $V^k(\g)$ and by $\Vir_{c_k}$ the unique simple quotient of $\Vir^{c_k}$.

\subsection{Minimal $\W$-algebras}\label{Minimal Walg}
Let $\g$ be a simple Lie algebra and take $f\in\g$ a (non-zero) nilpotent element.
By the Jacobson-Morozov theorem, one may find an $\sll_2$-triple $\{e,h=2x,f\}$ in $\g$, such that the adjoint $x$-action defines a $\frac{1}{2}\Z$-grading $\Gamma\colon \g=\bigoplus_{i}\g_i$.
The $\W$-algebra $\W^k(\g,f,\Gamma)$ associated with the pair $(f,\Gamma)$ is the quantum Hamiltonian reduction of the affine vertex algebra $V^k(\g)$.
As it depends only on the adjoint class, \ie\ the nilpotent orbit $\OO$ containing $f$, we denote it by $\W^k(\g,\OO)$ and its unique simple quotient by $\W_k(\g,\OO)$.

The nilpotent orbits form a poset where the partial order is defined by the closure relations for the Zariski topology on the nilpotent cone $\mathcal{N}$ of $\g$. The minimal nilpotent orbit $\OO_{\mathrm{min}}$ is the unique smallest, non-trivial orbit in $\mathcal{N}$. 
In this case, the grading $\Gamma$ is of the form
\begin{align*}
    \g=\g_{-1} \oplus \g_{-1/2} \oplus \g_{0} \oplus \g_{1/2} \oplus \g_{1}
\end{align*}
and $\W^k(\g,\minO)$ is strongly and freely generated by a basis of the centralizer 
$$\g^f=\g^f_0\oplus \g^f_{-1/2}\oplus \g^f_{-1}.$$
Note that $\g^\sharp=\g^f_0$ is a Lie subalgebra acting naturally on $\g^f_{-1/2}$ and $\g^f_{-1}$. In particular, $\g^f_{-1}=\C f$ is the trivial $\g^\sharp$-module.
By \cite[Theorem 5.1]{KW-QR},
\begin{itemize}
    \item[(M1)] $\g^\sharp$ generates an affine vertex subalgebra $V^{k^\sharp}(\g^\sharp)$ at level $k^\sharp$ that depends linearly on $k$,
    \item[(M2)] $\g^f_{-1}$ generates a Virasoro vertex subalgebra $\Vir^{c_{\W,k}}=\langle L_\W\rangle$ of central charge 
    $$c_{\W,k}=\frac{k \dim\g}{k+h^\vee}-6k+h^\vee-4,$$
    \item[(M3)] The generators $G^{\{u\}}$ ($u\in \g^f_{-1/2}$) have conformal weight $3/2$ and transforms as $\g^f_{-1/2}$ under the $\g^\sharp$-action, \ie\
    \begin{align*}
    \lbr{L_\W}{G^{\{u\}}}=\frac{3}{2}G^{\{u\}} \lm+\pd G^{\{u\}},\qquad \lbr{a}{G^{\{u\}}}=G^{\{[a,u]\}}\quad (a\in \g^\sharp).    
    \end{align*}
\end{itemize}
The remaining $\lambda$-brackets to fully determine $\W^k(\g,\minO)$ are given by
\begin{align}\label{OPE for weight3/2}
    \lbr{G^{\{u\}}}{G^{\{v\}}}=\frac{1}{6}a_0(k) (e,[u,v])\lm^2+ a_1(u,v;k)\lm+a_2(u,v;k)
\end{align}
with a certain scalar $a_0(k)$ depending only on $k$, and differential polynomials $a_i(u,v;k)$ of conformal weight $i=1,2$, see \cite[Theorem 5.1]{KW-QR} for the precise formula.

%Indeed, the conditions (M1)-(M3) characterize the simple minimal $\W$-algebra as follows. 
\begin{theorem}[{\cite[Theorem 3.2]{ACKL}}]\label{uniqueness of minimal Walg}
Let $V$ be a simple vertex algebra strongly generated by elements satisfying the properties (M1)-(M3). 
If in addition, $a_0(k)\neq0$ and the bilinear form 
\begin{equation*}
    V_{3/2}\times V_{3/2}\to \C,\qquad (A,B)\mapsto A_{(2)}B
%(G^{\{i\}},G^{\{j\}})\to G^{\{i\}}_{(2)}G^{\{j\}}
\end{equation*}
is non-degenerate, then $V \simeq \W_k(\g,\minO)$ holds.
%If the level $k$ satisfies $a_0(k)\neq 0$ and \red{the bilinear form $(e,[\cdot,\cdot])$ on $\g^f_{-1/2}\times \g^f_{-1/2}$ in the $\lambda$-bracket \eqref{OPE for weight3/2} for $V$} 
\end{theorem}

\subsection{Proof of Theorem \ref{coset construction}}
We fix a basis of $\osp_{1|2}$ whose corresponding fields \eqref{eq:field_affine_VOA} strongly and freely generate $V^\ell(\osp_{1|2})$. 
The even fields $e, f, h$ generate a vertex subalgebra $V^\ell(\sll_2)$ and the non-trivial $\lm$-brackets involving the odd fields $x, y$ of conformal weight one satisfy
\begin{comment}
\begin{equation}\nonumber
    \begin{split}
&\lbr{h}{h}= 2 \ell \lm, \qquad \lbr{h}{e} =  2e, \qquad \lbr{h}{f} =  -2f, \\
&\lbr{e}{f}=  \ell \lm+h,
    \end{split}
\end{equation}
and    
\end{comment}
\begin{equation*}
    \begin{aligned}
&\lbr{h}{x}= x, \qquad &&\lbr{h}{y} =  -y, \qquad &&\lbr{f}{x}=y, \qquad &&\lbr{e}{y}=x,\\
&\lbr{x}{x}=-2e, \qquad &&\lbr{y}{y}=2f,\qquad &&\lbr{x}{y}=2\ell \lm +h.
    \end{aligned}
\end{equation*}
Meanwhile, the $r$-free fermions vertex superalgebra $\mathcal{F}^r$ is strongly and freely generated by $\psi_1, \dots, \psi_r$ satisfying the $\lm$-brackets
$$\lbr{\psi_i}{\psi_j}=\delta_{i, j}.$$
Moreover, $\mathcal{F}^r$ has a conformal vector,
$$L_{\mathcal{F}^r}= \frac{1}{2}\sum_{i=1}^r (\partial\psi_i)\psi_i,$$
of central charge $c_r=\frac{r}{2}$, that gives $\psi_i$ ($1\leq i\leq r$) conformal weight $1/2$. 

Define the even vertex subalgebra
$$\scV^\ell(r):=(V^\ell(\osp_{1|2}) \otimes \mathcal{F}^r)_{\overline{0}}\subset V^\ell(\osp_{1|2}) \otimes \mathcal{F}^r$$
strongly generated by the subset 
$$\widetilde{\mathcal{S}}=\{e, f, h,X_{i}^{a, b},Y_{i}^{a, b},W_{i,j}^{a, b},Z_{z,z'}^{a, b}\mid 1\leq i,j\leq r,\, z, z' \in \{x, y\},\, a,b \geq0\}$$ 
where
$$X_{i}^{a, b}= (\partial^a x) (\partial^b \psi_i), \quad Y_{i}^{a, b} = (\partial^a y)(\partial^b \psi_i),\quad W_{i, j}^{a, b} =(\partial^a\psi_i) (\partial^b \psi_j), \quad Z_{z, z'}^{a, b} = (\partial^a z)(\partial^b z').$$

\begin{comment}
\begin{lemma}\label{lem:strong_gen}
