$$\mathcal{S}=\{e, f, h, X_{i}^{0, 0}, Y_{i}^{0, 0}, W_{i, j}^{0, 0}, Z_{z, z'}^{0, 0}\mid 1\leq i<j\leq r,\, z, z' \in \{x, y\}\}\subset \widetilde{\mathcal{S}}.$$
\end{lemma}
\end{comment}
\begin{lemma}\label{lem:strong_gen}
For $r\geq3$, the vertex algebra $\scV^\ell(r)$ is strongly generated by the subset
$$\mathcal{S}=\{e, f, h, X_{m}^{0, 0}, Y_{m}^{0, 0}, W_{i, j}^{0, 0}, Z_{x,y}^{0, 0}\mid 1\leq i<j\leq r, 1\leq m\leq r\}\subset \widetilde{\mathcal{S}}.$$
\end{lemma}

\begin{proof}
Using the Leibniz rule $\partial (AB) = (\partial A)B + A (\partial B)$, the generating set $\widetilde{\mathcal{S}}$ reduces to
$$\{e, f, h, X_{i}^{a, 0}, Y_{i}^{a, 0}, W_{i, j}^{a, 0}, Z_{z, z'}^{a, 0}\mid 1\leq i,j\leq r,\, z, z' \in \{x, y\},\, a\geq0\}.$$
Moreover, for all $1\leq i,j,m\leq r$ and $a\geq0$,
\begin{equation*}
X_{i}^{a, 0} W_{i, m}^{0, 0} = (1- \delta_{i, m}) X_{m}^{a+1, 0}, 
\qquad Y_{i}^{a, 0} W_{i, m}^{0, 0} = (1- \delta_{i, m}) Y_{m}^{a+1, 0}
\end{equation*}
and
\begin{equation*}
W_{i, j}^{a, 0} W_{j, m}^{0, 0} = 
\begin{cases}
    W_{i, m}^{a+1, 0}\quad &(i,j,m \text{ all different}),\\
    \frac{(-1)^a}{a+1}W_{j,j}^{a+1,0}+W_{m,m}^{a+1, 0}\quad &(i=m,j\neq m),\\
    0\quad&(j=m).
\end{cases}
\end{equation*}
In particular, we have for $1\leq i,j,m\leq r$ all different,
\begin{align*}
    W_{i,i}^{a+1,0}&=\begin{cases}
        \left(1- \frac{1}{(a+1)^2}\right)^{-1}\left(W_{i, j}^{a, 0} W_{j, i}^{0, 0}- \frac{(-1)^a}{a+1}W_{j, i}^{a, 0} W_{i, j}^{0, 0}\right)
    %\frac{(-1)^a}{a+1}W_{j,j}^{a+1,0}+W_{m,m}^{a+1, 0}- \frac{(-1)^a}{a+1}\left(\frac{(-1)^a}{a+1}W_{m,m}^{a+1,0}+W_{j,j}^{a+1, 0}\right)\\
    \qquad &(a>0),\\
    \frac{1}{2}(W_{i, j}^{0, 0} W_{j, i}^{0, 0}+W_{i, m}^{0, 0} W_{m,i}^{0, 0}-W_{m, j}^{0, 0} W_{j, m}^{0, 0})& (a=0).
    \end{cases}
\end{align*}
Noting that $W_{i, j}^{0, 0} = - W_{j, i}^{0, 0}$, one may further reduce the generating set so that $a=0$ for $W_{i, j}^{a, 0}$ $(i<j)$, $X_{m}^{a, 0}, Y_{m}^{a, 0}$.
Similarly,
\begin{equation*}
    \begin{split}
Z_{x, y}^{a+1, 0} = - X_{i}^{a, 0}Y_{i}^{0, 0}+\dots,\qquad
Z_{x, x}^{a+1, 0} = - X_{i}^{a, 0}X_{i}^{0, 0}+\dots,\qquad
Z_{y, y}^{a+1, 0} = - Y_{i}^{a, 0}Y_{i}^{0, 0}+\dots
\end{split}
\end{equation*}
where `$\dots$' are correction terms that only involve $W_{i, i}^{a, 0}$ and derivatives of $e,f,h$.
\begin{comment}
\begin{equation*}
\begin{split}
X_{i}^{a, 0}Y_{i}^{0, 0} &= - Z_{x, y}^{a+1, 0}  - Z^{a, 0}_{x, y} W^{1, 0}_{i, i} - \frac{(-1)^a}{a+1} h W^{a+1, 0}_{i, i} - \frac{k(-1)^a}{a+2} W^{a+2, 0}_{i, i} \\
X_{i}^{a, 0}X_{i}^{0, 0} &= - Z_{x, x}^{a+1, 0}  - Z^{a, 0}_{x, x} W^{1, 0}_{i, i} +  2\frac{(-1)^a}{a+1} e W^{a+1, 0}_{i, i}  \\
Y_{i}^{a, 0}Y_{i}^{0, 0} &= - Z_{y, y}^{a+1, 0}  - Z^{a, 0}_{y, y} W^{1, 0}_{i, i} -  2\frac{(-1)^a}{a+1} f W^{a+1, 0}_{i, i}
