\section{Ordinary Modules}\label{sec: ordinary modules}
In this section, we construct and classify the simple ordinary $\W_{-1}(\so_{N},\minO)$-modules.
This classification is first established in \S \ref{orbifold}, through the orbifold (Theorem \ref{coset construction}).
Then modules are realized in terms of the quantum Hamiltonian reduction in \S \ref{QHR-description}. 

\subsection{Generalities}
In this section, let $\g$ be a simple Lie algebra and $\widehat{\g}=\g[t^{\pm1}]\oplus \C K$ be the affine Lie algebra.
Fix
$$\g=\mathfrak{n}_+ \oplus \h \oplus \mathfrak{n}_-,\qquad \widehat{\g}=\widehat{\mathfrak{n}}_+ \oplus \widehat{\h} \oplus \widehat{\mathfrak{n}}_-$$
the usual triangular decompositions so that $\widehat{\h}=\h \oplus \C K$. 
Denote by $\alpha_1^\vee,\cdots,\alpha_n^\vee$ the simple coroots of $\g$ and by $\varpi_1,\cdots,\varpi_n$ its fundamental weights.
Then the simple coroots of $\widehat{\g}$ are 
$\alpha_0^\vee=-\theta+K, \alpha_1^\vee,\cdots,\alpha_n^\vee$
where $\theta$ is the highest root of $\g$ viewed as an element in $\h$ identified with its dual $\h^*$ through the normalized invariant bilinear form $(\cdot, \cdot)$. 

Let $\rho_\lm$ be the simple $\g$-module of highest weight $\lm \in \h^*$ and $L(\widehat{\lm})$ the simple $\widehat{\g}$-module of highest weight $\widehat{\lm} \in \widehat{\h}^*$.
The latter $L(\widehat{\lm})$ is naturally a (simple) positively graded $V^k(\g)$-module at level $k=\widehat{\lm}(K)$ whose the top space, 
that can be identified with the simple $\g$-module $\rho_\lm$ (with $\lm=\widehat{\lm}|_{\h^*}$),
has conformal weight 
\begin{align}
    h_\lm=\frac{({\lm},{\lm}+2{\rho})}{2(k+h^\vee)}
\end{align}
where ${\rho}=\sum_{i=1}^n\varpi_i$.
To highlight the structure of vertex algebra module, we denote $L(\widehat{\lm})$ by $L_k(\lm)$.

In the following, set $\OO=\minO$.
Given a $V^k(\g)$-module $M$, the zero-th BRST cohomology $\HH_{\OO}^0(M)$ associated with the minimal nilpotent orbit is naturally a $\W^{k}(\g,\OO)$-module. Indeed, this association gives a functor 
\begin{align*}
    \HH_\OO^0\colon V^k(\g)\mod\rightarrow \W^k(\g,\OO)\mod
\end{align*}
from the category of $V^k(\g)$-modules to the category of $\W^k(\g,\OO)$-modules.
In addition, the simple ordinary $\W^k(\g,\OO)$-modules are classified by the highest weight representations $\mathbf{L}_k(\lm^\sharp,h_\lambda^\sharp)$ of heighest weight $\lm^\sharp=\lm|_{\h^\sharp}$ with respect to the Cartan subalgebra $\h^\sharp= \h\cap \g^\sharp\subset \g^\sharp$ and conformal dimension $h_\lambda^\sharp$ \cite[\S 6]{A05}.
%see also \S \ref{Minimal Walg} for the strong generators of $\W^k(\g,\OO)$.

\begin{theorem}[\cite{A05}] \label{A05: minimal reduction}
For $\lm\in \h^*$, there is an isomorphism of $\W^k(\g,\OO)$-modules
\begin{align*}
    \HH^0_{\OO}(L_k(\lm)) \simeq \begin{cases}
        0 & \widehat{\lm}(\alpha_0^\vee)\in \Z_{\geq0}\\
        \mathbf{L}_k(\lm^\sharp, h_\lambda^\sharp) & \text{otherwise},
    \end{cases}
\end{align*}
where 
\begin{align}\label{conformal weight of minimal reduction}
    %\lm^\sharp=\lm|_{\h^\sharp},\qquad 
    h_\lambda^\sharp= \frac{(\lm, \lm+2\rho)}{2(k+h^\vee)}-{(\lm,\theta)}.
\end{align}
\end{theorem}


\subsection{Irreducible modules via orbifold}\label{orbifold}
Here, we construct ordinary simple $\W_{-1}(\so_{N},\minO)$-modules by using the realization established in Theorem \ref{coset construction}
\begin{align*}
   \W_{-1}(\so_{N},\minO)
    &\simeq (L_\ell(\osp_{1|2}) \otimes \mathcal{F}^r)_{\overline{0}}
    =L_\ell(\osp_{1|2})_{\overline{0}}\otimes \mathcal{F}^r_{\overline{0}}\oplus L_\ell(\osp_{1|2})_{\overline{1}}\otimes \mathcal{F}^r_{\overline{1}},
\end{align*}
with $\ell=-1+\frac{r}{2}$ and $r=N-4$.
By Theorem \ref{classification of simples}, simple ordinary modules can be obtained as 
\begin{align}\label{constructing simple modules}
    \ev{(M\otimes N)}=\ev{M}\otimes \ev{N} \oplus \od{M}\otimes \od{N},\quad \od{(M\otimes N)}=\ev{M}\otimes \od{N} \oplus \od{M}\otimes \ev{N}
\end{align}
where $M$ and $N$ are simple ordinary $L_\ell(\osp_{1|2})$-module and $\mathcal{F}^r$-module respectively, that are both local or both Ramond twisted.

Simple $L_\ell(\osp_{1|2})$-modules have been studied in \cite{CFK, CGL, CKLR2, RSW, wood} (see also \cite{KW88}).
In particular, the complete sets of simple ordinary local and Ramond twisted $L_\ell(\osp_{1|2})$-modules are given by highest weight representations
\begin{align*}
    &\irr{loc}{L_\ell(\osp_{1|2})}=\obj{L_\ell(\lambda), \Pi L_\ell(\lambda) \mid  \lambda=0,1,\dots, \lfloor\tfrac{p-2}{2}\rfloor} ,\quad \\
    &\irr{R}{L_\ell(\osp_{1|2})}=\obj{L_\ell^R(\lambda), \Pi L_\ell^R(\lambda) \mid \lambda=0,1,\dots, \lfloor\tfrac{p-3}{2}\rfloor}
\end{align*}
where $\Pi L_\ell(\lambda)$ (resp.\ $\Pi L_\ell^R(\lambda)$) is the parity reversal of $L_\ell(\lambda)$ (resp.\ $L_\ell^R(\lambda)$) and
\begin{align*}
    %\lambda \in \mathbb Z_{\geq0},\qquad 
    p = \begin{cases}
        {2\ell+3} & (\ell \in \Z_{\geq0}),\\
        2(2\ell+3) & (\ell \in \mathbb Z_{\geq0} + \frac{1}{2}).
    \end{cases} 
\end{align*}

The parity decomposition of a (local or Ramond twisted) $L_\ell(\osp_{1|2})$-module is denoted by $M=\ev{M}\oplus\od{M}$. 
Note that $\ev{\Pi M}\simeq \od{M}$ and $\od{\Pi M}\simeq \ev{M}$.
%\begin{align*}   
%    L_\ell(\lambda) = \ev{L_\ell(\lambda)} \oplus \od{L_\ell(\lambda)},\qquad L_\ell^R(\lambda) = \ev{L_\ell^R(\lambda)} \oplus \od{L_\ell^R(\lambda)}.
%\end{align*}
The top spaces of these direct summands are naturally modules over $\sll_2\subset \osp_{1|2}$.
By using the conformal weights of the top spaces of $L_\ell(\lambda)$ and $L_\ell^R(\lambda)$, respectively given by
$$h_\lambda = \frac{\lambda(\lambda+1)}{4(\ell+\frac{3}{2})},\qquad 
h^R_\lambda = \frac{(\lambda+\frac{1}{2})(\lambda+\frac{3}{2})}{4(\ell+\frac{3}{2})} -\frac{1}{8},$$
