On the other hand, the $r$-free fermion vertex superalgebra $\mathcal{F}^r$ decomposes into
\begin{align*}
    \mathcal{F}^r\simeq L_1(0) \oplus L_1(\varpi_1)
\end{align*}
as a $L_1(\so_{r})$-module. 

The integer lattice $U=\mathbb Z \epsilon_1 \oplus \dots \oplus  \mathbb Z \epsilon_n$ equipped with the bilinear form such that $(\epsilon_i, \epsilon_j) = \delta_{i, j}$ provides a convenient realization for some data of $\so_r$:
\begin{itemize}
    \item (Type $D$) $r=2s$:
    \begin{align*}
        \alpha_i=\begin{cases}
            \epsilon_i - \epsilon_{i+1} & (1\leq i \leq s-2)\\
            \epsilon_{s-1} - \epsilon_{r'} & (i=s-1)\\
            \epsilon_{s-1} + \epsilon_{r'} & (i=s)
            \end{cases},\quad 
        \omega_i=\begin{cases}
            \epsilon_1+\cdots + \epsilon_{i}  & (1\leq i \leq s-2)\\
           \frac{1}{2}(\epsilon_1 + \dots + \epsilon_{s-1}-\epsilon_s) & (i=s-1)\\
            \frac{1}{2}(\epsilon_1 + \dots + \epsilon_{s-1}+\epsilon_s) & (i=s)
            \end{cases},
    \end{align*}
    and the highest root $\theta$ and the Weyl vector $\rho$ are respectively
    $$\theta = \epsilon_1+\epsilon_2,\qquad \rho = (s-1) \epsilon_1 + (s-2)\epsilon_2 + \dots + \epsilon_{s-1}.$$
    \item (Type $B$) $ r=2s+1$:
    \begin{align*}
        \alpha_i=\begin{cases}
            \epsilon_i - \epsilon_{i+1} & (1\leq i \leq s-1)\\
            \epsilon_{s} & (i=s)
            \end{cases},\quad 
        \omega_i=\begin{cases}
            \epsilon_1+\cdots +\epsilon_{i}  & (1\leq i \leq s-1)\\
            \frac{1}{2}(\epsilon_1 + \dots + \epsilon_{s-1}+\epsilon_s) & (i=s)
            \end{cases},
    \end{align*}
    and the highest root $\theta$ and the Weyl vector $\rho$ are respectively
    $$\theta = \epsilon_1+\epsilon_2,\qquad \rho = \tfrac{1}{2}\left( (2s-1) \epsilon_1 + (2s-3)\epsilon_2 + \dots + \epsilon_{s}\right).$$
\end{itemize}

Depending on the parity of $N=2n, 2n+1$ and thus $r=2n-4,2n-3$, the complete set of simple ordinary $L_1(\so_{r})$-modules is given by (see for instance \cite{Kac}):
\begin{itemize}
    \item (Type $D$) $N=2n$:
    $$\irr{}{L_1(\so_{r})}=\obj{L_1(0), L_1(\omega_1), L_1(\omega_{n-3}), L_1(\omega_{n-2})},$$
    whose conformal dimensions are $h_0=0$, $h_1=\frac{1}{2}$, $h_{n-3}=\frac{n-2}{8}$, $h_{n-2}=\frac{n-2}{8}$, respectively.
    \item (Type $B$) $N=2n+1$:
    $$\irr{}{L_1(\so_{r})}=\obj{L_1(0), L_1(\omega_1), L_1(\omega_{n-2})},$$
    whose conformal dimensions are $h_0=0$, $h_1=\frac{1}{2}$, $h_{n-2}= \frac{2n-3}{16}$, respectively.
\end{itemize}
Then $\mathcal{F}^r$ admits a unique simple ordinary local module $\mathbb{L}$ and a unique simple ordinary Ramond twisted module $\mathbb{L}^R$, whose parity decompositions are
\begin{align*}
    \mathbb{L}=L_1(0)\oplus L_1(\omega_1),\qquad \mathbb{L}^R=\begin{cases} L_1(\omega_{n-3})\oplus L_1(\omega_{n-2}) & (N=2n),\\    L_1(\omega_{n-2}) \oplus L_1(\omega_{n-2})& (N=2n+1). \end{cases}
\end{align*}

Now, we introduce the following simple $\W_{-1}(\so_{N},\minO)$-modules
\begin{align*}
      &\mathbb{L}^+(\lm)=\ev{(L_\ell(\lm)\otimes \mathbb{L}) },
      &&\mathbb{L}^-(\lm)=\od{(L_\ell(\lm)\otimes \mathbb{L}) },  \\
      &\mathbb{L}^{+}_R(\lm)=\ev{(L^R_\ell(\lm)\otimes \mathbb{L}^R) },  &&\mathbb{L}^{-}_R(\lm)=\od{(L^R_\ell(\lm)\otimes \mathbb{L}^R) }. 
\end{align*}
The classification of the simple $\W_{-1}(\so_{N},\minO)$-modules is now straightforward by using \eqref{constructing simple modules}.
\begin{theorem}\label{Classification of simples via orbifolds}
The complete set of simple $\W_{-1}(\so_{N},\minO)$-modules is given by 
\begin{itemize}
    \item (Type $D$) $N=2n$:
    $$\mathrm{Irr}=\obj{\mathbb{L}^+(\lm),\mathbb{L}^-(\lm) \mid  \lambda=0,1,\dots, n-3}\cup \obj{\mathbb{L}^+_R(\lm), \mathbb{L}^-_R(\lm)\mid  \lambda=0,1,\dots, n-3}.$$
    \item (Type $B$) $N=2n+1$:
    $$\mathrm{Irr}=\obj{\mathbb{L}^+(\lm),\mathbb{L}^-(\lm)\mid  \lambda=0,1,\dots, 2n-3}\cup \obj{\mathbb{L}^{-}_R(\lm)\mid  \lambda=0,1,\dots, 2n-4}.$$
\end{itemize}
\end{theorem}
Note that in the type $B$ case, we have $\mathbb{L}^{+}_R(\lm)\simeq \mathbb{L}^{-}_R(\lm)$ as $\W_{-1}(\so_{N},\minO)$-modules since $\mathbb{L}^R_{\overline{0}}\simeq \mathbb{L}^R_{\overline{1}}\simeq L_1(\varpi_{n-2})$.
