The simple $\W_{-1}(\so_{N},\minO)$-modules in Theorem \ref{Classification of simples via orbifolds} can be realized via the BRST reduction.
\begin{proposition}\label{simples via reduction}
There are isomorphisms of $\W_{-1}(\so_{N},\minO)$-modules
\begin{itemize}
    \item (Type $D$) $N=2n$:
    \begin{align*}
    &\mathbb{L}^+(\lm)\simeq \HH_{\OO}^0(L_{-1}(\lm \omega_1)),&
    &\mathbb{L}^-(\lm)\simeq \ccases{\HH_{\OO}^0(L_{-1}(\omega_3))}{(\lm=0)}{\HH_{\OO}^0(L_{-1}( (\lm-1)\omega_1+\omega_2))}{(\lm\neq0)},\\
    &\mathbb{L}^+_R(\lm)\simeq \HH_{\OO}^0(L_{-1}(\lm \omega_1+\omega_{n-1})),&
    &\mathbb{L}^-_R(\lm)\simeq  \HH_{\OO}^0(L_{-1}(\lm \omega_1+\omega_n)). 
    \end{align*}
    \item (Type $B$) $N=2n+1$:
    \begin{align*}
    &\mathbb{L}^+(\lm)\simeq \HH_{\OO}^0(L_{-1}(\lm \omega_1)),&
    &\mathbb{L}^-(\lm)\simeq \ccases{\HH_{\OO}^0(L_{-1}(\omega_3))}{(\lm=0)}{\HH_{\OO}^0(L_{-1}( (\lm-1)\omega_1+\omega_2))}{(\lm\neq0)},\\
    &&&\mathbb{L}^-_R(\lm)\simeq  \HH_{\OO}^0(L_{-1}(\lm \omega_1+\omega_n)).
    \end{align*}
\end{itemize}
\end{proposition}

\proof
For a dominant integral weight $\Lambda=\lm_1 \omega_1+\cdots + \lm_n \omega_n$ with $\lm_i\in \Z_{\geq0}$, $\widehat{\Lambda}(\alpha_0^\vee)=-(\Lambda,\theta)-1\notin \Z_{\geq0}$ holds.
Theorem \ref{A05: minimal reduction} implies that $\mathbb{L}^\pm(\lm)\simeq \HH_{\OO}^0(L_{-1}(\Lambda))$ (or $\mathbb{L}^\pm_R(\lm)\simeq \HH_{\OO}^0(L_{-1}(\Lambda))$), for a certain dominant integral weight $\Lambda$, if and only if the highest weights and conformal weights of the top spaces of both-hand sides are the same, \ie\
$$\text{(I)}\quad  \rho_{\Lambda^\sharp}\simeq \rho^{\mathrm{top}},\qquad \text{(II)}\quad h^\sharp_\Lambda=\Delta^{\mathrm{top}}.$$
We do this case-by-case, using Table \ref{simple modules vira orbifold}, \eqref{conformal weights D} and \eqref{conformal weights B}, and 
\begin{align*}
    \Lambda^\sharp|_{\sll_2}=\lm_1 \omega,\qquad \Lambda^\sharp|_{\so_{N-4}}=\lambda_3 \omega_1 + \dots + \lambda_n \omega_{n-2}.
\end{align*}
\begin{itemize}[leftmargin=12pt]\setlength{\itemsep}{10pt}
    \item (Type $D$) $N=2n$:
\begin{enumerate}
    \item[(1)] $\mathbb{L}^+(\lm)$ with $0\leq \lm \leq n-3$:

    (I) implies $\Lambda = \lambda \omega_1 + \lambda_2 \omega_2$, and then (II) does $\lm_2=0$, \ie\ $\Lambda=\lm \omega_1$.

    \item[(2-1)] $\mathbb{L}^-(\lm)$ with $1\leq \lm \leq n-3$:

    (I) implies $\Lambda = (\lambda-1)\omega_1 + \lambda_2\omega_2$, and then (II) does $\lm_2=1$, \ie\ $\Lambda=(\lambda-1)\omega_1 + \omega_2$. 

    \item[(2-2)] $\mathbb{L}^-(\lm)$ with $\lm=0$:

   (I) implies $\Lambda =  \lambda_2\omega_2 + \omega_3$, and then (II) does $\lm_2=0$, \ie\ $\Lambda=\omega_3$.

    \item[(3)] $\mathbb{L}^+_R(\lm)$ with $1\leq \lm \leq n-3$:

    (I) implies $\Lambda = \lambda \omega_1 + \lambda_2 \omega_2 + \omega_{n-1}$, and then (II) does $\lm_2=0$, \ie\ $\Lambda=\lambda \omega_1 + \omega_{n-1}$.

    \item[(4)] $\mathbb{L}^-_R(\lm)$ with $1\leq \lm \leq n-3$:

    (I) implies $\Lambda = \lambda \omega_1 + \lambda_2 \omega_2 + \omega_{n}$, and then (II) does $\lm_2=0$, \ie\ $\Lambda= \lambda \omega_1 + \omega_{n}$. 
\end{enumerate}
\item (Type $B$) $N=2n+1$:
\begin{enumerate}
    \item[(1)] $\mathbb{L}^+(\lm)$ with $0\leq \lm \leq 2n-3$:

   (I) implies $\Lambda = \lambda \omega_1 + \lambda_2 \omega_2$, and then (II) does $\lm_2=0$, \ie\ $\Lambda=\lm \omega_1$.

    \item[(2-1)] $\mathbb{L}^-(\lm)$ with $1\leq \lm \leq 2n-3$:

    (I) implies $\Lambda = (\lambda-1)\omega_1 + \lambda_2\omega_2$, and then (II) does $\lm_2=1$, \ie\ $\Lambda=(\lambda-1)\omega_1 + \omega_2$.

    \item[(2-2)] $\mathbb{L}^-(\lm)$ with $\lm=0$:

    (I) implies $\Lambda =  \lambda_2\omega_2 + \omega_3$, and then (II) does $\lm_2=0$, \ie\ $\Lambda=\omega_3$.

