\endproof

\appendix
\section{Categorical aspects of vertex superalgebras}\label{appendix}
Let $V$ be a simple vertex algebra equipped with a conformal vector and $\sC$ a vertex tensor category of $V$-modules. Hence, $\sC$ is a braided tensor category with a tensor product $\boxtimes$ and a unit $\one$. The associators and the braidings are respectively denoted by 
$$\mathcal{A}_{X,Y,Z}\colon X \boxtimes(Y \boxtimes Z)\simeq (X \boxtimes Y) \boxtimes Z,\quad \mathcal{B}_{X,Y}\colon X \boxtimes Y \simeq Y \boxtimes X.$$

Let $A=\ev{A}\oplus \od{A}$, with $\ev{A}=V$, be a simple vertex superalgebra in $\sC$. 
Then $J=\od{A}$ is a simple current, \ie\ a simple $V$-module such that $J \boxtimes J \simeq \one$. 
Indeed, $A$ is naturally identified with a commutative algebra object $\ub{A}=(\one, J)$ in the larger category  $\ub{\sSC}$ defined as
the braided tensor \emph{super}category 
whose objects are pairs $\bX=(X_0, X_1)$ in $\sC\times\sC$ -- the parity decomposition of $\bX$\ -- with even morphisms $f\colon \bX\rightarrow \bY$, 
$$f=(f_0, f_1),\qquad f_0: X_0 \rightarrow Y_0,\quad f_1: X_1 \rightarrow Y_1.$$
The unit in $\ub{\sSC}$ is $\ub{\one}=(\one,0)$, the tensor product is again $\boxtimes$ preserving the parity,
$$\bX\boxtimes\bY=(X_0\boxtimes Y_0\oplus X_1\boxtimes Y_1,X_0\boxtimes Y_1\oplus X_1\boxtimes Y_0),$$
and the braiding is modified to respect the parity,
$$\mathcal{B}_{\bX,\bY}\colon \bX \boxtimes \bY \simeq \bY \boxtimes \bX,\quad \mathcal{B}_{\bX,\bY}|_{X_p\boxtimes Y_q} =(-1)^{p q} \mathcal{B}_{X_p,Y_q}.$$

Following \cite{CKL, CKM}, denote by $\ub{\sSC}_A$ the category of $\ub{A}$-module objects lying in $\ub{\sSC}$ equipped with parity-preserving morphisms. 
The objects in $\ub{\sSC}_A$ are pairs $(\bX, m_\bX)$ with $\bX$ in $\ub{\sSC}$ equipped with a structure map
$$m_\bX: \ub{A} \boxtimes \bX \rightarrow \bX$$
satisfying compatibility conditions with the multiplication $\mu\colon \ub{A} \boxtimes \ub{A} \rightarrow \ub{A}$.
The morphisms ${f: \bX \rightarrow \bY}$ in $\ub{\sSC}_A$ are those in $\ub{\sSC}$ that commute with the structure maps, \ie\ $m_\bY \circ (\text{id}_{\ub{A}} \boxtimes f) = f \circ m_\bX$. 

Since $J \boxtimes J \simeq \one$, {arbitrary $\ub{\sSC}_A$-modules are direct sums of two objects $\bX \oplus \bY$} satisfying the following properties:
\begin{equation*}
\vcenter{\xymatrix@R=1em{ \ub{J} \boxtimes \bX  \ar[rr]^-{\mathcal{M}_{\ub{J},\bX}} \ar[rd]_{m_\bX}&& \ub{J} \boxtimes \bX   \ar[ld]^{m_\bX} &\ub{J} \boxtimes \bY  \ar[rr]^-{(-1)^\bullet \mathcal{M}_{\ub{J},\bY}} \ar[rd]_{m_\bY}&& \ub{J} \boxtimes \bY   \ar[ld]^{m_\bY}\\ & \bX & && \bY &.}}
\end{equation*}
where $\ub{J}=(0,J)$, $\mathcal{M}_{\ub{J},\bullet}=\mathcal{B}_{\bullet,\ub{J}}\circ \mathcal{B}_{\ub{J},\bullet}$ is the monodromy, and $(-1)^\bullet$ denotes the parity.
The objects satisfying the first property are called the local (or Neveu-Schwarz) $\ub{A}$-modules corresponding to modules over the vertex superalgebra $A$, while the objects satisfying the second property are called twisted (or Ramond) $\ub{A}$-modules. Thus, $\ub{\sSC}_A$ decomposes into two full subcategories 
\begin{align*}
    \ub{\sSC}_A=\ub{\sSC}_A^{\mathrm{loc}} \oplus \ub{\sSC}_A^{\mathrm{tw}},
\end{align*}
consisting of local $\ub{A}$-modules and twisted $\ub{A}$-modules. 
By \cite{CKM}, $\ub{\sSC}_A$ is a tensor (super)category and $\ub{\sSC}_A^{\mathrm{loc}}$ is a braided tensor category.

Note that we have an induction functor
$$
\mathcal F: \sC \rightarrow \ub{\sSC}_A,\qquad
X \mapsto (\ub{A} \boxtimes (X, 0), \mu \boxtimes (\id_X, 0)), \qquad
f \mapsto \id_{\ub{A}} \boxtimes (f, 0),
$$
whose right adjoint is the forgetful functor $\mathcal G: \ub{\sSC}_A \rightarrow \sC$. 
In particular, Frobenius reciprocity holds
\begin{align*}
    \Frob_{\mathcal F(X), (\bY, m_\bY)}:\Hom_{\ub{\sSC}_A}(\mathcal F(X), (\bY, m_\bY))\overset{\simeq}{\longrightarrow}
\Hom_{\ub{\sSC}}((X, 0), \bY) \simeq 
\Hom_{\sC}(X, Y_0).
\end{align*}

\begin{theorem}\label{classification of simples}
Let $A=V \oplus J$ be a simple vertex superalgebra in a braided tensor category $\sC$ of $V$-modules as above. Then, the induction functor  $\mathcal F: \sC \rightarrow \ub{\sSC}_A$ gives an equivalence of tensor categories. Thus, there is an bijection on the sets of inequivalent simple objects $\mathrm{Irr}(\sC)\simeq \mathrm{Irr}(\ub{\sSC}_A)$.
\end{theorem}
\proof
It suffices to show that $\mathcal{F}$ is fully faithful and essentially surjective.
The former follows from Frobenius reciprocity $\Frob_{\mathcal F(X), \mathcal F(Y)}$:
\[
\Hom_{\ub{\sSC}_A}(\mathcal F(X), \mathcal F(Y))
\simeq\Hom_{\ub{\sSC}}((X, 0), \ub{A} \boxtimes (Y, 0))
\simeq\Hom_{\sC}(X, Y). 
\]
Let us show the latter. Take an $A$-module $(\bX, m_\bX)$ in $\ub{\sSC}_A$. We show the canonical map 
$$\Frob_{\mathcal F(X), (\bX, m_\bX)}^{-1}(\id_{X_0})\colon \mathcal{F}(X_0)\rightarrow \bX$$
is an isomorphism, that is $m_\bX \colon J\boxtimes X_0\rightarrow X_1$ is an isomorphism.
Indeed, the associativity of the structure map $m_\bX: \ub{A} \boxtimes \bX \rightarrow \bX$ restricted to $\ub{J} \boxtimes (\ub{J} \boxtimes \bY)\subset \ub{A} \boxtimes (\ub{A} \boxtimes \bY)$ with $\ub{J} = (0, J)$ gives the following commutative diagram:
\begin{equation}
\vcenter{\xymatrix{ \ub{J} \boxtimes (\ub{J} \boxtimes \bX)  \ar[rr]^-{\mathcal A}_\simeq \ar[d]_{\id \boxtimes m_\bX}&& (\ub{J} \boxtimes \ub{J}) \boxtimes \bX \ar[rr]^-{\mu \boxtimes \id}_\simeq && \ub{\mathbf 1} \boxtimes \bX \ar[d]^{m_\bX}_\simeq    \\ \ub{J} \boxtimes \bX \ar[rrrr]_-{m_\bX }&&&& \bX.}}
\end{equation}
Hence $m_{\bX}\circ(\id\boxtimes m_{\bX})\colon\ub{J} \boxtimes (\ub{J} \boxtimes \bX)\to\bX$ is an isomorphism and so is $m_{\bX}\colon J\boxtimes \bX\to \bX$ 
%$$m_\bX\colon \ub{J} \boxtimes \bX \hookrightarrow \bX,\quad m_\bX \colon \ub{J} \boxtimes \bX \twoheadrightarrow \bX $$
(the injectivity follows from $J\boxtimes J \simeq \one$). 
Since $\bX=(X_0,X_1)$, it follows 
\begin{align*}
        m_\bX\colon J\boxtimes X_0\xrightarrow{\simeq} X_1,\quad J\boxtimes X_1\xrightarrow{\simeq} X_0
\end{align*}
as desired. 
\endproof

Here, we record a nice criterion regarding the category $\sC(\g, k)$ of ordinary modules over simple affine vertex algebras $L_k(\g)$.
Recall that a tensor category $\sC$ is said of moderate growth if each indecomposable object $X$ satisfies $\dim \End(X^{\boxtimes n}) < n!$ for some $n\in\Z_{>0}$, and called an $r$-category if for every object $X$, the functor $\Hom_\sC(\bullet \boxtimes X, \one)$ is represented by some object $X^*$, giving rise to an equivalence $\sC \xrightarrow{\simeq}\sC^{mop},\ X\mapsto X^*$, to the tensor and arrows opposite category $\sC^{mop}$, see \cite{EP} and references therein.

\begin{theorem} \label{thm: general theorems from literature}
\phantom{x}
\begin{enumerate}[left=\itemindent]
    \item \textup{\cite[Theorem 2.12]{ALSW}}
Let $V$ be a simple, self-dual vertex algebra with a conformal vector and $\sC$ be a vertex tensor category of $V$-modules. If $\sC$ is closed under the contragredient dual, then $\sC$ is an $r$-category. 
\item \textup{\cite[Corollary 1.3]{EP}} Every semisimple braided $r$-category of moderate growth is rigid. 
\end{enumerate}
\end{theorem}
\begin{corollary}\label{cor:FTC}
For a simple Lie (super)algebra $\g$, let $\sC(\g, k)$ be the category of ordinary $L_k(\g)$-modules at non-critical level $k$. If $\sC(\g, k)$ is finite and semisimple, then it is a vertex ribbon category.
\end{corollary}
\begin{proof}
By assumption, $\sC(\g, k)$ is semisimple and thus forms a vertex tensor category by \cite[Corollary 3.4.5]{CY}. Thanks to the general property of vertex tensor categories, $\sC(\g, k)$ is a balanced braided tensor category with twist given by $e^{2\pi i L_0}$ where $L_0$ is the zero-mode of the conformal vector. Thus, it suffices to show that $\sC(\g, k)$ is rigid. It is clear that $L_k(\g)$ and $\sC(\g, k)$ satisfy the assumptions of Theorem \ref{thm: general theorems from literature} (1), $\sC(\g, k)$ is an $r$-category and, thus, it suffices to show that $\sC(\g, k)$ is of moderate growth by Theorem \ref{thm: general theorems from literature} (2). 

As $\sC(\g, k)$ is finite, let $M_1, \dots, M_r$ be the complete set of simple ordinary $L_k(\g)$-modules and $N_{i, j}^{\ \ \ell}$ be the fusion rules, \ie\
    \[
    M_i \boxtimes M_j \simeq \bigoplus_{\ell =1}^r N_{i, j}^{\ \ \ell} M_\ell.
    \]
    Set $m =r \cdot \text{max}\{ (N_{i, j}^{\ \ \ell})^2 | 1 \leq i, j, \ell \leq r \}$. By Schur's Lemma, it follows that $\dim\End(M_i \boxtimes M_j) = \sum_{\ell = 1}^r (N_{i, j}^{\ \ \ell})^2 \leq m$. By induction, we find that $\dim\End(M_{i_1} \otimes \dots \otimes M_{i_n})\leq m^{n-1}$. Since $m^{n-1}< n!$ holds for large enough $n$, one has 
    $\dim\End(M_i^{\otimes n}) < n!$ for some $n$, \ie\ $M_i$ is of moderate growth. This completes the proof.
\end{proof}

