\section{Density profile of unprocessed gas}
\label{app:density}

\citet{2013A&A...549A.132P} proposed a semi-analytical model in which a star cluster is formed from a centrally concentrated spherically symmetric gas cloud with constant SFE per free-fall time $\epsilon_{\text{ff}}$. The overall density profile $\rho_0(r)$ does not change, where $r$ is the distance from the center of the cluster. As stars form, the gas profile $\rho_\mathrm{gas}(r,t)$ and the star profile $\rho_\star(r,t)$ change depending on the evolution time $t$, but must satisfy the constraint
\begin{equation}
\rho_0(r) = \rho_{\text{gas}}(r,t) + \rho_{\star}(r,t).
\end{equation}
\citet{2013A&A...549A.132P} derive the gas and stellar profile evolution to be
\begin{equation}
\label{eq:rho_gas_app}
\rho_{\text{gas}}(t, r) = \left( \rho_0(r)^{-1/2} + \sqrt{\frac{8G}{3\pi}} \epsilon_{\text{ff}} t \right)^{-2},
\end{equation}
\begin{equation}
\label{eq:rho_star_app}
\rho_{\star}(t, r) = \rho_0(r) - \rho_{\rm gas}(r, t),
\end{equation}
where $G$ is the gravitational constant. \citet{Bek+2017} rewrote the constraint for a given density profile of the formed star cluster $\rho_{\star}(r)$,
\begin{equation}
\rho_0(r, t_{\text{SF}}) = \rho_{\text{gas}}(r, t_{\text{SF}}) + \rho_{\star}(r).
\end{equation}
In this formulation, the gas profile $\rho_{\text{gas}}$ and the total density profile $\rho_{0}$ depend on the star formation duration $t_{\text{SF}}$ and are calculated using Eqs. (\ref{eq:rho_gas_app}) and (\ref{eq:rho_star_app}), which results in 
\begin{equation}
    \rho_{\text{gas}} = \frac{1}{k^2} - \frac{\rho_{\star}}{2} - \frac{1}{2} \sqrt{K_2 + \frac{8}{k^6 K_1}} + K_1,
\end{equation}
where 
\begin{equation}
 K_0 = \frac{3 \sqrt{\alpha^3 + 36\alpha^2 + 216\alpha + 24 \alpha \sqrt{3(\alpha + 27)}}}{3(\alpha + 27)}, \quad \alpha = k^4 \rho_{\star}^2, \quad k = \sqrt{\frac{8G}{3\pi} } \epsilon_{\text{ff}} t_{\text{SF}}, \nonumber
\end{equation}
and 
\begin{equation}
K_1 = \frac{\sqrt{\alpha^2 + \alpha (K_0 + 24) + K_0 (K_0 + 12)}}{12 k^4 K_0}, \quad K_2 = \frac{(\alpha - K_0 + 24)(K_0 - \alpha)}{3 k^4 K_0}. \nonumber
\end{equation}

