\subsection{Theory}\label{sec::theory}
% In this section, we list examples of rank transformations $\psi$ for which the private Siegel--Tukey test statistic exhibits asymptotic normality. 
We now present some theoretical results concerning the RPST tests. 
The first result shows that the RPST tests are differentially private. 
\begin{theorem} \label{thm::privacy}
For all $n_1,n_2\geq 1$, $Q\in \{0\}\cup [n-1]$, strictly-increasing, non-negative functions $\psi: \nats \rightarrow \reals$, the pair $(\widetilde U_1, \widetilde\sigma^2)$ are jointly $(\eps_U+\eps_d,\delta)$-differentially private. 
\end{theorem}
The proof Theorem~\ref{thm::privacy} is given in Appendix~\ref{sec::proofs}. Theorem~\ref{thm::privacy} guarantees that all versions of the RPST test are differentially private. 
Our next result concerns the asymptotic distribution of the test statistic under the null hypothesis.  
For this result, we need a few conditions. 
\begin{condition}\label{cond::group_sizes}
There exists $\lambda \in (0, 1)$ such that $\frac{n_1}{n} \rightarrow \lambda$ as $n\to \infty$.
\end{condition}
Condition \ref{cond::group_sizes} says that the groups sizes are bounded away from zero, or, one group size is not asymptotically dominating another. This is a relatively standard assumption in rank testing. We now introduce another condition. 
\begin{condition}\label{cond::strong}
Let $\psi\colon \re^+\to \re^+$ be a continuous, strictly increasing, positive, real-valued function on $\re^+$, such that $\psi(n)=O(n^k)$ for any $k>0$ and $\psi(0)=0$. 
% such that there exists $N \in \nats$, $x_0 > 0$, $1 < L \leq U < \infty$ and $\beta \in (0, 1)$ such that for all integers $n \geq N$, either $\bar\psi \geq \psi(\beta n) $ or $\bar\psi \leq \psi(\beta n) $ and for all $x \geq x_0$
%         \begin{align}
%  L \leq \frac{\psi(x/\sqrt{\beta})}{\psi(x)} \leq U. \label{eqn::psicond1-1}
% % \label{eqn::psicond1-1}
% \end{align}
\end{condition}
% To interpret the restriction $\bar\psi \geq \psi(\beta n) $ or $\bar\psi \leq \psi(\beta n) $, let $q = 0$ and consider the ranks that are assigned to the data points of a sample of size $n$ (assuming no ties):
% \begin{align*}
%     \psi(1), \psi(2), \dots, \psi(n - 1), \psi(n).
% \end{align*}
Condition~\ref{cond::strong} gives a sufficient condition on $\psi$ for asymptotic normality of $U_1$ under the null hypothesis. 
Condition~\ref{cond::strong} is satisfied for increasing functions which pass through the origin, and do not grow faster than some polynomial. 
For instance, Condition~\ref{cond::strong} is satisfied for $\psi(x)$ being any of $x,\log(x+1)$ or $x^k$. 
% We can elaborate on Condition~\ref{cond::strong} as follows. 
% The restriction $\bar\psi \geq \psi(\beta n) $ or $\bar\psi \leq \psi(\beta n) $ stipulates that we must eventually be able to bound the mean of the transformed ranks either above or below by a certain percentile of the transformed ranks themselves. Essentially, $\psi(i)$ cannot simultaneously be ``too'' large for $i$ close to $Q$ and ``too'' small for $i$ close to 0. The restriction \eqref{eqn::psicond1-1} states that when we multiply the input of $\psi$ by $1/\sqrt{\beta}$, we should be able to bound the (multiplicative) effect on the output, both above and below. 
% Essentially, $\psi$ cannot grow too fast or too slow. To see this, observe that $\psi(x) = e^x$ exhibits too fast a growth rate, while $\psi(x) = 1 - \frac{1}{x + 1}$ is too slow, and $\psi(x) = x^k$ for $k>0$ is acceptable. We will see later that convex and concave polynomials meet Condition~\ref{cond::strong}, see Condition~\ref{cond::polynomial}. 
Condition~\ref{cond::strong} can also be weakened, see Condition~\ref{cond::psi} in the appendix. However, the weaker condition is very opaque, whereas Condition~\ref{cond::strong} is very straightforward. 
We now present our main theorem, which gives the distribution of the test statistic under the null hypothesis. 
%%%%%%%%%%%%
\begin{theorem}\label{thm::main-result}
Let $Q\in \{0\}\cup [n-1]$ be the number of central data points to truncate. Suppose that Conditions \ref{cond::problem}--\ref{cond::strong} hold, as well as $H_0$ holds, as given in \eqref{eqn::hyp}. 
For all $\eps,\delta>0$, it holds that
\begin{equation*}
    \frac{\widetilde U_1}{\sigma(\widetilde n_1,\widetilde n_2,\psi,Q)} \cond \cN(0, 1) \text{.}
\end{equation*}    
\end{theorem}
The proof of this Theorem~\ref{thm::main-result} is given in Appendix~\ref{sec::proofs}.  
Theorem~\ref{thm::main-result} gives the limiting distribution of the test statistic, which yields that it suffices to use the distribution $\cN(0, \sigma^2(\widetilde n_1,\widetilde n_2,\psi,Q))$ as the reference distribution for computing the $p$-values. 

\begin{remark}\label{rem::ties}[Relaxing the absolute continuity assumption]
If $F$ and $G$ are not absolutely continuous, then the data may contain repeated observations. In that case, a small amount of noise can be added to the data in order to obtain data without repeated observations. In that case, it is obvious that the global sensitivity of the test statistic remains the same. In addition, the asymptotic distribution under the null hypothesis will also remain unchanged, and so the test can be applied without changes. The only hiccup is to ensure that the magnitude of noise is small enough so that the order of the non-repeated observations stays the same, which can be chosen based on domain knowledge. 
