\subsection{The privacy of the test}
We now, prove the privacy of the test, which follows mainly from the following lemma: 
\begin{lemma} \label{lem::rtpmstsens}
% Let $\psi$, $Q$ and $U_1$ be defined as in theorem \ref{thm::rtpmstasymp}.
It holds that for all $Q\in \{0,\ldots,n\}$, and all increasing, non-negative real functions $\psi$, 
\begin{align*}
      \GS(U_1)\leq   \max \left\{\psi(n - Q), \psi(n - Q) + \psi(n - Q - 1) - \bar\psi_Q  \right\}.
    \end{align*}
    % where $M = \frac{1}{n} \left(Q \psi(0) + \sum_{i = 1}^n \psi(i) \right)$.
\end{lemma}
\noindent We will prove this lemma following the proof of Theorem~\ref{thm::privacy}.

\begin{proof}[Proof of Theorem~\ref{thm::privacy}]
From Lemma~\ref{lem::rtpmstsens} and Theorem~\ref{thm::lapmech}, we have that $\widetilde U_1$ is $\eps_U$-differentially private. Furthermore, the properties of the Laplace distribution directly yield that $d_1^*$ is $(\eps_d,\delta)$-differentially private, see also Theorem A.6 of \cite{couch2019differentially}, with the oversight corrected as given in Appendix~\ref{app::Correction}. 
Lastly, basic composition (Theorem~\ref{thm::comp}) gives the final result. 
\end{proof}
In order to prove Lemma~\ref{lem::rtpmstsens}, we first prove a simpler theorem, a bound on the global sensitivity of $U_1$ when $Q=0$. 
\begin{lemma}\label{thm::rtstsens}
% Let $\psi$ and $U_1$ be defined as in theorem \ref{thm::rtstasymp}. 
It holds that
    \begin{align*}
       \GS(U_1(\psi,0))\leq  \max \left\{\psi(n) - \psi(1), \psi(n) + \frac{1}{n} \sum_{i = 1}^n  \psi(i) - \psi(1) - \psi(2)\right\} \text{.}
    \end{align*}
\end{lemma}
\begin{proof} % The structure of the proof resembles that of the proof without rank transformation. Modify it for the case with rank transformation. Also write down a sensitivity proof for the ``base'' private Siegel--Tukey test (w/o RT or PM)
    The following proof is similar in spirit to that of Theorem 4.1 of \cite{couch2019differentially} in form. However, since ranks are assigned differently, we will require new arguments. 

    Consider two neighboring databases $\mathbf{x}$ and $\mathbf{x'}$.
    Arrange the data points in database $\mathbf{x}$ as follows: $X_1, X_2, \dots, X_{n_1}, Y_1, Y_2, \dots, Y_{n_2}$. Label these arranged data points $Z_1, Z_2, \dots, Z_n$, in order from least to greatest. Denote by $w_i$ the ``raw rank'' of the $i$th data point in this sequence, $i \in \{1, 2, \dots, n_1 + n_2 = n\}$. From there, let $r(w, n)$ be the map from the ``raw ranks'' to the ``working ranks'' (i.e., the ranks used in the rank-transformed Siegel--Tukey testing procedure), and let $r_i$ denote the ``working rank'' of data point $i$. Do the same for database $\mathbf{x'}$ and denote the corresponding quantities with the same notation, except with an apostrophe (ex., the ``working ranks'' of database $x'$ will be denoted $w'_i$). 

    Suppose the data point with $w_i = p$ from database $\mathbf{x}$ is changed to become the data point with $w'_i = q$ in database $\mathbf{x'}$. Without loss of generality, we may assume that $p \leq q$. Divide the rest of the data points in database $\mathbf{x}$ into four regions as follows, depending on the case. Let $h$ be the raw rank of the data point with the highest working rank (this will depend on $n$). Note that $r(h, n) = \psi(n)$. When $p \leq h$ and $q > h$, the regions are:

    \begin{itemize}
        \item Region $A_1$, consisting of the data points with $w_i < p$;
        \item Region $A_2$, consisting of the data points with $p < w_i \leq h$;
        \item Region $A_3$, consisting of the data points with $h < w_i < q$; and
        \item Region $A_4$, consisting of the data points with $w_i > q$.
    \end{itemize}

    When $p, q \leq h$ or $p, q > h$, the regions are:

    \begin{itemize}
        \item Region $A_1$, consisting of the data points with $w_i < p$;
        \item Region $A_2$, consisting of the data points with $p < w_i < q$; and
        \item Region $A_3$, consisting of the data points with $w_i > q$.
    \end{itemize}

    Now define:

    \begin{align*}
        b_j = \sum_{i: Z_i \in \bfX_{n_1}, w_i \in A_j} (r_i - r'_i),
    \end{align*}
    where $\bfX_{n_1}$ consists of all the data points in group 1 (i.e., the $X$ points). Armed with this notation, we are now ready to conduct the case analysis.

    \hfill\newline
    \noindent \textbf{Case 1: The Changed Row Retains its Group}
    \paragraph{Case 1a: $p, q \leq h$}
    Suppose without loss of generality that the changed row is from group 1. Let us first bound the sensitivity of $U_1$. As in \cite{couch2019differentially}, we decompose the sensitivity into the sum of three effects:
    \begin{enumerate}
        \item The removal of the row with raw rank $p$ from database $\mathbf{x}$, which (by itself) decreases $U_1$ by $r(p, n)$. 
        \item The addition of the row (whose raw rank becomes $q$) into database $\mathbf{x'}$, which increases $U_1$ by $r(q, n)$.
        \item The reduction of the raw ranks of the data points in region $A_2$ of database $\mathbf{x}$ by one apiece, which decreases $U_1$ by $|b_2|$ (as working ranks decrease away from the centre).
    \end{enumerate}
    This means that:
    \begin{align*}
        \GS(U_1) \leq |-r(p, n) + r(q, n) - |b_2||.
    \end{align*}
    Since
    \begin{align*}
        r(1, n) = \psi(1) \leq ||b_2| + r(p, n)| \leq r(h, n) - r(1, n) = \psi(n) - \psi(1),
    \end{align*}
    and
    \begin{align*}
        \psi(1) \leq r(q, n) \leq \psi(n) \text{,}
    \end{align*}
    we have that:
    \begin{align*}
        \GS(U_1) \leq \psi(n) - \psi(1) \text{.}
    \end{align*}
    By a similar argument, if it were the case that $p, q > h$, one could obtain the same sensitivity bound. 
    \paragraph{Case 1b: $p \leq h$ and $q > h$}
    Suppose without loss of generality that the changed row is from group 1. Let us first bound the sensitivity of $U_1$. As in \cite{couch2019differentially}, we decompose the sensitivity into the sum of four effects:
    \begin{enumerate}
        \item The removal of the row with raw rank $p$ from database $\mathbf{x}$, which (by itself) decreases $U_1$ by $r(p, n)$. 
        \item The addition of the row (whose raw rank becomes $q$) into database $\mathbf{x'}$, which increases $U_1$ by $r(q, n)$. 
        \item The reduction of the raw ranks of the data points in region $A_3$ of database $\mathbf{x}$ by one apiece, which increases $U_1$ by $|b_3|$ (as working ranks increase toward the centre).
        \item The reduction of the raw ranks of the data points in region $A_2$ of database $\mathbf{x}$ by one apiece, which decreases $U_1$ by $|b_2|$ (as working ranks decrease away from the centre).
    \end{enumerate}
    This means that:
    \begin{align*}
        \GS(U_1) \leq |-r(p, n) + r(q, n) + |b_3| - |b_2||.
    \end{align*}
    Since
    \begin{align*}
        0 \leq ||b_2 + r(p, n)| \leq r(h, n) - r(1, n) = \psi(n) - \psi(1),
    \end{align*}
    and
    \begin{align*}
        0 \leq ||b_3 + r(q, n)| \leq r(h, n) - r(n, n) = \psi(n) - \psi(2) \text{,}
    \end{align*}
    we have that:
    \begin{align*}
        \GS(U_1) \leq \psi(n) - \psi(1) \text{.}
    \end{align*}
    This is the same bound as was achieved in Case 1a. 

    \hfill\newline
    \textbf{Case 2: The Changed Row Switches its Group}
    \paragraph{Case 2a: $p, q \leq h$}
    Suppose, without loss of generality, that the changed data point transfers from group 1 to group 2, and that $p \leq q$. As before, we decompose the sensitivity into the sum of three effects:
    \begin{enumerate}
        \item The removal of the row with raw rank $p$ from database $\mathbf{x}$, which (by itself) decreases $U_1$ by $r(p, n)$.
        \item The reduction of the raw ranks of the data points in region $A_2$ of database $\mathbf{x}$ by one apiece, which decreases $U_1$ by $|b_2|$ (as working ranks decrease away from the centre).
        \item The removal of a row from group 1, which increases $U_1$ by $\frac{1}{n} \sum_{i = 1}^n \psi(i)$.
    \end{enumerate}
    This means that:
    \begin{align*}
        \GS(U_1) \leq \left|-r(p, n) - |b_2| + \frac{1}{n} \sum_{i = 1}^n \psi(i)\right|.
    \end{align*}
    Since
    \begin{align*}
        \psi(1) \leq ||b_2| + r(p, n)| \leq r(h, n) - r(1, n) = \psi(n) - \psi(1),
    \end{align*}
    and $\sum_{i = 1}^n \psi(i) \leq \psi(n)$, we have that $\GS(U_1) \leq \psi(n) - \psi(1)$.
    By a similar argument, the same bound is achieved when $p, q > h$.

    % \hfill\newline
    \paragraph{Case 2c: $p \leq h$ and $q > h$}
    The assumptions remain the same as in case 2a. The sensitivity of $U_1$ can be written as the sum of the following four effects:
    \begin{enumerate}
        \item The removal of the row with raw rank $p$ from database $\mathbf{x}$, which (by itself) decreases $U_1$ by $r(p, n)$. 
        \item The removal of a row from group 1, which increases $U_1$ by $\frac{1}{n} \sum_{i = 1}^n \psi(i)$.
        \item The reduction of the raw ranks of the data points in region $A_3$ of database $\mathbf{x}$ by one apiece, which increases $U_1$ by $|b_3|$ (as working ranks increase toward the centre).
        \item The reduction of the raw ranks of the data points in region $A_2$ of database $\mathbf{x}$ by one apiece, which decreases $U_1$ by $|b_2|$ (as working ranks decrease away from the centre).
    \end{enumerate}
    This means that:
    \begin{align*}
        \GS(U_1) \leq \left|-r(p, n) + \frac{1}{n} \sum_{i = 1}^n \psi(i) + |b_3| - |b_2|\right|.
    \end{align*}
    To make further progress, we will utilize the technique of bounding the expression within the absolute value in two separate cases: when it is positive and when it is negative. This technique is used by \cite{couch2019differentially} to bound the sensitivity of the Mann-Whitney test statistic. When the expression is positive, we have that:
    \begin{align*}
        \GS(U_1) &\leq \frac{1}{n} \sum_{i = 1}^n \psi(i) + |b_3| - r(p, n) - |b_2| \leq \frac{1}{n} \sum_{i = 1}^n \psi(i) + \psi(n) - \psi(2) - \psi(1),
    \end{align*}
    The last line follows from the fact that, $|b_3| \leq \psi(n) - \psi(2)$ and $r(p, n) \leq \psi(1)$.
    If the aforementioned expression is negative, then:
    \begin{align*}
        \GS(U_1) &\leq -\frac{1}{n} \sum_{i = 1}^n \psi(i) - |b_3| + r(p, n) + |b_2| \leq \psi(n) - \psi(1).
    \end{align*}
    The last line follows from the facts that $r(p, n) + |b_2| \leq \psi(n)$ and $\frac{1}{n} \sum_{i = 1}^n \psi(i) \geq \psi(1)$.
    All told,
    \begin{align*}
        \GS(U_1) = \max \left\{\psi(n) - \psi(1), \psi(n) + \frac{1}{n} \sum_{i = 1}^n  \psi(i) - \psi(1) - \psi(2)\right\} \text{.}
    \end{align*}
    This is what we wanted to show.
\end{proof}
