\subsection{The limiting distribution under $H_0$}
We first consider what happens to the ``Laplace'' portion of the test statistic. That is, the term $Z\cdot \GS^*(U_1)/\sigma(n_1, n_2, \psi, Q),$ where $$\GS^*(U_1)=\max \left\{\psi(n - Q), \psi(n - Q) + \psi(n - Q - 1) - \bar\psi_Q  \right\}.$$
% %%%%%%%%%%%%
\begin{lemma}\label{lem::privacy-error}
Suppose that Conditions \ref{cond::problem}--\ref{cond::group_sizes} hold as well as $H_0$ (as given in \eqref{eqn::hyp}) holds. Then, if $\psi$ is continuous on $\re^+$, then 
    $$ \frac{\GS^*(U_1)}{\sigma(n_1, n_2, \psi, Q)}=O\left(\frac{1}{\sqrt{n\lambda(1-\lambda) }}\right).$$
    % $$ \lim_{n \to \infty} \frac{\GS^*(U_1)}{\sigma(n_1, n_2, \psi, Q)}=\lim_{n \to \infty}\frac{1}{\sqrt{n\lambda(1-\lambda) C(n,\psi)}},$$
    % where $$n^{-1}\sum_{i=1}^{n-Q}\psi(i)^2/\psi(n - Q)^2-\left(n^{-1}\sum_{i=1}^{n-Q}\psi(i)/\psi(n - Q)\right)^2,$$ 
    % and $0<\lim_{n \to \infty} C(n,\psi)<1 $. 
\end{lemma}
\begin{proof}
We have that 
\begin{align*}
    \sigma^2(n_1,n_2,\psi,Q) &=\frac{n_1}{n}\left(1-\frac{n_1}{n}\right) \sum_{i = 1}^{n - Q} \psi^2(i)   + 2\frac{n_1}{n}\left(\frac{n_1 - 1}{n - 1}-\frac{n_1}{n}\right) \sum_{i = 1}^{n - Q - 1} \sum_{j = i + 1}^{n - Q} \psi(i) \psi(j)
    .
\end{align*}
Now, 
\begin{align*}
        \frac{n_1}{n} - \frac{n_1 - 1}{n - 1}=\frac{n_1(n-1)-n(n_1 - 1)}{n(n - 1)} &= \frac{n - n_1}{n(n - 1)} \stackrel{(!)}{=} \frac{n - \lambda n + O(n^{1/2})}{n(n - 1)} = \frac{1 - \lambda }{n - 1}+ O(n^{-3/2}),
    \end{align*}
Using this, 
\begin{align*}
    \sigma^2(n_1,n_2,\psi,Q) &\approx\lambda(1-\lambda)\left(\left(1+\frac{1}{n-1} \right) \sum_{i = 1}^{n - Q} \psi^2(i) - \frac{1}{n-1} \sum_{i = 1}^{n - Q } \sum_{j = 1}^{n - Q} \psi(i)\psi(j)
    \right)\\
    &=\lambda(1-\lambda)\left(\left(1+\frac{1}{n-1} \right) n\bar\psi_Q^2 - \frac{n^2}{n-1} (\bar\psi_Q)^2
    \right)\\
    &\approx n\lambda(1-\lambda)\left( \bar\psi_Q^2 - (\bar\psi_Q)^2
    \right). 
\end{align*}
In general, we have that 
\begin{align*}
    \sigma^2(n_1,n_2,\psi,Q) &= n\lambda(1-\lambda)\left( \bar\psi_Q^2 - (\bar\psi_Q)^2
    \right)+R, 
\end{align*}
where $R$ is a remainder of lower order. 
    Note that
\begin{equation*}
   \GS^*(U_1)
    \to   \psi(n - Q) + \psi(n - Q - 1) - \bar\psi_Q.
\end{equation*}
Thus, we consider the quantity
$$\frac{\psi(n - Q)}{\sqrt{n\lambda(1-\lambda)\left( \bar\psi_Q^2 - (\bar\psi_Q)^2
    \right)}}.$$
Now, let
\begin{align*}
    C(n,\psi)&=( \bar\psi_Q^2 - (\bar\psi_Q)^2)/\psi(n - Q)^2\\
    &=n^{-1}\sum_{i=1}^{n-Q}\psi(i)^2/\psi(n - Q)^2-\left(n^{-1}\sum_{i=1}^{n-Q}\psi(i)/\psi(n - Q)\right)^2\\
    &\coloneqq V_{n,1}-V_{n,2}^2.
\end{align*}
% Observe that because $\psi(i)/\psi(n - Q)\leq 1$ for $i\leq n-Q$ and $\psi$ is increasing we have that $0<C(n,\psi)<1$. 
% Now, 
% \begin{align*}
%   C(n,\psi)&=n^{-1}\sum_{i=1}^{n-Q}\psi(i)^2/\psi(n - Q)^2-\left(n^{-1}\sum_{i=1}^{n-Q}\psi(i)/\psi(n - Q)\right)^2\\
%   &=\int_1^{n-Q}\psi(x)^2dx/\psi(n - Q)^2-\left(\int_1^{n-Q}\psi(x)dx/\psi(n - Q)\right)^2
% \end{align*}
Then, since $\psi$ is continuous and monotonic, it is differentiable. We have by the mean value theorem there exists $n-Q\leq r\leq n-Q+1$, $n_0\in\bbN$ and $0<p<1$ so that for all $n\geq n_0$,
\begin{align*}
    \psi(n-Q+1)-\psi(n-Q)=\psi'(r)&\implies 1-\frac{\psi(n-Q)}{\psi(n-Q+1)}=\frac{\psi'(r)}{\psi(n-Q+1)}\\
    &\implies \frac{\psi(n-Q)}{\psi(n-Q+1)}\geq 1-\frac{\psi'(r)}{\psi(n-Q+1)}\geq \sqrt{p}. 
\end{align*}
%  $\frac{\psi(n-Q)}{\psi(n-Q+1)}\geq \sqrt{p}$. 
% Let $b_n=\frac{\psi(n-Q)}{\psi(n-Q+1)}>\sqrt{p}$ eventually (by assumption) and 
In addition, $a_n=n/(n+1)$ is also greater than $\sqrt{p}$ eventually.
Thus, 
\begin{align*}
    C(n+1,\psi)&=V_{n+1,1}-V_{n+1,2}^2\\
    &=a_n b_n V_{n,1}+(n+1)^{-1}-a_n^2 b_n^2 V_{n,2}^2-2a_n b_n V_{n,2}/n-1/(n+1)^2\\
    &\approx a_n b_n V_{n,1}-a_n^2 b_n^2 V_{n,2}^2\\
    &=a_n b_n C(n,\psi)+(a_n b_n-a_n^2 b_n^2) V_{n,2}^2\\
    &\geq p C(n,\psi) \text{ eventually. }
\end{align*}
We have that 
\begin{align*}
    C(n,\psi)&\geq p\sum_{i=n_0}^{n-1}C(i,\psi)+a_{n_0} b_{n_0} C(n_0,\psi)+(a_{n_0} b_n-a_{n_0}^2 b_{n_0}^2) V_{n_0,2}^2\geq (a_{n_0} b_n-a_{n_0}^2 b_{n_0}^2) V_{n_0,2}^2. 
\end{align*}
Thus, there exists $0<c<1$ and $n_0\in\bbN$ such that $c<C(n,\psi)<1$ for all $n\geq n_0$. 
\end{proof}
