\section{Proofs concerning the signed rank test}\label{app::sr_proofs}


\begin{proof}[Proof of Theorem~\ref{thm::rsasymp}]
Following similar logic as the proof of Lemma~\ref{lem::privacy-error}, we have that $2\psi(n-Q)\bigg/\sqrt{\sum_{i=1}^{n-Q}\psi(i)^2}\to 0$ as $n\to \infty$. Therefore, it suffices to consider $W_1$.  
    If we can show that $W_1$ satisfies the hypotheses of the \nameref{thm::lya}, the desired result would automatically follow from said theorem. To this end, we shall define, for each $i \in \{1, 2, \dots, Q\}$, the mutually-independent random variables $W_{0, i}$ which take on the values $\psi(0)$ and $-\psi(0)$ with probability $\frac{1}{2}$ apiece. As well, for each $j \in \{1, 2, \dots, n-Q\}$, define:

    \begin{align*}
        W_j = \begin{cases}
            \psi(j) \quad &\text{w.p. $\frac{1}{2}$} \\
            -\psi(j) \quad &\text{w.p. $\frac{1}{2}$}
        \end{cases}
        \text{,}
    \end{align*}
where the $W_j$'s and the $W_{0, i}$'s are mutually independent. Notice that under $H_0$, 
    \begin{align*}
    W_1 \stackrel{d}{=} \sum_{i = 0}^Q W_{0, i} + \sum_{j = 1}^{n - Q} W_j. 
    \end{align*}
    We have just re-expressed the test statistic in a manner that facilitates the application of the \nameref{thm::lya}. Before using this result, we need to compute the relevant moments of the $W_{0, i}$'s and the $W_j$'s. First, we observe that for all $i \in \{1, 2, \dots, Q\}$, for all $j \in \{1, 2, \dots, n - Q\}$ and for all $m \in \nats$:

    \begin{enumerate}[1)]
        \item \begin{align} \label{eqn::EWj}
        \expect(W_j^m) &= \begin{cases}
            0 \quad &\text{if $m$ is odd} \\
            \psi^m(j) \quad &\text{if $m$ is even}
        \end{cases}
    \end{align}
        \item \begin{align}
        \expect(|W_j|^m) = \psi^m(j) \label{eqn::EabsWj}
    \end{align}
        \item \begin{align} \label{eqn::EW0}
        \expect(W_{0, i}^m) &= \begin{cases}
            0 \quad &\text{if $m$ is odd} \\
            \psi^m(0) \quad &\text{if $m$ is even}
        \end{cases}
    \end{align}
        \item \begin{align}
        \expect(|W_{0, i}|^m) = \psi^m(0) \label{eqn::EabsW0}
    \end{align}
    \item \begin{align}
        \var(W_j) = \sigma^2_j = \psi^2(j) \text{.} \label{eqn::VarWj}
    \end{align} 
    \item \begin{align}
        \var(W_{0, i}) = \sigma^2_{0, i} = \psi^2(0) \text{.} \label{eqn::VarW0}
    \end{align}
    \end{enumerate}

    To make further progress, we note that there must exist $\ell \in \nats$ such that $\ell \in \nats \cup \{0\}$ and $\psi$ is $\Omega(n^{\frac{\ell}{4}})$ and $o(n^{\frac{\ell + 1}{4}})$. Our strategy is then to bound above the growth rate of the numerator of the fraction present in Condition \ref{eqn::lyacond} and bound below the growth rate of the denominator. For reference, Condition \ref{eqn::lyacond} reads as follows in our context (due to the above equations):

    \begin{equation} \label{lyacondcontext}
            \frac{Q |\psi(0)|^{2 + \delta} + \sum_{j = 1}^{n - Q} \left(|\psi(j)|^{2 + \delta} \right)}{\left(Q \psi^2(0) + \sum_{j = 1}^{n - Q} \psi^2(j) \right)^{1 + \frac{\delta}{2}}} \rightarrow 0 \quad \text{as $n \rightarrow \infty$ for some $\delta > 0$}.
    \end{equation}

    Since $\psi$ is non-negative, increasing and $o(n^{\frac{\ell + 1}{4}})$, term $j$ of the sum in the numerator is $o(j^{\frac{\ell + 1}{2} + \delta \, \frac{\ell + 1}{4}})$, so the sum as a whole is $o((n - Q)^{\frac{\ell + 3}{2} + \delta \, \frac{\ell + 1}{4}})$. The $Q |\psi(0)|^{2 + \delta}$ term does not affect this bound on the asymptotic growth rate of the sum as $Q \leq n$ and $\psi$ is strictly increasing. Meanwhile, the sum in the denominator is $\Omega((n - Q)^{\frac{\ell}{2} + 1})$, so the denominator as a whole is $\Omega((n - Q)^{\frac{\ell + 2}{2} + \delta \, \frac{\ell + 2}{4}})$. Thus, if $\delta \geq 2$, the limit of the fraction at large as $n \rightarrow \infty$ is indeed 0. This indicates that the hypotheses of the \nameref{thm::lya} are satisfied, which is what we needed to show. The asymptotic distribution of $W_1$ then follows from the \nameref{thm::lya} and Theorem \ref{thm::sk}.
\end{proof}
\begin{proof}[Proof of Theorem~\ref{thm::WWWCRS}]
    Fix neighboring databases $\mathbf{v}$ and $\mathbf{w}$ and assume row $j$ of the former can be changed to produce the latter. We may assume, without loss of generality, that $a_j^{'} > a_j$. We will also divide the rows of $\mathbf{v}$ into three regions:
\begin{enumerate}
    \item $A_1$, consisting of the rows with ranks not exceeding $r_j$;
    \item $A_2$, consisting of the rows with ranks exceeding $r_j$ but with $a_i < a_j^{'}$, where $a_j^{'}$ is the absolute difference of row $j$ of database $\mathbf{w}$; and,
    \item $A_3$, consisting of the rows with $a_i > a_j^{'}$.
\end{enumerate}

Before proceeding further, we will define some more notation. Let $\Delta j$ be the change in the signed rank of row $j$ when transitioning from $\mathbf{v}$ to $\mathbf{w}$. In addition, for $i = 1, 2, 3$, let $\Delta A_i$ be the change in the sum of the signed ranks of all rows in region $A_i$ upon making this transition. The change in the overall test statistic, $\Delta W_1$, is the sum of these two effects. This is because the ranks of the data points in $A_1$ and $A_3$ are unaffected by the transition between the neighbouring databases.

We notice that the only rows whose ranks differ between the databases are row $j$ and the rows in region $A_2$. Let us first bound $\Delta j$. As $\psi$ is increasing and $s_j$ changes in the worst-case scenario (this is the same justification as in the proof of Theorem 4.1 of \cite{couch2018differentially}), we have that:

\begin{align*}
    \Delta j \leq \psi(n - Q) + \psi(\max\{c_1 + 1 - Q, 0\}).
\end{align*}

Meanwhile, the ranks of each row in region $A_2$ decrease by 1 apiece, while their signs remain unchanged. Thus,

\begin{align*}
    \Delta A_2 &= \left|\sum_{i \in A_2} \psi(\max\{r_i^{'} - Q, 0\} ) - \psi(\max \{r_i - Q, 0\}) \right| \\
    &\leq \sum_{i \in A_2} \left| \psi(\max \{r_i^{'} - Q, 0 \}) - \psi(\max \{r_i - Q, 0\}) \right| \quad \text{(by the triangle inequality)} \\
    &=(\psi(\max \{c_1 + 2 - Q, 0\}) - \psi(\max\{c_1 + 1 - Q, 0\})) \\
    &\phantom{=}+ (\psi(\max \{c_1 + 3 - Q, 0\}) - \psi(\max\{c_1 + 2 - Q, 0\})) \\
    &\phantom{= \,} + \dots + (\psi(\max\{c_1 + c_2 + 1 - Q, 0\}) - \psi(\max\{c_1 + c_2 - Q, 0\})) \\
    &= \psi(\max\{c_1 + c_2 + 1 - Q, 0\}) - \psi(\max \{c_1 + 1 - Q, 0\}) \\
    &\leq \psi(n - Q) - \psi(\max\{c_1 + 1 - Q, 0\}).
\end{align*}

Then,

\begin{align*}
    \Delta W_1 &\leq \Delta j + \Delta A_2 \\
    &\leq \psi(n - Q) + \psi(\max\{c_1 + 1 - Q, 0\}) + \psi(n - Q) - \psi(\max\{c_1 + 1 - Q, 0\}) \\
    &= 2 \psi(n - Q).
\end{align*}

This is what we wanted to show. 
\end{proof}
\section{Useful auxiliary results}
We now present a set of results which will be useful in our proofs pertaining to the asymptotic distributions of our test statistics. 
Our theoretical results rely upon two central limit theorems. 
The first of these results is the \nameref{thm::lya}, which generalizes the `ordinary' Central Limit Theorem to sets of random variables which are not necessarily identically distributed. We adopt the formulation of this result from \citet{pratt2012concepts}.
\begin{theorem}[\textbf{Lyapunov Central Limit Theorem}] \label{thm::lya}
If $X_1, X_2, \dots$ are independent, real-valued random variables with possibly different distributions, each having finite absolute moments of the order $2 + \delta$ for some $\delta > 0$, and if
        \begin{equation} \label{eqn::lyacond}
            \frac{\sum_{j = 1}^{n} \expect \left(|X_j - \mu_j|^{2 + \delta} \right)}{\left(\sum_{j = 1}^{n} \sigma_j^2 \right)^{1 + \frac{\delta}{2}}} \rightarrow 0 \quad \text{as $n \rightarrow \infty$},
        \end{equation}
where $\mu_j = \expect(X_j)$ and $\sigma_j^2 = \var(X_j)$, then
        \begin{align*}
            \frac{\sum_{j = 1}^{n} (X_j - \mu_j)}{\left(\sum_{j = 1}^{n} \sigma_j^2 \right)^{\frac{1}{2}}},
        \end{align*}
        converges in distribution to the standard normal distribution.
\end{theorem}
\noindent The second result is due to \citet{wald1944statistical}:
\begin{theorem}[\textbf{Wald-Wolfowitz Theorem}] \label{thm::waldwolf}
        For a sequence \seq{y} and for all $m, r \in \nats$, define:

        \begin{align*}
            \mu_r(y_n, m) = \frac{1}{m} \sum_{i=1}^m \left(y_i - \sum_{j = 1}^m y_j \right)^r.
        \end{align*}
Let the sequence \seq{a} have the property that
\begin{align} \label{eqn::wwcond}
            \frac{\mu_r(a_n, m)}{\mu_2(a_n, m)^{\frac{r}{2}}} = O(1),
\end{align}
for all $r > 2$, and let the sequence \seq{d} also satisfy this property. Let $X = \left(x_1, x_2, \dots, x_m \right)^T$ be a random vector whose elements form a permutation of the first $m$ terms of \seq{a} with probability 1. Then, the random variable 
\begin{align*}
            L_m = \sum_{i = 1}^m d_i \, x_i,
\end{align*}
has the property that
\begin{align*}
            \frac{L_m - \expect(L_m)}{\text{SD}(L_m)} \cond N(0, 1) \text{.}
        \end{align*}
\end{theorem}

