\section{Donoghue classes and L-systems}\label{s3}

Denote by  $\widehat{\calN}$  the  class of all scalar Herglotz-Nevanlinna functions $M(z)$ that admit the representation \eqref{hernev-real}
%\begin{equation}\label{hernev-0}
%M(z)=\int_\bbR \left(\frac{1}{{t}-z}-\frac{{t}}{1+{t}^2}\right)d\sigma,
%\end{equation}
where $\sigma$ is a compactly supported  bounded Borel measure such that
\begin{equation}\label{e-9-cond}
\int_\bbR\frac{t}{1+{t}^2}\,d\sigma({t})=0.
\end{equation}
Observe that for a function $M(z)\in\widehat{\calN}$ condition \eqref{e-9-cond} implies
$$
M(i)=\int_\bbR \frac{d\sigma(t)}{t-i}={\int_\bbR \frac{t}{t^2+1}\,d\sigma(t)+i\int_\bbR \frac{d\sigma(t)}{t^2+1}}=i\int_\bbR \frac{d\sigma(t)}{t^2+1}.
$$

 Following the approach of  \cite{BMkT,BMkT-3,MT10}, given   $0\le\kappa<1$,  denote by $\widehat{\sM}$,  $\widehat{\sM_\kappa}$ and  $\widehat{\sM_\kappa^{-1}}$  the subclass of $\widehat{\calN}$     satisfying the additional requirement  that
\begin{equation}\label{e-42-int-don}
\int_\bbR\frac{d\sigma({t})}{1+{t}^2}=1\,,\quad\text{equivalently,}\quad M(i)=i,
\end{equation}
\begin{equation}\label{e-38-kap}
\int_\bbR\frac{d\sigma({t})}{1+{t}^2}=\frac{1-\kappa}{1+\kappa}\,,\quad\text{equivalently,}\quad M(i)=i\,\frac{1-\kappa}{1+\kappa},
\end{equation}
and
\begin{equation}\label{e-39-kap}
\int_\bbR\frac{d\sigma({t})}{1+{t}^2}=\frac{1+\kappa}{1-\kappa}\,,\quad\text{equivalently,}\quad M(i)=i\,\frac{1+\kappa}{1-\kappa},
\end{equation}
respectively. Clearly,  $$\widehat{\sM}=\widehat{\sM_0}=\widehat{\sM_0^{-1}}.$$

It is easy to see that  if $M(z)$ is an arbitrary function from the class $\widehat{\calN}$ such that
\begin{equation}\label{e-66-L}
\int_\bbR\frac{d\sigma({t})}{1+{t}^2}=a \quad\text{for some}\quad  a>0,
\end{equation}
 then  $M\in\widehat{\sM}$ if and only if $a=1$.

The membership of $M\in \widehat{\cN}$ in the other generalized Donoghue classes   $ \widehat{\sM_\kappa} $  and   $\widehat{\sM_\kappa^{-1}}$ can
also be described straightforwardly as follows:
 \begin{enumerate}
\item[] if $a<1$, then $M\in \widehat{\sM_\kappa}$ with
\begin{equation}\label{e-45-kappa-1}
\kappa=\frac{1-a}{1+a},
\end{equation}
\item[]and
\item[]if $a>1$, then $M\in \widehat{\sM_\kappa^{-1}}$ with
\begin{equation}\label{e-45-kappa-2}
\kappa=\frac{a-1}{1+a}.
 \end{equation}
 \end{enumerate}

