%\mathbb{E}\left[N^{\rm U}_{\rm A}\right] + \mathbb{E}\left[N^{\rm I}\right]\cdot\mathbb{E}\left[N^{\rm U}_{\rm I}\right] \ge \mathbb{E}\left[N^{\rm U}\right].
%\end{equation}
%It is difficult to derive the exact analytical expression or the lower bound of the expectations of $N^{\rm U}_{\rm A}$ and $N^{\rm U}_{\rm I}$ to ensure the constraint (\ref{target_num_requirement}) satisfied.
Combining the constraint on sensing quantity in~\eqref{num_targets_requirement_frequency}, the constraint on sensing data processing time in~\eqref{comput_delay_requirement}, and the constraint due to the maximum number of targets in the on-device sensing subregion in~\eqref{SIR_constraint_transformed}, we derive the maximum values of $\mathbb{E}[N^{\rm U}_{\rm I}]$ and $\mathbb{E}[N^{\rm U}_{\rm A}]$ as
\begin{subequations}\label{upper_bound_expected_targets}
\begin{equation}\label{upper_bound_NIU}
