\overline{N}^{\rm U}_{\rm I}  \triangleq  \min\left\{\mathbb{P}\left\{D^{\rm I, U}\le D^{\rm I,U}_{\rm max}\right\}\cdot \mathbb{E}\left[N^{\rm U}_{\rm I,1}\right],\frac{1-\rho_{\rm c}}{\widehat{\rho}_{\rm s}}, \frac{\tau T\cdot F^{\rm I}_{\rm e}}{C_0} \right\},%\ge\mathbb{E}\left[N^{\rm U}_{\rm I}\right],
\end{aligned}
\end{equation}
