D^{\rm I,U}_{\rm max} &= \left(\frac{\bar{{\sigma}}}{\widehat{\gamma}_s}\cdot(-\ln \widehat{P})\cdot \frac{1}{\phi_{\rm I} ^2 \check{\lambda}^{\rm I}}\right)^{\frac{1}{4}}\cdot\left(\frac{X_{\rm s}^{\rm I}}{1-\rho_{\rm c}}\right)^{\frac{1}{4}},
\end{aligned}
\end{equation}
\textit{which is also the maximum distance between a target and an mobile device for satisfying the sensing SIR requirement in~\eqref{SINR_constraint_in_problem}.}}
