Please refer to Appendix B.
\end{proof}
Based on Proposition 2, we can transform constraint~\eqref{SINR_constraint_in_problem} equivalently using~\eqref{max_range}. To make Problem (P1) more tractable, we relax the integer decision variables, i.e., ${X}^{\rm I}_{\rm s}, {X}^{\rm A}_{\rm c}, {X}^{\rm A}_{\rm s}$, to real-valued variables. Then, to efficiently solve the problem, we derive necessary conditions for optimality as follows.

\noindent\textbf{Proposition 3:} \textit{The optimal solution of Problem (P1) must satisfy the following three conditions:}
\begin{subequations}\label{necessary_opt_con}
\begin{equation}\label{rho_c_new_constraint}
\frac{1-\rho_{\rm c}}{\widehat{\rho}_{\rm s}} \le\min\left\{\mathbb{E}\left[N^{\rm U}_{\rm I,1}\right],\frac{\tau T\cdot F^{\rm I}_{\rm e}}{C_0}\right\};
\end{equation}
\vspace{-0.4cm}
\begin{equation}\label{rho_c_XIs_new_constraint}
\frac{1-\rho_{\rm c}}{\widehat{\rho}_{\rm s}} = \mathbb{P}\left\{D^{\rm I, U}\le D^{\rm I,U}_{\rm max}\right\}\cdot \mathbb{E}\left[N^{\rm U}_{\rm I,1}\right];
\end{equation}
\vspace{-0.4cm}
\begin{equation}\label{XsA_FeA_constraint}
\frac{X_{\rm s}^{\rm A}}{\widehat{\rho}_s}= \frac{\tau T\cdot F^{\rm A}_{\rm e}}{C_0}.
\end{equation}
\end{subequations}
\begin{proof}
Please refer to Appendix C.
\end{proof}
Condition \eqref{rho_c_new_constraint} specifies a minimum value of $\rho_c$ since the right-hand side is independent of any decision variable in Problem (P1); \eqref{rho_c_XIs_new_constraint} gives the relation between $\rho_c$ and ${X}^{\rm I}_{\rm s}$ since $\mathbb{P}\left\{D^{\rm I, U}\le D^{\rm I,U}_{\rm max}\right\}$ is a function of only these two decision variables; \eqref{XsA_FeA_constraint} gives the relation between ${X}^{\rm A}_{\rm s}$ and $F^{\rm A}_{\rm e}$. \looseness=-1%In addition, \eqref{rho_c_new_constraint} and \eqref{rho_c_XIs_new_constraint} make $\overline{N}^{\rm U}_{\rm I}$ in the constraint \eqref{target_num_requirement_relaxed} equal $\frac{1-\rho_{\rm c}}{\widehat{\rho}_{\rm s}}$; \eqref{XsA_FeA_constraint} makes $\overline{N}^{\rm U}_{\rm A}$ in the constraint \eqref{target_num_requirement_relaxed} equal $\frac{X_{\rm s}^{\rm A}}{\widehat{\rho}_s}$.
\subsubsection{Problem Transformation and Solution}
Based on \textbf{Proposition 2} and \textbf{Proposition 3}, given the value of the decision variable $\rho_{\rm c}$, the optimal values of the other four decision variables can be determined in closed forms. First, the minimum spectrum reservation for communication, ${X}^{\rm A}_{\rm c}$, can be obtained by converting the inequality constraint \eqref{comm_tot_requirement} to an equality constraint. Second, the optimal amount of spectrum resources reserved for sensing by mobile devices, ${X}^{\rm I}_{\rm s}$, can be found by solving \eqref{rho_c_XIs_new_constraint}. Third, the optimal spectrum reservation for sensing by APs, ${X}^{\rm A}_{\rm s}$, can be obtained by converting the inequality constraint \eqref{target_num_requirement_relaxed} to an equality constraint. Given the optimal ${X}^{\rm A}_{\rm s}$, the optimal edge computing network planning, $F^{\rm A}_{\rm e}$, can be obtained based on \eqref{XsA_FeA_constraint}. As a result, the original multi-variable optimization problem can be transformed into a single-variable problem concerning $\rho_{\rm c}$. The transformed problem can be solved by a brute-force search. Then, the real values in the decision are rounded up to integers. Given the joint spatial model or the independent spatial model, a candidate network planning decision can be respectively obtained.%\looseness=-1 %According to either of the two spatial models of the mobile devices and the sensing targets in the slice DT, one set of network planning decisions can be obtained by a brute-force search for the optimal $\rho_{\rm c}$, respectively.
\begin{comment}
\begin{itemize}
    \item \textit{Spectrum network planning for Communication:} According to (\ref{low_bound_R_secV}), given $\rho_{\rm c}$, there exists a minimum real-valued $X^{\rm A}_{\rm c}$, denoted by $\widetilde{X}^{\rm A}_{\rm c}$, for satisfying the communication demand (\ref{comm_tot_requirement}), given by
    \begin{equation}\label{opt_ul_resources}
    \widetilde{X}^{\rm A}_{\rm c} = \frac{\hat{R}}{R_0}\left(\frac{1}{\rho_{\rm c}}+\frac{\check{\lambda}_{\rm 1}^{\rm I}A_0}{1-e^{-\check{\lambda}_{1}^{\rm I} A_0}}-1\right).
    \end{equation}%the lower bound of the uplink transmission rate of the mobile device, i.e., $\bar{R}$, is increasing with the number of subcarriers reserved for uplink communication, i.e., $X^{\rm A}_{\rm c}$. As a result,
    \item \textit{Spectrum network planning for Target Tracking by mobile devices:}
    Given $\rho_{\rm c}$, by solving (\ref{rho_c_XIs_new_constraint}), the optimal amount of spectrum resources reserved for target tracking by mobile devices, denoted by $\widetilde{X}^{\rm I}_{\rm s}$, is given by
    \begin{equation}\label{opt_sensing_spectrum_device}
    \widetilde{X}^{\rm I}_{\rm s}=
    \begin{cases}
