\begin{corollary}\label{cor:Irr-eta}
  Let $\eta \in \monxxr$.
  Let $H$ be the set of monomials~$m \preccurlyeq \eta$ such that $m\in \lm(S)\cap\lm(\dd W_\xx^r)$ and
  $m \neq \lm(\partial_i p g)$
  for any $i$, $g\in G$, and $p\in\monxx$.
  For~$m\in H$, let $a_m \in W_\xx^r$ be any reduced form of some $\xx^\ggamma g - \lc(g) \dd^\bbeta \xx^{\aalpha + \ggamma} e_j$, where
  $g \in G$,
  $\lm(g) = \xx^{\aalpha} \dd^{\bbeta} e_j$,
  and $m = \lm(\xx^\ggamma g)$.
  Then
  \begin{equation}\label{eq:Irr-as-sum}
    \Irr_{\preccurlyeq \eta} = \sum_{m\in H} \bK a_{m} .
  \end{equation}
\end{corollary}

\begin{proof}
  Note that for each~$m\in H$, the corresponding~$\bbeta$ is nonzero.
  Indeed, by definition, $m\in \lm(\dd W_x^r)$ so there is some~$\partial_i$ such that~$m = \lm(\partial_i m')$ for another monomial~$m'$. Moreover, $m = \lm(\xx^\ggamma g)$, so~$\lm(g)$ also contains~$\partial_i$.
  In particular, the term $\lc(g) \dd^\bbeta \xx^{\aalpha + \ggamma} e_j$ has the form~$\partial_i w$.
  Therefore,
  Theorem~\ref{thm:redT} applies and
  $\Irr_{\preccurlyeq m} =  \Irr_{\prec m} + \bK a_m$.
  For a monomial~$m$ not in~$H$, either Theorem~\ref{thm:redT} or Lemma~\ref{lem:crit-red}
  shows that~$\Irr_{\preccurlyeq m} =  \Irr_{\prec m}$.
  Then the statement follows by well-founded induction on~$\eta$.
