To turn Corollary~\ref{cor:Irr-eta} into an algorithm,
we introduce a finiteness property of the monomial order~$\preccurlyeq$.
\begin{hypothesis}\label{hyp:finiteness-for-eta}
For any two monomials $\gamma$ and~$\eta$ of~$\monxxr$,
the set of~$\aalpha$ for which $\xx^\aalpha \gamma \preccurlyeq \eta$ is finite.
\end{hypothesis}
This hypothesis is always satisfied by orders graded by total degree,
because a monomial~$\eta$ has a finite number of predecessors in~$\monxxr$.
It is also satisfied by orders eliminating~$\xx$, in the sense that
\begin{equation}\label{eq:elimination-order}
\aalpha'-\aalpha \in \bN^n \setminus \{0\} \Rightarrow \xx^\aalpha \dd_\xx^\bbeta e_i \prec \xx^{\aalpha'} \dd_\xx^{\bbeta'} e_{i'} ,
\end{equation}
as long as the set of~$\aalpha$ for which $\xx^\aalpha \preccurlyeq x_i$ is finite for each $i \in \{1,\dots,n\}$.
For example, this contains “elimination orders” \cite{CoxLittleOShea-1998-UAG} or “block orders” \cite{BeckerWeispfenning-1993-GB} that first order by total degree in~$\xx$,
but not a lexicographical order that has $x_1 > x_2 > \partial_1 > \partial_2$.


\begin{alg}{Computation of $\Irr_{\preccurlyeq\eta}$}{basis-E-lambda}
  \textbf{Input:}
  \begin{algovals}
    \item a Gröbner basis~$G$ of~$S$
    \item $\eta\in \monxxr$
    \end{algovals}
  \textbf{Output:}
  \begin{algovals}
    \item a generating family of the $\bK$-vector space $\Irr_{\preccurlyeq\eta}$
  \end{algovals}
  \begin{pseudo}
    $G' \gets \left\{ g \in G \st \lm(g) \text{ involves some $\partial_i$} \right\}$\\
    \label{line:defH}$H \gets \left\{ \lm(\xx^\ggamma g) \st  \ggamma \in \mathbb{N}^n, \ g\in G', \text{ and } \lm(\xx^\ggamma g)\preccurlyeq \eta \right\}$ \ct{finite by Hypothesis~\ref{hyp:finiteness-for-eta}}\\
    $H \gets H \setminus \left\{ \lm(\partial_i m g) \st m\in \monxx, \ g\in G, \ 1\leq i\leq n \right\}$\\

    $B \gets \varnothing$ \\
    \kw{for} $m \in H$\\+
      pick $g\in G'$ and $\ggamma$ such that~$m = \lm(\xx^\ggamma g)$\\
      $\xx^{\aalpha} \dd^\bbeta e_i \gets \lm(g)$ \quad \ct{by construction~$\bbeta \neq 0$}\\
      $B \gets B \cup \big\{ \big[\xx^\ggamma g - \lc(g) \dd^\bbeta \xx^{\aalpha + \ggamma} e_i \big] \big\}$\\-
    \kw{return} $B$ \\
  \end{pseudo}
\end{alg}

\begin{theorem}
Under Hypothesis~\ref{hyp:finiteness-for-eta} Algorithm~\ref{algo:basis-E-lambda} is correct and terminates.
\end{theorem}

\begin{proof}
  Termination is obvious since the set on line~\ref{line:defH} is finite, by hypothesis.
  For the correction, we observe that~$H$ computed in the algorithm is the same as the set~$H$ described in Corollary~\ref{cor:Irr-eta}.
\end{proof}

\begin{definition}
Let $B_\eta$ be an echelon form of the generating family returned by Algorithm~\ref{algo:basis-E-lambda} on input $\eta$.
We define a reduction $[.]_{\eta}$ from $W_\xx^r$ into itself by
\[
[a]_\eta = \Reduce( [a], B_\eta)
\]
where $[.]$ is the map defined by Algorithm~\ref{algo:irred-form}
and $\Reduce(.,B_\eta)$ is the reduction algorithm by the echelon form $B_\eta$.
\end{definition}

\begin{proposition}
The map~$[.]_\eta$ is $\bK$-linear.
\end{proposition}

\begin{proof}
This follows from Proposition~\ref{prop:[.]-is-linear} and the $\bK$-linearity of $\Reduce(.,B_\eta)$.
\end{proof}

\begin{theorem}
\label{thm:red}
For any $a\in S + \dd W_\xx^r$ there exists $\eta\in \monxxr$ such that for all $\eta' \succcurlyeq \eta$, the remainder~$[a]_{\eta'}$ is zero.
\end{theorem}

\begin{proof}
  The element~$[a]$ is congruent to~$a$ modulo~$S+\dd W_\xx^r$,
  so it is in~${S+\dd W_\xx^r}$, like~$a$ itself.
  Moreover, it is irreducible, and so it is in~$\Irr$ by the definition of~$\Irr$.
  Because of the equality $\Irr = \bigcup_{\eta \in \monxxr} \Irr_{\preccurlyeq\eta}$, there exists $\eta$
  such that $[a]\in \Irr_{\preccurlyeq\eta}$
  and thus $\Reduce([a], B_\eta) = 0$.
  For~$\eta' \succcurlyeq \eta$, the vector space $\Span_\bK(B_\eta)$ is included in~$\Span_\bK(B_{\eta'})$, so
  $[a]_{\eta'} = \Reduce([a], B_{\eta'}) = \Reduce(\Reduce([a], B_\eta), B_{\eta'}) = \Reduce(0, B_{\eta'}) = 0$.
\end{proof}

\begin{definition}\label{def:nf}
The \emph{normal form} of an element~$a \in W_\xx^r$ modulo~$S+\dd W_\xx^r$ is the unique element~$a' \in W_\xx^r$
such that~$a \equiv a' \pmod{S+\dd W_\xx^r}$
and no monomial of~$a'$ is the leading monomial of an element of~$S+\dd W_\xx^r$.
\end{definition}

\begin{corollary}\label{cor:nf}
  For any~$a\in W_\xx^r$, there exists $\eta\in \monxxr$ such that for all $\eta' \succcurlyeq \eta$,
  the remainder~$[a]_{\eta'}$ is the normal form of~$a$ modulo~$S+\dd W_\xx^r$.
\end{corollary}

\begin{proof}
  Let~$a'$ be the normal form of~$a$.
  Let~$\eta$ such that~$[a- a']_\eta = 0$, given by Theorem~\ref{thm:red}.
  By definition, $[.]_\eta$~replaces monomials by smaller ones,
  but only if this is possible,
  so that we have~$[a']_\eta = a'$.
  By linearity of~$[.]_\eta$, we obtain~$[a]_\eta = a'$.
\end{proof}



\subsection{Confinement}
\label{subsec:guess_eta}

``Computing'' in the quotient $M/\dd M \simeq W_\xx^r/(S + \dd W_\xx^r)$
can take on several forms, with various levels of potency.
In the strongest interpretation, we want to compute a basis of the quotient, as a $\bK$-linear space,
and we want to be able to compute normal forms in~$W_\xx^r$ modulo~$S + \dd W_\xx^r$.
In a weaker sense, we merely want to be able to capture the finiteness of the quotient space,
without ensuring the linear independence of a finite generating set or even producing it explicitly.
%
In view of our needs for integration algorithms in the next sections,
there is an even weaker sense:
given $a \in W_\xx^r$ (which will designate a function to be integrated)
and a $W_\xx$-linear map from~$W_\xx^r$ to itself (which will be related to taking derivatives with respect to a parameter $t \in \bK$),
we need to testify the finite-dimensionality of the span over~$\bK$
of the orbit $\{L^i(a)\mid i\in\bN\}$ modulo $S+\dd W_\xx^r$.
%
In this section, we show that the reductions~$[.]_\eta$ can be used to find,
for any $a$ and~$L$, a finite set~$B$ that witnesses this finite-dimensionality.

\begin{alg}{Computation of a confinement}{confinement}
  \textbf{Input:}
  \begin{algovals}
    \item a module $S\subseteq W_\xx^r$ given by a Gröbner basis
    \item $a \in W_\xx^r$
    \item a $W_\xx$-linear map $L : W_\xx^r\to W_\xx^r$ given by a $r\times r$ matrix
    \item $\rho \in \bN$
    \end{algovals}
  \textbf{Output:}
  \begin{algovals}
    \item an effective confinement for~$a$ and~$L$ modulo~$S+\dd W_\xx^r$
  \end{algovals}
  \begin{pseudo}
    $s\gets \rho$ \\
    $\eta \gets$ the largest monomial of degree~$s$ \label{line:mainloop} \\
    $B \gets \varnothing$ \\
    $Q \gets \supp([a]_\eta)$ \\
    \kw{while} $Q\setminus B \neq \varnothing$ \\+
      $m\gets $ an element of~$Q\setminus B$ \\
      \kw{if} $\deg m > s - \rho$ \\+
      $s\gets s+1$ \\
      \kw{goto} line~\ref{line:mainloop} \\-
      $Q \gets Q \cup \supp([L(m)]_\eta)$ \\
      $B\gets B\cup \left\{ m \right\}$ \\-

    \kw{return} $(\eta, B)$ \\
  \end{pseudo}
\end{alg}



\begin{definition}
An \emph{effective confinement}
for~$a \in W_\xx^r$ and a $W_\xx$-linear map~$L : W_\xx^r \to W_\xx^r$
is a pair $(\eta,B)$ consisting of a monomial~$\eta$ and of a finite subset~$B\subseteq \monxxr$, and satisfying:
\begin{enumerate}
  \item the support of $[a]_\eta$ is included in~$B$;
  \item the support of $[L(m)]_\eta$ is included in~$B$ for any $m \in B$.
\end{enumerate}
An effective confinement is \emph{free} if the elements of~$B$ are $\bK$-linearly independent modulo~$S+\dd W_\xx^r$.
\end{definition}



\begin{theorem}\label{thm:confinement}
  Algorithm~\ref{algo:confinement} is correct.
  It terminates if $M/\dd M$~is finite-di\-men\-sio\-nal,
  for example if $M$~is holonomic.
  Moreover, if the input parameter~$\rho$ is large enough, then Algorithm~\ref{algo:confinement} outputs a free effective confinement.
\end{theorem}

\begin{proof}
  We first address correctness.
  Consider the sets $B$ and~$Q$ after any iteration of the while loop.
  By construction, we have $B \subseteq Q$,
  $\supp([a]_\eta) \subseteq Q$,
  and $\supp([L(m)]_\eta) \subseteq Q$ for any~$m\in B$.
  If the halting condition $Q\setminus B \neq \varnothing$ of the while loop is reached,
  that is, equivalently, if $Q \subseteq B$ holds at the end of an iteration,
  then we have $B = Q$.
  In conclusion, the returned value~$(\eta,B)$ is an effective confinement.

  As for termination,
  let~$C \subseteq M_\xx^r$ be the set of monomials that are normal forms modulo~$S+\dd W_\xx^r$.
  As a consequence of Definition~\ref{def:nf}, the set of normal forms is the vector space~$\Span_\bK(C)$.
  Moreover, a basis of the quotient space~$M/\dd M$ is formed by the classes modulo $S+\dd W_\xx^r$ of all elements of~$C$,
  so in particular, $C$~is finite by the hypothesis of finite dimension.
  By Corollary~\ref{cor:nf},
  there is therefore some~$\eta_\infty$ such that for any~$\eta \succcurlyeq \eta_\infty$,
  \begin{equation}
    \label{eq:all-confined}
    \supp([a]_\eta) \subseteq C \text{ and } \forall m\in C, \ \supp([L(m)]_\eta) \subseteq C.
  \end{equation}

  Since each iteration of the \emph{while} loop treat a different monomial~$m$,
  and since there are finitely many monomials of degree at most~$s -\rho$,
  the \emph{while} loop terminates.
  It terminates either because~$Q\setminus B = \varnothing$, in which case the algorithm terminates,
  or because~$Q$ contains an element of degree larger that~$s - \rho$, in which case we increase~$s$.
  So, either the algorithm terminates, or $s$~tends to~$\infty$.

  Assume~$s\to\infty$.
  At some point, we will have $s \geq \deg \eta_\infty$,
  so after line~\ref{line:mainloop} is executed,
  we have the inequalities
  $\eta \succcurlyeq \eta_\infty x_1^{s-\deg(\eta_\infty)} \succcurlyeq \eta_\infty$,
  because $\eta$~is the largest monomial of degree~$s$ and by the definition of a monomial order.
  In this circumstances, the set~$Q$ is a subset of~$C$ at every iteration of the main loop, because of~\eqref{eq:all-confined}, and so is~$B$ because of the invariant~$B\subseteq Q$.
  Since~$s \to \infty$, we also reach a point where~$\rho + \deg m \leq s$
  for all~$m\in C$. After this point, $s$~is not increased anymore.
  This contradiction shows that the algorithm terminates.

  If the input~$\rho$ satisfies $\rho \geq \deg \eta_\infty$,
  we have $s \geq \rho \geq \deg \eta_\infty$,
  and by the same reasoning as in the previous paragraph,
  we have again $\eta \succcurlyeq \eta_\infty$.
  This is so during the whole execution of the algorithm.
  Therefore, like in the preceding paragraph,
  we have $B \subseteq Q \subseteq C$ during the execution of the while loop.
  So, the output set~$B$ is a subset of~$C$, which is a free family modulo~$S+\dd W_\xx^r$.
\end{proof}


\subsection{Comparison with the Griffiths--Dwork reduction}
\label{subsec:GD}

Let~$f \in \bK[\xx]$ be a homogeneous polynomial
and let $M$ be the $W_\xx$-module~$\bK[\xx]  e^{f}$, where $\partial_i$ acts by $\partial_i \cdot e^{f} = \frac{\partial f}{\partial x_i} e^f$.
When~$f$ defines a smooth variety, we can compute in~$M/\dd M$ using the Griffiths--Dwork reduction~\cite{Dwork62,Dwork64,Griffiths-1969-PCR}.
This is usually presented with rational functions in~$\bK[\xx, f^{-1}]$ but the exponential formulation is equivalent (for example, see \parencite{Dimca_1990,Lairez_2016}).
The module~$M$ admits the presentation
\[ M \simeq \frac{W_\xx}{\sum_i W_\xx (\partial_i - f_i)}, \]
where~$f_i$ denotes the partial derivative $\frac{\partial f}{\partial x_i}$.
(This presentation is what makes the exponential formulation easier in our setting. A presentation of the holonomic $W_\xx$-module $\bK[\xx, f^{-1}]$ is much harder to compute \parencite{OakuTakayama_2001}.)

We briefly present the Griffiths--Dwork reduction and observe that irreducible elements for the Griffiths--Dwork reduction are exactly the irreducible elements for our reduction $\to$.

\paragraph{The Griffiths--Dwork reduction.}

Let $\preccurlyeq_0$ be a monomial order on $\bK[\xx]$,
and, for this monomial ordering, let $G_{0}$ be the minimal Gröbner basis of the polynomial ideal $ I = (f_1,\dots,f_{n})$.
Given a homogeneous polynomial $a \in \bK[\xx]$,
we can compute the remainder~$r$ of the multivariate division of~$a$ by~$G_0$ and the cofactors~$b_1,\dotsc,b_n \in \bK[\xx]$ such that
\begin{equation}
\label{introGD1}
a = r + \sum_{i=1}^{n}{b_if_i}.
\end{equation}
By homogeneity, $\deg b_i = \deg a - \deg f + 1$ (unless~$b_i = 0$).
Then, the rule for the derivative of a product yields
\begin{equation}
\label{introGD2}
ae^{f} = r e^{f} - \underbrace{\sum_{i=1}^{n}{\frac{\partial b_i}{\partial x_i}} }_{\mathclap{\text{degree $\deg a - \deg f$}}} e^{f} + \underbrace{\sum_{i=1}^{n} \partial_i \cdot \left(b_ie^{f}\right)}_{\in \dd M}.
\end{equation}
The last term is in~$\dd M$, so we ignore it,
and the second term has lower degree than~$a$, so we can apply the same procedure recursively,
which will terminate by induction on the degree.
In the end, we obtain a reduced form $a e^f \equiv r e^f \pmod{\dd M}$ where~$r \in \bK[\xx]$ is irreducible with respect to~$G_0$. These are the irreducible elements for the Griffiths--Dwork reduction.

This reductions is defined for any homogeneous polynomial~$f$, but it enjoys special properties when $f_1,\dotsc,f_n$ do not have any non trivial common zero
in an algebraic closure of~$\bK$. Geometrically, this means that $f$ defines a smooth hypersurface in~$\mathbb{P}^{n-1}(\bK)$.
\textcite{Griffiths-1969-PCR} proved, under this smoothness assumption, that the reduced form of any~$a e^f$ vanishes if and only if~$a e^f \in \dd M$.


