%   \textbf{Output:} a polynomial $r$ such that $ae^{f} \equiv re^{f} \pmod{\sum_{i=1}^n \partial_i\left( \bK[\xx]e^{f}\right)}$
%   \begin{pseudo}
%     $G_0\gets $ Gr\"obnerBasis$(f_1,\dots,f_n)$ for $\preccurlyeq_0$ \\
