\textbf{Axioms:} \\
G(m_1 - 2m_2) = cd_1\frac{dx_1}{dt} \\
F_g d_1 = F_c d_2 \\
d_1\frac{dx_2}{dt}(4F_c + F_g) = W\frac{dx_1}{dt} + cd_2m_2\frac{d^2x_1}{dt^2} \\
cWm_2\frac{d^2x_1}{dt^2} + F_c p\left( \frac{dx_2}{dt} \right)^2 = F_g\left( \frac{dx_1}{dt} \right)(cp + F_c d_1) \\
