W = \frac{F_g \frac{dx_1}{dt} \frac{dx_2}{dt} \left(2 \frac{dx_1}{dt} \frac{d^2x_2}{dt^2} - \frac{dx_1}{dt} + d_1 \frac{d^2x_2}{dt^2} \right) + 2F_c d_1 \left( \frac{dx_2}{dt} \right)^2 \frac{d^2x_2}{dt}}{\frac{dx_1}{dt} \frac{d^2x_2}{dt^2} \left( \frac{dx_1}{dt} - \frac{dx_2}{dt} \right)}
