\subsection{Energy correlations of a SC matrix}\label{sec:SC_energy}
%=========================================================
%=========================================================
%	SC: density of NNS, number variance
\begin{figure}[t]
	\centering
	\includegraphics[width=0.95\columnwidth]{fig_SC_s_numvar}
	\caption[Energy correlation of SC matrices]{Energy correlation of random SC matrices. (a) density of level spacing (b) number variance for $N = 2048$. The solid curves denote numerical results while the dashed lines denote the analytical expressions for Poisson, GOE and random SC matrices (Eqs.~\eqref{eq_NNS_SC} and \eqref{eq_nvar_SC}).}
	\label{fig_SC_s_numvar}
\end{figure}
%=========================================================
We are interested in random SC matrices having independent and identically distributed Gaussian random elements with zero mean and unit variance. Corresponding energy spectrum is a superposition of two pure spectra, each belonging to a Gaussian orthogonal ensemble (GOE) matrix. The energy correlations in case of such mixed spectrum is well known~\cite{Pandey2019Arxiv}. Below, we provide the analytical forms of the energy correlations for a random SC matrix for the sake of completeness.

The density of states (DOS) of a random SC matrix follows the Wigner's semi-circle law with a width $2\sqrt{\mean{E^2}} = \sqrt{4 + N}$. Corresponding energy levels exhibit level clustering where the density of level spacing follows~\cite{Mehta2004book, Pandey2019Arxiv}
\begin{align}
	\label{eq_NNS_SC}
	\mathrm{P}^\mathrm{SC}(s) = \frac{e^{-\frac{\pi}{8}s^2}}{2} + \frac{\pi}{8} s e^{-\frac{\pi}{16}s^2} \ferfc{\frac{\sqrt{\pi}}{4}s}
\end{align}
and the 2nd moment of the level spacing is
\begin{align}
	\mean{s^2} = \frac{8(2 - \sqrt{2})}{\pi}.
\end{align}
In Fig.~\ref{fig_SC_s_numvar}(a), we plot the numerically obtained density of level spacing of SC ensemble for $N = 2048$ along with the analytical expression from Eq.~\eqref{eq_NNS_SC}. The above equation indicates a degree of level repulsion intermediate between that of the GOE and Poisson ensemble ($\mean{s^2} = \frac{4}{\pi}$ and 2 for the Wigner's surmise and exponential distribution, respectively). An intermediate level repulsion caused by incomplete separation of symmetries is observed in many-body systems as well, e.g.~1D hard core boson model~\cite{Santos2010}.

The superposition of two pure spectra also affects the long-range energy correlation of a SC matrix, reflected in the two-point correlation function, 
\begin{align}
	\label{eq_def_rho2}
	\rho^{(2)}(E_1, E_2) = N(N-1) \int dE_3\dots dE_N \prob{\vec{E}}.
\end{align}
The above integral relation is valid provided the joint density of the $N$ energy levels, $\prob{\vec{E}}$ is invariant under the exchange of any pair of energies. The two-point correlation, 
$\rho^{(2)}(E_1, E_2)$ is the probability of finding any two energy levels at $E_1$ and $E_2$~\cite{Bogomolny2001}. 
%, hence can be interpreted as the sum of the densities of all possible level spacings~\cite{Bogomolny2001}. Importantly, $\rho^{(2)}(E_1, E_2)$ has translational invariance and it is only a function of the distance between given energy levels, i.e.~$\rho^{(2)}(E_1, E_2) = \rho^{(2)}(E)$ where $E \equiv |E_1 - E_2|$. 
A related quantity is the two-level cluster function, $T_2(E) \equiv 1 - \rho^{(2)}(E)$. We denote the two-level cluster function of the unfolded energy levels as $Y_2(\Ecal)$ where $\Ecal$ is the gap of unfolded energy levels~\cite{Guhr1998}. In the Poisson ensemble, $Y_2(\Ecal) = 0$ at any energy gap, while for GOE~\cite{Mehta2004book}
\begin{align}
	\label{eq_Y2_GOE}
	\begin{split}
		Y_2^\mathrm{GOE}(\Ecal) &= \del{\frac{\pi}{2}\mathrm{sgn}(\Ecal) - \mathrm{Si}(\pi \Ecal)} \del{\frac{\cos\pi \Ecal}{\pi \Ecal} - \frac{\sin \pi \Ecal}{(\pi \Ecal)^2}}\\ &+ \del{\frac{\sin \pi \Ecal}{\pi \Ecal}}^2
	\end{split}
\end{align}
where $\mathrm{sgn}(x)$ is the Signum function and $\mathrm{Si}(x)$ is the sine integral. In case of a SC matrix, the superposition of two GOE spectra leads to a two-level cluster function~\cite{Pandey2019Arxiv}
\begin{align}
	\label{eq_Y2_SC}
	Y_2^\mathrm{SC}(\Ecal) = \frac{1}{2} Y_2^\mathrm{GOE}\del{\frac{\Ecal}{2}}
\end{align}

The inverse Fourier transform of the two-level cluster function gives the two-level form factor, a function in the dimensionless time domain, $\tau$
\begin{align}
	\label{eq_def_b2}
	b_2(\tau) = \int_{-\infty}^{\infty} d\Ecal\: Y_2(\Ecal) \cos(2\pi \tau \Ecal)
\end{align}
where the symmetry of $Y_2(\Ecal)$ around $\Ecal = 0$ reduces the complex integral to a real one~\cite{Buijsman2020}. The two-level form factor controls the long time dynamics of a generic observable~\cite{Schiulaz2019}. For Poisson ensemble, $b_2(\tau) = 0$ at any time while for GOE
\begin{align}
	\label{eq_b2_GOE}
	b_2^{\mathrm{GOE}}(\tau) &= \begin{cases}
		1 - 2\tau + \tau\log\del{1 + 2\tau}, & \tau\leq 1,\\
		\tau\log \left( \dfrac{2\tau + 1}{2\tau - 1} \right) - 1, &\tau > 1 .
	\end{cases}
\end{align}
Then, Eq.~\eqref{eq_Y2_SC} implies that the two-level form factor of a SC matrix is $b_2^\mathrm{SC}(\tau) = b_2^{\mathrm{GOE}}(2\tau)$.

To identify different energy scales in a system, one of the most useful measure is the number variance, defined for a set of unfolded energies, $\cbr{\Ecal_j}$ as~\cite{Das2025a},
\begin{align}
	\begin{split}
		\Sigma^2(\Ecal) &= \mean{ [\mathcal{N}(\Ecal, \Ecal_0) - \Ecal]^2}_{\Ecal_0}\\
		\mathcal{N}(\Ecal, \Ecal_0) &= I\del{\Ecal_0 + \frac{\Ecal}{2}} - I\del{\Ecal_0 - \frac{\Ecal}{2}}
	\end{split}
	\label{eq_nvar}
\end{align}
where $I(\Ecal)$ is the cumulative distribution of the unfolded energy levels and $\mathcal{N}(\Ecal, \Ecal_0)$ is the number of energy levels in the window of span $\Ecal$ and centered at $\Ecal_0$. For GOE, the energy spectrum is rigid so that any two energy levels are correlated and the number variance has a logarithmic behavior~\cite{Mehta2004book}
\begin{align}
	\label{eq_num_var_GOE}
	\begin{split}
		\Sigma^2_\mathrm{GOE}(\Ecal) = \frac{2}{\pi^2} \log\del{ 2\pi \Ecal + \gEM + 1 - \frac{\pi^2}{8} } + \mathcal{O}\del{\frac{1}{\Ecal}}% &= \frac{2}{\pi^2}\del{ 1 + \gEM + \log(2\pi\Ecal) + \pi^2 \Ecal - \cos (2\pi\Ecal) - \mathrm{Ci}(2\pi\Ecal) - 2\pi\Ecal \mathrm{Si}(2\pi\Ecal) - \frac{\pi}{2}\mathrm{Si}(\pi\Ecal) + \frac{\mathrm{Si}^2(\pi\Ecal)}{2} }
	\end{split}
\end{align}
where $\gEM = 0.577216\dots$ is the Euler-Mascheroni constant, $\mathrm{Ci}(x) = -\int_{x}^{\infty}dt \frac{\cos t}{t}$ and $\mathrm{Si}(x) = \int_{0}^{x}dt \frac{\sin t}{t}$. Contrarily in the Poisson ensemble, the number of unfolded energy levels are free to fluctuate around their mean position, $\mean{\mathcal{N}(\Ecal, \Ecal_0)}_{\Ecal_0} = \Ecal$ and the number variance exhibits a linear behavior, $\Sigma^2(\Ecal) = \Ecal$. In case of a SC matrix, superposition implies that the number variance follows~\cite{Pandey2019Arxiv}
\begin{align}
	\label{eq_nvar_SC}
	\Sigma^2_\mathrm{SC}(\Ecal) = 2 \Sigma^2_\mathrm{GOE}\del{\frac{\Ecal}{2}}
\end{align}
In Fig.~\ref{fig_SC_s_numvar}(b), we plot the numerically obtained number variance of SC ensemble for $N = 2048$ along with the analytical expression from Eq.~\eqref{eq_nvar_SC} and find an excellent agreement. 

