\subsubsection{Phase diagram from fermionic Hamiltonian}

In the main text, we obtain the phase diagram by exactly diagonalizing the fermionic Hamiltonian \eqref{fermionicH}. Here we provide the details of the derivation. 

Firstly we define complex fermion 
\begin{equation}
f_{n}^{\dagger}=\frac{1}{2}(\tilde{\eta}_{n}^{\beta}+i\tilde{\eta}_{n}^{\alpha}),
\end{equation}
such that $\tilde{\eta}_{n}^{\beta}=f_{n}+f_{n}^{\dagger}$, $\tilde{\eta}_{n}^{\alpha}=i(f_{n}-f_{n}^{\dagger})$. The Hamiltonian \eqref{fermionicH} can be written as
\begin{equation}
\mathcal{H}_{v}^{(d)}=\sum_{n=1}^{2N}\left[(J_{x}\tau_{n}-J_{y})(f_{n}+f_{n}^{\dagger})(f_{n}-f_{n}^{\dagger})+J_{z}\tau_{n}\right]+\sum_{n=1}^{2N-1}(K+\tilde{K}\tau_{n}\tau_{n+1})(f_{n}-f_{n}^{\dagger})(f_{n+1}+f_{n+1}^{\dagger}).
\end{equation}
Only phases which preserve part of the translational symmetry are considered. To this end, we pick the unit cell containing two $f$ fermions, and rename
\begin{equation}
f_{2n-1}\rightarrow f_{n}^{1},\qquad f_{2n}\rightarrow f_{n}^{2},\qquad \tau_{2n-1}\rightarrow \tau_{n}^{1},\qquad \tau_{2n}\rightarrow \tau_{n}^{2}.
\end{equation}
The Hamiltonian \eqref{fermionicH} then becomes 
\begin{eqnarray}
\begin{aligned}
\mathcal{H}_{v}^{(d)}=&\sum_{n=1}^{N}(J_{x}\tau_{n}^{1}-J_{y})(2f_{n}^{1\dagger}f_{n}^{1}-1)+(J_{x}\tau_{n}^{2}-J_{y})(2f_{n}^{2\dagger}f_{n}^{2}-1)+J_{z}(\tau_{n}^{1}+\tau_{n}^{2})\\&+(K+\tilde{K}\tau_{n}^{1}\tau_{n}^{2})\bigg(f_{n}^{1}f_{n}^{2}-f_{n}^{1\dagger}f_{n}^{2}+f_{n}^{1}f_{n}^{2\dagger}-f_{n}^{1\dagger}f_{n}^{2\dagger}\bigg)\\
&+\sum_{n=1}^{N-1}(K+\tilde{K}\tau_{n}^{2}\tau_{n+1}^{1})\bigg(f_{n}^{2}f_{n+1}^{1}-f_{n}^{2\dagger}f_{n+1}^{1}+f_{n}^{2}f_{n+1}^{1\dagger}-f_{n}^{2\dagger}f_{n+1}^{1\dagger}\bigg).
\end{aligned}
\end{eqnarray}
Due to the assumed translational symmetry, a Fourier transform can be performed by defining 
\begin{equation}
f_{n}^{\dagger}=\frac{1}{\sqrt{N}}\sum_{k}f_{k}^{\dagger}e^{ikn},\qquad f_{n}=\frac{1}{\sqrt{N}}\sum_{k}f_{k}e^{-ikn}.
\end{equation}
The range of $k$ is taken to be $(-\pi,\pi)$. For every unit cell, the values of $\tau^{1}$ and $\tau^{2}$ are fixed, so can be treated as independent of the position, therefore we have 
\begin{eqnarray}
\label{fIsing}
\begin{aligned}
\mathcal{H}_{v}^{(d)}=\sum_{k}&(J_{x}\tau^{1}-J_{y})(2f_{k}^{1\dagger}f_{k}^{1}-1)+(J_{x}\tau^{2}-J_{y})(2f_{k}^{2\dagger}f_{k}^{2}-1)+J_{z}(\tau^{1}+\tau^{2})\\
&+(K+\tilde{K}\tau^{1}\tau^{2})\bigg(f_{k}^{1}f_{-k}^{2}-f_{k}^{1\dagger}f_{k}^{2}+f_{k}^{1}f_{k}^{2\dagger}-f_{k}^{1\dagger}f_{-k}^{2\dagger}\bigg)\\
&+(K+\tilde{K}\tau^{1}\tau^{2})\bigg(f_{k}^{2}f_{-k}^{1}e^{ik}-f_{k}^{2\dagger}f_{k}^{1}e^{-ik}+f_{k}^{2}f_{k}^{1\dagger}e^{ik}-f_{k}^{2\dagger}f_{-k}^{1\dagger}e^{-ik}\bigg).
\end{aligned}
\end{eqnarray}
To simplify the notations we introduce coupling constants $J_{1}=J_{x}\tau^{1}-J_{y}$, $J_{2}=J_{x}\tau^{2}-J_{y}$, $K_{1}=K+\tilde{K}\tau^{1}\tau^{2}$. The Hamiltonian can then be written in a matrix form, 
\begin{equation}
\label{fIsingmatrix}
\mathcal{H}_{v}^{(d)}=\sum_{k}\left(\begin{array}{cccc}
f_{k}^{1\dagger}&f_{k}^{2\dagger}&f_{-k}^{1}&f_{-k}^{2}
\end{array}\right)\hat{\mathbf{H}}_{k}\left(\begin{array}{c}
f_{k}^{1}\\f_{k}^{2}\\f_{-k}^{1\dagger}\\f_{-k}^{2\dagger}
\end{array}\right)+J_{z}(\tau^{1}+\tau^{2}),
\end{equation}
the matrix $\hat{\mathbf{H}}_{k}$ is given by
\begin{equation}
\hat{\mathbf{H}}_{k}=\left(\begin{array}{cccc}
J_{1}&-\frac{1}{2}K_{1}(1+e^{ik})&0&-\frac{1}{2}K_{1}(1-e^{ik})\\
-\frac{1}{2}K_{1}(1+e^{-ik})&J_{2}&\frac{1}{2}K_{1}(1-e^{-ik})&0\\
0&\frac{1}{2}K_{1}(1-e^{ik})&-J_{1}&\frac{1}{2}K_{1}(1+e^{ik})\\
-\frac{1}{2}K_{1}(1-e^{-ik})&0&\frac{1}{2}K_{1}(1+e^{-ik})&-J_{2}
\end{array}\right)
\end{equation}
The phase diagram is thus obtained by comparing ground-state energies of the fermionic Hamiltonian evaluated on a grid of $k$-space with different values of $\tau^{1}$ and $\tau^{2}$.

\begin{figure}
\includegraphics[width=0.45\textwidth]{FigS2a.pdf}
\includegraphics[width=0.45\textwidth]{FigS2b.pdf}
\caption{Comparison between phase diagrams of the vertical ladder obtained in two different ways with $\tilde{K}=0.8$, $J_{x}=J_{y}=1$. Left: from exact calculation of fermionic ground states; Right: from numerical diagonalization on a system of 16 spins (open boundary condition).}
\label{figcompare}
\end{figure}

The vertical ladder can be mapped into a free fermion model and thus enjoys exact solvability. For the horizontal ladder, the only way to obtain the phase diagram is by diagonalizing the spin Hamiltonian on a finite lattice. The vertical ladder is thus an ideal platform to study the finite-size effect. To this end, we adopt another way to obtain the phase diagram of the vertical ladder, namely by diagonalization of \eqref{transverseising} on a system of 16 spins. The phase diagrams of the vertical ladder obtained by the two methods are compared in Fig. \ref{figcompare}, from which the finite-size effect of the direct diagonalization of spin Hamiltonian is evident. In particular the phase boundaries of the ``staggered" and ``CP" phases are moved to the left.


\subsection{The horizontal ladder}


For the horizontal ladder, the lattice geometry is taken as half-infinite and has an extra spin site for definition purpose, we name this site 0 and label the spins with numbers as shown in Fig. \ref{figSladder}. The spin Hamiltonian \eqref{horizontalH} can be written explicitly as
\begin{equation}
\mathcal{H}_{h}^{(d)}=\sum_{n=0}\left[J_{x}\sigma_{2n}^{x}\sigma_{2n+1}^{x}+J_{y}\sigma_{2n}^{y}\sigma_{2n+1}^{y}+J_{z}\sigma_{2n}^{z}\sigma_{2n+1}^{z}\right]+\sum_{n=1}\left[K\sigma_{2n-1}^{z}\sigma_{2n}^{z}+\tilde{K}\sigma_{2n-1}^{z}\sigma_{2n+2}^{z}\right].
\end{equation}
In the following we assume the coupling on bond $(0,1)$ to be zero so that the spin on site 0 does not couple to the ladder. Using Jordan-Wigner transformation (\ref{JWtrans}) with the starting point of string operator $s=0$, we have 
\begin{eqnarray}
\begin{aligned}
\mathcal{H}_{h}^{(d)}=&\sum_{n=0}\left[J_{x}(-)\eta_{2n}^{\beta}\eta_{2n+1}^{\alpha}\eta_{2n}^{\alpha}\eta_{2n+1}^{\beta}+J_{y}(-i)\eta_{2n+1}^{\alpha}\eta_{2n}^{\beta}+J_{z}i\eta_{2n+1}^{\beta}\eta_{2n}^{\alpha}\right]\\&+\sum_{n=1}\left[Ki\eta_{2n}^{\beta}\eta_{2n-1}^{\alpha}+\tilde{K}(-i)\eta_{2n+2}^{\beta}\eta_{2n-1}^{\alpha}\eta_{2n}^{\alpha}\eta_{2n}^{\beta}\eta_{2n+1}^{\alpha}\eta_{2n+1}^{\beta}\right].
\end{aligned}
\end{eqnarray}
The model has conserved quantities $\tau_{n}=\sigma_{2n}^{z}\sigma_{2n+1}^{z}=-i\eta_{2n}^{\alpha}\eta_{2n+1}^{\beta}$, with which the Hamiltonian is written as
\begin{equation}
\label{Hhorizontalf}
\mathcal{H}_{h}^{(d)}=\sum_{n=0}\left[(J_{y}-J_{x}\tau_{n})i\eta_{2n}^{\beta}\eta_{2n+1}^{\alpha}+J_{z}\tau_{n}\right]+\sum_{n=1}\left[K(-i)\eta_{2n-1}^{\alpha}\eta_{2n}^{\beta}+\tilde{K}(-\tau_{n})\eta_{2n-1}^{\alpha}\eta_{2n}^{\beta}\eta_{2n+1}^{\alpha}\eta_{2n+2}^{\beta}\right].
\end{equation}
Then we group together sites $(2n,2n+1)$ with $n=0,1,2,\cdots$, and redefine $\eta_{2n}^{\beta}\rightarrow \tilde{\eta}_{n}^{\beta}$ and $\eta_{2n+1}^{\alpha}\rightarrow \tilde{\eta}_{n}^{\alpha}$. The Hamiltonian becomes
\begin{equation}
\mathcal{H}_{h}^{(d)}=\sum_{n=0}\left[(J_{y}-J_{x}\tau_{n})i\tilde{\eta}_{n}^{\beta}\tilde{\eta}_{n}^{\alpha}+J_{z}\tau_{n}\right]+\sum_{n=1}\left[K(-i)\tilde{\eta}_{n-1}^{\alpha}\tilde{\eta}_{n}^{\beta}+\tilde{K}(-\tau_{n})\tilde{\eta}_{n-1}^{\alpha}\tilde{\eta}_{n}^{\beta}\tilde{\eta}_{n}^{\alpha}\tilde{\eta}_{n+1}^{\beta}\right].
\end{equation}
Next we introduce the first-order spin $\boldsymbol{S}_{n}$ for each pair by a new set of JW transformation 
\begin{equation}
\tilde{\eta}_{n}^{\alpha}=S_{n}^{y}\prod_{j=0}^{n-1}(-S_{j}^{x}),\qquad \tilde{\eta}_{n}^{\beta}=S_{n}^{z}\prod_{j=0}^{n-1}(-S_{j}^{x}),\qquad i\tilde{\eta}_{n}^{\beta}\tilde{\eta}_{n}^{\alpha}=S_{n}^{x}.
\end{equation}
Using this the Hamiltonian (\ref{Hhorizontalf}) becomes Eq. \eqref{HtwoS}, namely
\begin{equation}
\mathcal{H}_{h}^{(d)}=\sum_{n=0}\left[(J_{y}-J_{x}\tau_{n})S_{n}^{x}+J_{z}\tau_{n}\right]+\sum_{n=1}\left[KS_{n-1}^{z}S_{n}^{z}+\tilde{K}\tau_{n}S_{n-1}^{z}S_{n+1}^{z}\right].
\end{equation}
This Hamiltonian with static distribution of $\{\tau_{n}\}$ involves Ising interaction of second-nearest neighbours, making it the ANNNI model. 

For the next step we look for relations between the first-order spin $\boldsymbol{S}$ and the zeroth-order spin $\boldsymbol{\sigma}$. To do this we note that 
$S_{n}^{z}=\eta_{2n}^{\beta}\prod_{j=0}^{n-1}(-i\eta_{2j}^{\beta}\eta_{2j+1}^{\alpha})$ and $\sigma_{2n}^{z}=\eta_{2n}^{\beta}\prod_{j=0}^{2n-1}(i\eta_{j}^{\alpha}\eta_{j}^{\beta})$; so we have 
\begin{eqnarray}
\begin{aligned}
\sigma_{2n}^{z}=&\eta_{2n}^{\beta}(-i\eta_{0}^{\beta}\eta_{0}^{\alpha})(-i\eta_{1}^{\beta}\eta_{1}^{\alpha})(-i\eta_{2}^{\beta}\eta_{2}^{\alpha})(-i\eta_{3}^{\beta}\eta_{3}^{\alpha})\cdots (-i\eta_{2n-1}^{\beta}\eta_{2n-1}^{\alpha})\\
=&S_{n}^{z}\tau_{0}\tau_{1}\cdots\tau_{n-1}.
\end{aligned}
\end{eqnarray}
Using $\tau_{n}=\sigma_{2n}^{z}\sigma_{2n+1}^{z}=-i\eta_{2n}^{\alpha}\eta_{2n+1}^{\beta}$, this becomes the first part of the relation,
\begin{equation}
S_{n}^{z}=\prod_{j=0}^{2n}\sigma_{j}^{z}.
\end{equation}
On the other hand we have the second part of the relation $S_{n}^{x}=\sigma_{2n}^{y}\sigma_{2n+1}^{y}$ for the same reason as the vertical ladder, see Eq. \eqref{Srelationsigma}. 

Here the {\it dipole parity} can also be defined, namely $\mathcal{I}=\prod_{n=0}S_{n}^{z}=\prod_{n=0}\prod_{j=0}^{2n}\sigma_{j}^{z}$, satisfying $\{S_{n}^{x},\mathcal{I}\}=0$. Explicitly the dipole parity can be written as $\mathcal{I}=\prod_{j}(\sigma_{j}^{z})^{N-x_{j}}$, where $x_{j}$ is the {\it effective coordinate} of the spin site $j$, which coincides with the $x$-coordinates of the sites in the horizontal geometry shown in Fig. \ref{figladders}. 




\section*{Dynamical structural factor}

The zero-temperature dynamical structural factor can be used to distinguish the phases of the ladder models. Here we derive the results in the main text.


By definition, the zero-temperature dynamical structural factor for spin chain is
\begin{equation}
\label{DSFchain}
D^{\alpha\beta}_{0}(q,\omega)=\frac{1}{N}\sum_{j,l=1}^{N}\int_{-\infty}^{\infty}dt e^{iql+i\omega t}\langle S_{j}^{\alpha}(t)S_{j-l}^{\beta}(0)\rangle.
\end{equation}
Here we denote the structural factor by $D$ instead of the standard $S$ to avoid confusion with the spin.
For the 2D spin ladder we are considering, the zero-temperature dynamical structural factor is given by
\begin{equation}
\label{DSFladder}
D^{zz}(q_{x},q_{y},\omega)=\frac{1}{2N}\sum_{j,l=1}^{N}\sum_{y,y'=0,1}\int dt e^{i\omega t}e^{iq_{x}l+iq_{y}(y-y')}\langle S_{j+l,y}^{z}(t)S_{j,y'}^{z}(0)\rangle.
\end{equation}

\subsection{The vertical ladder}

For the vertical ladder, the sum over $y,y'$ in \eqref{DSFladder} can be done before the integration and gives
\begin{equation}
D^{zz}(q_{x},q_{y},\omega)=\frac{1}{2N}\sum_{j,l=1}^{N}\int dt e^{i\omega t+iq_{x}l}\left[\sum_{y,y'=0,1}e^{iq_{y}(y-y')}\langle S_{j+l,y}^{z}(t)S_{j,y'}^{z}(0)\rangle\right].
\end{equation}
If the system is in the {\it dipole phase}, namely $S_{i,1}^{z}\equiv -S_{i,0}^{z}$, the dynamical structural factor is 
\begin{equation}
D^{zz}(q_{x},q_{y},\omega)=(1-\cos q_{y})\frac{1}{N}\sum_{j,l=1}^{N}\int dt e^{i\omega t+iq_{x}l}\langle S_{j+l,0}^{z}(t)S_{j,0}^{z}(0)\rangle=(1-\cos q_{y})D_{0}^{zz}(q_{x},\omega).
\end{equation}
If it is in the {\it charge-pair phase}, namely $S_{i,1}^{z}\equiv S_{i,0}^{z}$, the dynamical structural factor is 
\begin{equation}
D^{zz}(q_{x},q_{y},\omega)=(1+\cos q_{y})\frac{1}{N}\sum_{j,l=1}^{N}\int dt e^{i\omega t+iq_{x}l}\langle S_{j+l,0}^{z}(t)S_{j,0}^{z}(0)\rangle=(1+\cos q_{y})D_{0}^{zz}(q_{x},\omega).
\end{equation}
To summarize, if $S_{i,1}^{z}\equiv \pm S_{i,0}^{z}$, the dynamical structural factor is 
\begin{equation}
D^{zz}(q_{x},q_{y},\omega)=(1\pm\cos q_{y})D_{0}^{zz}(q_{x},\omega).
\end{equation}
In the above, $D_{0}^{zz}(q_{x},\omega)$ is the dynamical structural factor for the Ising chain defined in \eqref{DSFchain}.

\subsection{The horizontal ladder}

We now move on to the zero-temperature dynamical structural factor for the horizontal ladder. By definition we label the unit cells of the lattices by its coordinates $(x,y)$; inside each unit cell, the two sites are labelled by 0 and 1. The dynamical structural factor \eqref{DSFladder} can be written as
\begin{eqnarray}
\begin{aligned}
D^{zz}(q_{x},q_{y},\omega)=&\frac{1}{2N}\sum_{x,x'}\sum_{y,y'}\int dt e^{i\omega t}e^{iq_{y}(y-y')}e^{iq_{x}(x-x')}\big[\langle S_{x,0,y}^{z}(t)S^{z}_{x',0,y'}(0)\rangle\\&+\langle S_{x,0,y}^{z}(t)S_{x',1,y'}^{z}(0)\rangle e^{-iq_{x}}+\langle S_{x,1,y}^{z}(t)S_{x',0,y'}^{z}(0)\rangle e^{iq_{x}}+\langle S_{x,1,y}^{z}(t)S_{x',1,y'}^{z}(0)\rangle\big].
\end{aligned}
\end{eqnarray}
For the {\it dipole phase} of the horizontal ladder, we have $S_{x,1,y}\equiv -S_{x,0,y}$ for all unit cells. So the dynamical structural factor reads
\begin{eqnarray}
\begin{aligned}
D^{zz}(q_{x},q_{y},\omega)&=(1-\cos q_{x})\bigg[\frac{1}{N}\sum_{x,x'}\sum_{y,y'}\int dt e^{i\omega t}e^{iq_{y}(y-y')+iq_{x}(x-x')}\langle S^{z}_{x,0,y}(t)S^{z}_{x',0,y'}(0)\rangle\bigg]\\
&=(1-\cos q_{x})\tilde{D}^{zz}(q_{x},q_{y},\omega).
\end{aligned}
\end{eqnarray}
In the {\it charge-pair phase} of the horizontal ladder, we have $S_{x,1,y}\equiv S_{x,0,y}$ for all unit cells. So the dynamical structural factor is given by
\begin{eqnarray}
\begin{aligned}
D^{zz}(q_{x},q_{y},\omega)&=(1+\cos q_{x})\bigg[\frac{1}{N}\sum_{x,x'}\sum_{y,y'}\int dt e^{i\omega t}e^{iq_{x}(x-x')+iq_{y}(y-y')}\langle S^{z}_{x,0,y}(t)S^{z}_{x',0,y'}(0)\rangle\bigg]\\
&=(1+\cos q_{x})\tilde{D}^{zz}(q_{x},q_{y},\omega).
\end{aligned}
\end{eqnarray}
In the above, $\tilde{D}^{zz}(q_{x},q_{y},\omega)$ represents the zero-temperature dynamical structural factor for a zig-zag ANNNI model. To summarize, if $S_{x,1,y}^{z}\equiv \pm S_{x,0,y}^{z}$, the zero-temperature dynamical structural factor for the horizontal ladder is 
\begin{equation}
D^{zz}(q_{x},q_{y},\omega)=(1\pm\cos q_{x})\tilde{D}^{zz}(q_{x},q_{y},\omega).
\end{equation}

Experimentally, the {\it dipole phase} and the {\it charge-pair phase} are distinguished by the {\it zeros} of the dynamical structural factor. 


\section*{The quadrupole model and beyond}

\subsection{Phases of the quadrupole model}

The configurations of one plaquette with four spins $\sigma_{4n-3}$ to $\sigma_{4n}$ in the quadrupole model \eqref{higherorderH} can be classified by two first-order $\mathbb{Z}_{2}$ quantities $\tau_{2n-1}=\sigma_{4n-3}^{z}\sigma_{4n-2}^{z}$ and $\tau_{2n}=\sigma_{4n-1}^{z}\sigma_{4n}^{z}$ and one second-order $\mathbb{Z}_{2}$ quantity $T_{n}=S_{2n-1}^{z}S_{2n}^{z}=\sigma_{4n-2}^{z}\sigma_{4n-1}^{z}$. We name the configurations with two parts. The first part reflects the values of the two $\tau$; if they both equal to $-1$, then we call it ``dipole"; if they both equal to $+1$, we call it ``charge-pair (CP)"; if they are not equal, we call it ``staggered". The second part reflects the value of $T$, for $T=-1$ it is ``dipole" and for $T=+1$ it is ``charge-pair (CP)". One special example is for $\tau_{2n-1}=\tau_{2n}=T_{n}=-1$, then the configuration is ``dipole-dipole" which is naturally ``quadrupole". In the table below we list all the possible configurations determined by $\tau$ and $T$, and give pictorial examples for each case. 

