  \section{Fixed point theorem  with application to a satellite web coupling problem }

  In this section, we present a fixed point theorem in  fuzzy $ \mathscr{F}$- metric space setting that provides a useful criterion for existence of unique fixed point of self-mappings in fuzzy metric spaces that generalizes classical results by incorporating the notion of fuzzy contractions. 

  \begin{dfn}
  Let $ ( X, M,  f, \alpha, \star ) $ be a fuzzy $ \mathscr{F} $-metric space. A mapping $ T : X \to X $   is said to be a    fuzzy $ \psi$-contraction mapping with respect to the  function $ \psi \in \Psi $ if the following implication   holds:
  $$ 0 < M ( x, y, t ) <  1 \implies M ( Tx, Ty, t ) \geq \psi ( M ( x, y, t ) ) $$
  for all $ x, y \in X $ and $t> 0 $. 
  \end{dfn}




  \begin{thm} \label{main thm}
  	Let $ ( X, M, f, \alpha, \star  ) $ be an $ \mathscr{F} $-complete fuzzy $ \mathscr{F} $-metric space and   $ T  $     be a    fuzzy $ \psi$-contraction mapping with respect to some  function $ \psi \in \Psi $ such that   there exists $ y \in X $ satisfying  $ 0 < M ( y, T y, t ) <  1 ~ \forall t > 0 $. Then $ T $ has   { at most } one fixed point in $X$. 
  \end{thm}
  %
 \begin{proof}
	Let $ x \in X $ be such that $ 0 < M ( x, T x, t ) <  1 ~ \forall t > 0 $ and define $x_n = T^n x, ~ n \in \mathbb{N} \cup \{ 0 \} $. If $ T ( x_k ) = x_k $ for some $ k \in \mathbb{N} \cup \{ 0 \} $ then the proof is done.  So suppose $ T ( x_r ) \ne  x_r $ for all $ r \in \mathbb{N} \cup \{ 0 \} $. 

	Since $T$ is a fuzzy $ \psi$-contraction mapping then for the sequence $ \{ x_n \} $, we have 
	$$ M ( x_{n+2}, x_{n+1}, t ) \geq \psi \left( M ( x_{n+1}, x_{n}, t )\right) ~~  \forall n \in \mathbb{N} \cup \{ 0 \} ~ \& ~ t > 0.  $$ 
	%

	Repeating the above relation, for any $ m \geq 2 $ we get
	$$ M ( x_{m+1}, x_m, t ) \geq  \psi ( M ( x_{m }, x_{m-1}, t ) ) \geq \psi^2 ( M ( x_{m - 1}, x_{m- 2}, t ) )  \geq \cdots \geq \psi^m  ( M ( x_{ 1}, x_{0}, t ) ) ~~ \forall t> 0.  $$ 
	% 

	Taking limit as $ m \to \infty $ and using Lemma \ref{prop of si 2} in the above relation, we get 
	\begin{align}\label{main thm 1}
		&  \underset{m \to \infty  }{\lim } M ( x_{m+1}, x_m, t ) \geq \underset{m \to \infty  }{\lim } \psi^m  ( M ( x_{ 1}, x_{0}, t ) )  = 1 ~~ ~~ \forall t> 0         \nonumber \\
		\implies & \underset{m \to \infty  }{\lim } M ( x_{m+1}, x_m, t ) = 1  ~~ ~~ \forall t> 0.
	\end{align} 
	%

	Proceeding in this way, we obtain 
	\begin{equation} \label{main thm 4}
		 \underset{m \to \infty  }{\lim } M ( x_{m+i}, x_{m+i -1}, t ) = 1  ~~ ~~ \forall t> 0 ~ \& ~ i \geq 1.
	\end{equation} 
	%
	Next we show that $ \{ x_r \}$ is a Cauchy sequence in $ ( X, M, f, \alpha, \star  ) $. 

	Now using the inequality $ ( \mathscr{F}M4)$, for any $ m  \in \mathbb{N} $ and $ p = 1, 2, 3, \ldots $,  we have
	\begin{equation} \label{main thm 5} 
		(f ( M ( x_{ m+ p }, x_{m}, t ) ))^\alpha \geq f ( M ( x_{m+p}, x_{m+p-1}, \frac{ t }{  p } ) \star \cdots \star M ( x_{m+ 2}, x_{m + 1}, \frac{ t }{ p} ) \star M ( x_{m+1}, x_m, \frac{ t }{ p } ) )    
	\end{equation}
 	%

	Applying the relation (\ref{main thm 4}) on (\ref{main thm 5}), we get  
	 $$ \underset{m \to \infty  }{\lim }\{ M ( x_{m+p}, x_{m+p-1}, \frac{ t }{ p } ) \star \cdots    \star M ( x_{m+1}, x_m, \frac{ t }{ p} ) \} = 1,  ~ \forall t> 0 ~ \& ~ p = 1,2, 3, \ldots. $$
	 %

	 This implies 
	\begin{align*}
	  & \underset{m \to \infty  }{\lim } f ( M ( x_{m+p}, x_{m+p-1}, \frac{ t }{ p } ) \star \cdots   \star M ( x_{m+1}, x_m, \frac{ t }{ p} )  ) = 1,  ~ \forall t> 0 ~ ~ (\text{by } ~ (\mathscr{F}2)) \\
	or ~~ & 	\underset{m \to \infty  }{\lim } ~ (f ( M ( x_{ m+ p }, x_{m}, t ) ))^\alpha \geq 1 ~~~ \forall t> 0 ~~ (\text{by} ~( \ref{main thm 5})) \\
	or ~~ & \underset{m \to \infty  }{\lim } ~ (f ( M ( x_{ m+ p}, x_{m }, t ) ))^\alpha = 1 ~~~ \forall t> 0 \\
	or ~~ & \underset{m \to \infty  }{\lim } ~ (f ( M ( x_{ m+p }, x_{m}, t ) ))  = 1 ~~~ \forall t> 0 \\
	or ~~ & \underset{m \to \infty  }{\lim } ~  M ( x_{ m + p }, x_{m}, t )  = 1 ~~~ \forall t> 0. 
\end{align*} 
% 

This proves that $ \{ x_m \}$ is a Cauchy sequence in $ ( X, M, f, \alpha, \star  ) $.  Since $X$ is $ \mathscr{F}$-complete, so $ \{ x_m \}$ converges to some $ u \in X $.  
Therefore,
$$ \underset{m \to \infty  }{\lim } ~  M ( x_{ m  }, u, t )  = 1 ~~~ \forall t> 0.  $$

Next we claim that $ u   $ is a fixed point of $T$. If possible suppose there exists $ t_0 > 0$ such that 
\begin{equation}\label{main thm 2}
	M ( u, Tu, t_0 ) < 1. 
\end{equation}
%

Then we have,
\begin{equation}\label{main thm 3}
	 (	f ( M ( u, Tu, t_0 ) ))^\alpha \geq f ( M ( u, x_m, \frac{t_0}{2} ) \star M ( x_m, Tu, \frac{t_0}{2} )) ~~~\forall m \in \mathbb{N}.
\end{equation}
%

Again,
\begin{align*}
  &   M ( x_m, Tu, \frac{t_0}{2} ) \geq \psi ( M ( x_{m - 1 }, u, \frac{t_0}{2} ) ) ~~~\forall m\in \mathbb{N} \\ 
\implies & \underset{m \to \infty  }{\lim } ~ M ( x_m, Tu, \frac{t_0}{2} ) \geq \underset{m \to \infty  }{\lim }  ~ \psi ( M ( x_{m - 1 }, u, \frac{t_0}{2} ) ) = 1 ~~~(\text{using  Lemma} ~ \ref{prop of si 2}) \\
\implies & \underset{m \to \infty  }{\lim } ~ M ( x_m, Tu, \frac{t_0}{2} )  = 1. 
\end{align*}

 Therefore,  
 \begin{align*}
 & \underset{m \to \infty  }{\lim } ~ M ( u, x_m, \frac{t_0}{2} ) \star M ( x_m, Tu, \frac{t_0}{2} )  = 1 \\
\implies & \underset{m \to \infty  }{\lim } ~ f ( M ( u, x_m, \frac{t_0}{2} ) \star M ( x_m, Tu, \frac{t_0}{2} )) = 1 ~~~ (\text{using}~ (\mathscr{F}2))  \\
\implies & \underset{m \to \infty  }{\lim } ~  (	f ( M ( u, Tu, t_0 ) ))^\alpha \geq 1 ~~~ (\text{using the relation }~  (\ref{main thm 3}))   \\
\implies &   M ( u, Tu, t_0 ) = 1   ~~~ (\text{using}~ (\mathscr{F}2)).
\end{align*}

Thus we arrived at a contradiction to the relation (\ref{main thm 2}). Therefore $ u $ is a fixed point of $T$. 

To prove the uniqueness of the fixed point, suppose there exists an element $ v \in X $ with $ u \neq v $ such that $T v = v $. Since $ v \neq u $, so there exists $ s > 0 $ such that $ M ( u, v, s ) < 1 $. In that case, we get 
$$ M ( u, v, s ) = M ( T u, T v, s ) \geq \psi ( M ( u, v, s ) ) > M ( u, v, s ), $$
which is a contradiction. So, $T$ has unique fixed point in $X$. 
 \end{proof}




We present the following example in the support of the  above theorem.  


 \begin{eg}
 	Consider the Example \ref{ex from 1st paper} of fuzzy $ \mathscr{F} $-metric space. Here we take  
 	 $ X = [ - 5, 5 ] $. 
 	At first we show that $ ( X, M, f, \alpha, \star )$ is complete fuzzy $ \mathscr{F} $-metric space.  For, consider a Cauchy  sequence $ \{ x_n \} $ in $ ( X, M , f, \alpha, \star ) $. 
 	Then 
 	\begin{align*}
 		& \underset{ m, n \to  \infty }{\lim} ~  M ( x_n, x_m, t) = \underset{ m, n \to  \infty }{\lim} ~ \left( \frac{t}{t+1} \right)^{|x_n-x_m|^2} = 1,   ~  ~ ~ \forall t \in ( 0, \infty ). \\
 		\implies & \underset{ m, n \to \infty }{\lim} ~ {|x_n-x_m|}^2 = 0.  \\
 	\implies 	&  \underset{ m, n \to \infty }{\lim} ~ | x_n-x_m| = 0.
 	\end{align*} 
   %
 	Therefore, $ \left\{ x_n \right\} $ is a Cauchy sequence in $ X $ with respect to usual metric .  
 	Since $ X $ is complete with respect to usual metric, so there exists $ x \in X $ such that $ \underset{ n \to \infty } \lim | x_n - x |  = 0 $ which implies
 	  $$ 	\underset{ n \to \infty } \lim M (x_n, x, t)    = \underset{ n \to  \infty } \lim  \left(   \frac{t}{1+t} \right)^{ | x_n - x|^2 }   = 1,  ~ ~ ~  \forall  t \in ( 0, \infty ). $$
   %
 This implies  $ x_n \to x ~\text{as } n \to \infty $ in $ ( X, M, f, \alpha, \star )$.   
 	Hence $ ( X, M, \textit{f}, \alpha, \star) $ is a $ \mathscr{F} $-complete fuzzy $ \mathscr{F} $-metric space.

 	Next we consider two mappings   by $ T (x) = \frac{x}{6} ~ \forall x \in X $ and  $ \psi ( t ) = \sqrt{t} ~ \forall t \in [ 0, 1 ] $.
 	Then we have
 	 $$ M ( Tx, Ty, t) = M ( \frac{x}{6}, \frac{y}{6}, t ) = \left( \frac{t}{1+t} \right)^{ \frac{|x-y|^2}{36}} ~~ \text{and} ~~ 
  \psi \left(  M ( x, y, t ) \right) = \sqrt{ M ( x, y, t ) } = \left(  \frac{t}{1+t} \right)^ { \frac{ | x-y|^2}{2} } $$
   implies
   $$ M ( Tx, Ty, t) \geq \sqrt{ M ( x, y, t )} = \psi \left(  M ( x, y, t ) \right), ~~\text{since} ~ \frac{t}{1+t} < 1. $$
   % 
 	Hence, $ T $ satisfies the fuzzy $ \psi $-contraction condition.
 	So by above  theorem  $ T $ has a unique fixed point in $ X $ which is $ x = 0 $.   

    The geometric illustration of this example is provided in Figure 1 which shows the variation between $ M ( Tx, Ty, t) $ and $  \psi \left(  M ( x, y, t ) \right) $.  In Figure 1$(a) $,   the variation is due to particular fixed value of $ t $ and  Figure 1$(b) $ shows the variation for fixed values of $ | x - y |, x, y\in X $. This visualization highlights the interplay between the mapping $T$   and the function  $ \psi $ that demonstrates  how the inequality $ M ( Tx, Ty, t) \geq  \psi \left(  M ( x, y, t ) \right) $  is sustained under the given conditions. The figure is not only for supporting  the theoretical framework of the contraction condition but also it provides an intuitive understanding of the relationship between the parameters  and  makes the main result  more comprehensible and accessible. 


