\subsection{Mathematical Formalization and Theorems}
\label{sec:mathFormalTheorems}

Having presented the conceptual framework of \emph{intrinsic observer space}, category-theoretic perspectives, and background independence in the previous sections, we now turn to a precise algebraic formalism. Our goal is to define how one observer may be mapped to another in a manner preserving the structure of state transitions and outputs, thereby showing a formal equivalence that mirrors the isomorphisms discussed earlier. We also introduce quantitative measures (complexity and adaptation speed) that capture how observers process and respond to inputs in a feedback loop. 

%--------------------------------------------------------
%--------------------------------------------------------
\subsubsection{Observer Equivalence and Invariants}

\begin{remark}
\textbf{On Commutativity and ``Homomorphisms.''} 
Strictly speaking, the mappings introduced below capture the requirement that the relevant transition diagrams \emph{commute}: for any internal state $x$ and input $y$, the map $\phi_X$ must intertwine with $f$ to preserve transitions, and $\phi_Z$ must likewise intertwine with $g$ to preserve outputs. In a category-theoretic sense, we are demanding \emph{compatibility of compositions} in a commutative diagram, rather than using the term ``homomorphism'' in a strictly group-theoretic sense.
\end{remark}

\begin{definition}[Observer Homomorphism]
\label{def:obsHomomorphism}
Let 
\[
O_1 = (X_1,\, Y_1,\, Z_1,\, f_1,\, g_1,\, \mathcal{B}_1)
\quad\text{and}\quad
O_2 = (X_2,\, Y_2,\, Z_2,\, f_2,\, g_2,\, \mathcal{B}_2)
\]
be two observers (as in Definition~\ref{def:minObs}). A \emph{homomorphism} from $O_1$ to $O_2$ is a triple of functions $(\phi_X, \phi_Y, \phi_Z)$ such that:
\begin{align*}
& \phi_X : X_1 \to X_2, \\
& \phi_Y : Y_1 \to Y_2, \\
& \phi_Z : Z_1 \to Z_2,
\end{align*}
and for all $x \in X_1$ and $y \in Y_1$, the following commutation conditions hold:
\[
\phi_X\bigl(f_1(x,y)\bigr) \;=\; f_2\bigl(\phi_X(x),\, \phi_Y(y)\bigr),
\]
\[
\phi_Z\bigl(g_1(x)\bigr) \;=\; g_2\bigl(\phi_X(x)\bigr).
\]
\end{definition}

\noindent
Intuitively, $(\phi_X,\phi_Y,\phi_Z)$ ensures that the transition function $f_1$ and output function $g_1$ in $O_1$ map in a structure-preserving way to $f_2$ and $g_2$ in $O_2$. Equivalently, we have two commutative diagrams:

\begin{figure}[ht]
\centering
\begin{tikzcd}
X_1 \times Y_1 \arrow[r, "f_1"] \arrow[d, "\phi_X \times \phi_Y"] 
& X_1 \arrow[d, "\phi_X"] \\
X_2 \times Y_2 \arrow[r, "f_2"] 
& X_2
\end{tikzcd}
\caption\centering{Commutative diagram for the transition function $f$.}
\label{fig:commDiagram_f}
\end{figure}

\begin{figure}[ht]
\centering
\begin{tikzcd}
X_1 \arrow[r, "g_1"] \arrow[d, "\phi_X"] 
& Z_1 \arrow[d, "\phi_Z"] \\
X_2 \arrow[r, "g_2"] 
& Z_2
\end{tikzcd}
\caption\centering{Commutative diagram for the output function $g$.}
\label{fig:commDiagram_g}
\end{figure}

\begin{theorem}[Equivalence Relation]
\label{thm:obsEquivalence}
Let $O_1$ and $O_2$ be two observers. Define $O_1 \sim O_2$ if and only if there exists a \emph{bijective} homomorphism $(\phi_X, \phi_Y, \phi_Z)$ between $O_1$ and $O_2$. Then $\sim$ is an equivalence relation on observers.
\end{theorem}

\begin{proof}
\textbf{Reflexivity:} 
Take $\phi_X = \mathrm{id}_{X_1}$, $\phi_Y = \mathrm{id}_{Y_1}$, $\phi_Z = \mathrm{id}_{Z_1}$. These trivially satisfy the commutation conditions in both diagrams.

\noindent
\textbf{Symmetry:} 
If $(\phi_X, \phi_Y, \phi_Z)$ is a bijection from $O_1$ to $O_2$, then $(\phi_X^{-1}, \phi_Y^{-1}, \phi_Z^{-1})$ is a bijection from $O_2$ to $O_1$, satisfying the same commutative properties in reverse.

\noindent
\textbf{Transitivity:} 
If $(\phi_X, \phi_Y, \phi_Z)$ is a bijection from $O_1$ to $O_2$ and $(\psi_X, \psi_Y, \psi_Z)$ is a bijection from $O_2$ to $O_3$, then composing them yields a bijection from $O_1$ to $O_3$ preserving all commutation requirements.

Thus, $\sim$ is an equivalence relation.
\end{proof}

\noindent
Two observers $O_1$ and $O_2$ are said to be \emph{equivalent} if they differ only by a bijective, diagram-commuting relabeling. In category-theoretic language, this corresponds to an \emph{isomorphism} between observer objects. Any property of an observer that remains invariant under such isomorphisms—e.g.\ minimal cardinalities of $X, Y, Z$, the presence of certain feedback cycles, or stable attractors—qualifies as an \emph{invariant} of the equivalence class.

