\subsection{A DMB halo model}
\label{sec:1h}
This section delineates our implementation of the DMB halo model, which was originally presented by \cite{Schneider19}, and subsequently modified by \cite{Giri21, methodpaper, Paper1, 2024OJAp....7E.108A}. 
We model the matter distribution $\rho(r,M_{200c},z, c_{200c})$ around an isolated halo at a given mass ($M_{200c}$), concentration ($c_{200c}$) and redshift ($z$)  with three components, namely
\begin{eqnarray}
    \rho(r,M_{200c},z, c_{200c}) = \rho_{\rm{gas}} (r,M_{200c},z)+\rho_{\rm{cga}} (r,M_{200c})+\rho_{\rm{clm}}(r,M_{200c},z, c_{200c}), 
\end{eqnarray}
where  $\rho_{\rm{gas}} (r,M_{200c},z)$ describes the intracluster medium, $\rho_{\rm{cga}} (r,M_{200c})$ describes stars in the central galaxy of the halo, $\rho_{\rm{clm}} (r,M_{200c},z, c_{200c})$ consists of stars in satellite galaxies and dark matter, and $r$ is the comoving distance to the halo center. 

These components depend on the total stellar fraction, $f_{\rm{star}}$, and the stellar fraction in the central galaxy, $f_{\rm{cga}}$, whose dependence on halo mass is modeled following \cite{2013MNRAS.428.3121M}: 
\begin{eqnarray}
\label{eq:star}
f_{\rm{star}} (M_{200c}) = 0.055 \left(\frac{2.5\times10^{11}~ h^{-1}M_\odot}{M_{200c}}\right)^{\eta_*}, \\
\label{eq:cga}
f_{ \rm{cga}} (M_{200c}) = 0.055 \left(\frac{2.5\times10^{11}~ h^{-1}M_\odot}{M_{200c}}\right)^{\eta_{ \rm{cga}}},
\end{eqnarray}
where $\eta_{\rm{cga}} = \eta_*+\delta\eta$.

The gas component $\rho_{\rm{gas}} (r,M_{200c},z)$ is parametrized by a cored double power law \cite{Schneider19, Giri21}
\begin{equation}
\label{eq:rhogas}
    \rho_{\rm{gas}} (r,M_{200c},z) \propto \frac{\Omega_{\rm{b}}/\Omega_{\rm{m}}-f_{\rm{star}}(M_{200c})}{\left(1+10 r/R_{200c}\right)^{\beta(M_{200c},z)} \left(1+ r/\left(R_{200c}\theta_{\rm{ej}}\right)\right)^{\left(\delta-\beta\left(M_{200c},z\right)\right)/\gamma}},
\end{equation}
where $\theta_{\rm{ej}}, \delta$, and $\gamma$ are free parameters describing the gas ejection radius and slope, and $\beta (M_{200c},z)$ is modeled as 
\begin{equation}
\label{eq:betam}
    \beta (M_{200c},z) = \frac{3}{1+(M_{c0}(1+z)^{\nu_{\rm z}}/M_{200c})^{\mu_{\beta}}}, 
\end{equation}
 where $M_{c0}$, $\nu_{\rm z}$, and ${\mu_{\beta}}$ are free parameters.

The central galaxy component described a truncated Gaussian profile \cite{Schneider19, Giri21}:
\begin{equation}
\label{eq:cg}
    \rho_{\rm{cga}} (r,M_{200c})=\frac{f_{\rm{cga}}(M_{200c})}{0.06\pi^{3/2}R_{200c}r^2} \exp \left(-\left(\frac{r}{0.03 R_{200c}}\right)^2\right).
\end{equation} 

In a gravity only simulation, collisionless matter should follow a truncated NFW profile \cite{nfw, 2011MNRAS.414.1851O}, albeit modified by the gravitational potential of the gas and central galaxy components. The timescale of the change in potential is assumed to be significantly longer than the dark matter's orbital period, so we can model the evolution as an adiabatic process. Hence, $\rho_{\rm{clm}}$ is given by \cite{Schneider19}
\begin{eqnarray}
\label{eq:clm}
    \rho_{\rm{clm}}(r,M_{200c},z, c_{200c}) &=& \left(1-\Omega_{\rm{b}}/\Omega_{\rm{m}}+f_{\rm{star}}(M_{200c})-f_{\rm{cg}}(M_{200c})\right) \rho_{\rm{nfw}}\left(r/\zeta(r,M_{200c},z, c_{200c}), c_{200c}\right)\nonumber\\
    \rho_{\rm{nfw}}(r, c_{200c})&\propto& 
    \frac{1}{\left(\frac{rc_{200c}}{R_{200c}}\right)\left(1+\frac{rc_{200c}}{R_{200c}}\right)^2} \frac{1}{\left(1+\left(\frac{r}{4R_{200c}}\right)^2\right)^2},
\end{eqnarray}
where $R_{200c}$ is the halo radius. $\zeta (r,M_{200c},z, c_{200c})$ is the root of
\begin{equation}
    \zeta -1 = 0.3\left(\left(\frac{\int_0^r\rho_{\rm{nfw}}(t,c_{200c}) t^2 dt}{\int_0^r \rho_{\rm{clm}}(t, M_{200c}, z, c_{200c}) t^2 dt + \int_0^{\zeta r} \left(\rho_{\rm{gas}}(t,M_{200c},z)+\rho_{\rm{cg}}(t,M_{200c}) \right)t^2 dt}\right)^2-1\right).
\end{equation}
Finally, $\rho_{\rm{clm}}(r,M_{200c},z, c_{200c})$ and $\rho_{\rm{gas}}(r,M_{200c},z)$ are normalized by the same factor such that 
\begin{eqnarray}
    \int_0^\infty \left(\rho_{\rm{gas}}(r)+\rho_{\rm{cga}}(r)+\rho_{\rm{clm}}(r)\right) 4\pi r^2 dr = \int_0^\infty \rho_{\rm{nfw}}(r) 4\pi r^2 dr.
\end{eqnarray}
