    \label{fig:redshiftevol}
\end{figure}

\begin{figure}
    \centering
    \includegraphics[width=\linewidth]{figs/suppression_vs_ksz_no_redshift.pdf}
    \caption{We plot the constrained suppression assuming no redshift evolution in the model in yellow, i.e. setting $\nu_z = 0$. We see that there is little effect of the redshift evolution on the level of suppression, and slightly better constraining power compared to the fiducial model, plotted in blue, and slightly better constraining power than B24, plotted in purple.}
    \label{fig:suppredshift}
