\section{Universal adjoint invariant for $T[4,n]$}

\subsection{Universal invariant explicitly}

Now we are ready to construct the universal adjoint invariant. It has the form
\be
\boxed{
\begin{array}{c}
P^{[4,n]}_{Adj}(u,v,w)\ = \ \displaystyle{  T^{8n}\over \qD_{\!_{Adj}}(u,v,w )} \Big(
2+ T^{-n}\cdot\qD_{X_2}-T^{-2n}\cdot\qD_{X_4}+T^{-2n}v^nw^n\cdot\qD_{J}
+T^{-2n}u^nw^n\cdot\qD_{J'}+\\
\\
+T^{-2n}v^nu^n\cdot\qD_{J''}
+T^{-2n}u^{3n}\cdot\qD_{Y_4}+T^{-2n}v^{3n}\cdot\qD_{Y'_4}+T^{-2n}w^{3n}\cdot\qD_{Y''_4}
-T^{-2n}u^{2n}\cdot\qD_{G}-\\
\\
-T^{-2n}v^{2n}\cdot\qD_{G'}-T^{-2n}w^{2n}\cdot\qD_{G''}+T^{-2n}u^{n}\cdot\qD_{I}+T^{-2n}v^{n}\cdot\qD_{I'}+T^{-2n}w^{n}\cdot\qD_{I''}
\Big)
\end{array}
}
\label{RJu}
\ee
