\section{Pricing-hedging duality, closure of $K^{\mcY}$ and completeness for finite dimensional exchanges}\label{sec2}

In this section we propose a friendly proof of the Collective Fundamental Theorem of Asset Pricing (CFTAP I) and the pricing-hedging duality, in a setup where exchanges among agents are allowed only on a finite dimensional vector space. 
Let $(\Omega, \mathcal{F}_T, P)$ be a (general) probability space and recall the meaning of $L^{0}(\Omega, \mathbf{F}_T, P)$ as introduced in  Notation \ref{productnotation}. 


\begin{theorem}[CFTAP I]\label{FTAP:R}
    Let $\mcY \subseteq L^{0}(\Omega, \mathbf{F}_T,P)$ be a finite dimensional  vector space containing  $\mathbb R^N_0 $. Then 
    \begin{equation*}
      \mathbf{NCA(\mathcal{Y})} \iff \Me \not = \emptyset.  
    \end{equation*}
where $\mathcal{M}_e(\mcY)$ is the set of collective equivalent martingale measures defined in \eqref{MartingaleMeasures}.
\end{theorem}

The validity of this theorem would be a direct consequence of Theorem \ref{Th1} and Item 1 in Remark \ref{remY}, contingent upon establishing the closedness of $K^{\mcY}$  in $L^{0}(\Omega, \mathbf{F}_T, P)$. This closedness will be demonstrated via a recursive procedure on the the number of vectors generating  $\mcY$ in the subsequent section. As a direct consequence of this theorem, we present in Corollary \ref{cor1} a simplified version of the CFTAP I applicable to vector spaces $\mcY$, which are not necessarily finitely generated.



For each $Y$ in $L^0(\Omega, \mathbf{F}_T,P)$,  recall that $\mathrm{span}(Y,\mathbb R^N_0 ) \subseteq L^{0 }(\Omega, \mathbf{F}_T,P)$ is the (finite dimensional) linear space generated by the single random vector $Y$ and the vector space $\mathbb R^N_0 $.  Observe that the set $\mathcal{M}_e(\mathrm{span}(Y,\mathbb R^N_0 ))$ is given by
\begin{equation*}
\left\{ Q=(Q^1,\dots,Q^N) \in {\sf X}_{i=1} ^{N}\mie   \mid Y \subseteq L^{1 }(\Omega, \mathbf{F}_T,Q)  \text { and  } \sum_{i=1}^N E_{Q^i}[Y^i]\leq 0   \right\}.
\end{equation*}
Having this in mind, we can state the following result.
\begin{corollary}\label{cor1}
    Let $\mcY \subseteq L^{0 }(\Omega, \mathbf{F}_T,P)$ be a vector space containing  $\mathbb R^N_0 $. Then 
    \begin{equation*}
      \mathbf{NCA(\mathcal{Y})} \iff  \mathcal M_e(\mathrm{span}(Y,\mathbb R^N_0 )) \neq \emptyset \quad \forall Y \in \mcY.  
    \end{equation*}
\end{corollary}

\begin{proof}
From Theorem \ref{FTAP:R} we know that $$ \mathbf{NCA}(\mathrm{span}(Y,\mathbb R^N_0 )) \iff \mathcal M_e(\mathrm{span}(Y,\mathbb R^N_0 )) \neq \emptyset. $$
   From the definition of $\mathbf{NCA}$, one can check that 
   \begin{equation*}
    \mathbf{NCA}(\mathrm{span}(Y,\mathbb R^N_0 )) \quad \forall Y \in \mcY \iff \mathbf{NCA}(\mathcal{Y} +\mathbb R^N_0  )  \iff \mathbf{NCA}(\mathcal{Y}),
   \end{equation*}
   where the last equivalence is trivial as, by assumption, $(\mathcal{Y} +\mathbb R^N_0  )=\mathcal{Y}$.
\end{proof}
\begin{remark}
Analogously, Corollary \ref{cor1} remains valid, with appropriate modifications, when a finite collection of vectors from $\mcY$ replaces the single vector $Y \in \mcY$.
\end{remark}

In order to state the collective version of the pricing-hedging duality, we recall from \cite{BDFFM25} the concept of collective super/sub replication price.

\begin{definition}[Definition 4.1 and 4.16 \cite{BDFFM25}]
    For $\mcY\subseteq L^{0}(\Omega, \mathbf{F}_T,P)$ and $(f^1,\dots,f^N)=f\in L^{0}(\Omega, \mathbf{F}_T, P)$ we define the collective superhedging and subhedging price as
\begin{align}
    \label{super:rho} \rho^{\mcY}_+(f) & =\inf\left\{\sum_{i=1}^N m_i \mid m\in\R^N \text{ and }  m+k+Y \geq f \;\text{for }  k\in {\sf X}_{i=1} ^{N}  K_i,\, Y\in \mcY \right\},
    \\ \notag \rho^{\mcY}_-(f) & =\sup\left\{ \sum_{i=1}^N m_i\mid m\in\R^N \text{ and }  m+k-Y \leq f \;\text{for }  k\in {\sf X}_{i=1} ^{N}  K_i,\, Y\in \mcY \right\}.
\end{align}
We say that $\rho^{\mcY}_+(f)$ (similarly for $\rho^{\mcY}_-(f)$) defined in \eqref{super:rho} is attained if there exists $ m\in\R^N, \, k\in {\sf X}_{i=1} ^{N}  K_i,\, Y\in \mcY $  such that $m+k+Y \geq f $ and $\rho^{\mcY}_+(f)=\sum_{i=1}^N m_i $ .
\end{definition}



We defer the reader to \cite{BDFFM25} Section 4 for the interpretation of $\rho^{\mcY}_+(f)$ and the difference with the classical superhedging price, there denoted by $\rho^N_+(f)$, of the $N $ claims $(f^1,\dots,f^N)=f$.
We also  note that when $\mcY$ is a vector space 
\begin{equation}
\label{rem:rhopm}
    \rho^{\mcY}_-(f)=-\rho^{\mcY}_+(-f)\text{ for every }f\in L^{0}(\Omega, \mathbf{F}_T,P)
\end{equation}


To handle the super-hedging duality of potentially unbounded or non-integrable contingent claim vectors $f \in L^0(\Omega, \mathbf{F}, P)$ we introduce the following convex set of vectors of martingale measures. For any arbitrary $\varphi\in L^{0}(\Omega, \mathcal{F},P)$ let
 \begin{equation}\label{Mfi}\mathcal{M}^{\varphi}_e(\mcY):=\{Q\in \mathcal{M}_e(\mcY)\mid E_{Q_i}[|\varphi^i|]<\infty\;\forall\,i=1,\ldots,N\} \subseteq \mathcal{M}_e(\mcY) .
 \end{equation}

\begin{remark}\label{remdegenerate}
    We observe that for $\mcY=\mathrm{span}(Y_1,\dots, Y_R)$ and  $\varphi^i=\max \{|Y^i_1|,\ldots, |Y^i_R|\}$ we have $\mathcal{M}^{\varphi}_e(\mcY)=\Me $. 
\end{remark}

 \begin{assumption}
 \label{ass2} $\,$


     \begin{enumerate}
         \item $\mcY $ is a finite dimensional vector space satisfying $R^N_0 \subseteq \mcY \subseteq L^{0 }(\Omega, \mathbf{F}_T,P)$, i.e. $\mcY=\mathrm{span}(Y_m,m=0,\dots,R)$, with $Y_0=R^N_0$ and $Y_m \in L^{0 }(\Omega, \mathbf{F}_T,P)$, $m=1,\dots,R$.
         \item \textbf{NCA}$(\mcY)$ holds true
     \end{enumerate}
 \end{assumption}


The Assumption \ref{ass2} in particular implies that there exists $P' \in \mathcal P_e$ such that $\mcY \subseteq L^{1 }(\Omega, \mathbf{F}_T,P')$ 
\begin{theorem}[Pricing hedging duality]\label{duality:R} Let Assumption \ref{ass2} holds true. Then 
for any $f\in L^{0}(\Omega, \mathbf{F}_T,P)$ and for any $\varphi\in L^{0}(\Omega, \mathbf{F}_T,P)$ such that  
$\max \{|f^i|,|Y^i_1|,\ldots, |Y^i_R|\}\leq \varphi^i$ we have $\mathcal{M}^{\varphi}_e(\mcY) \not= \emptyset$ and
\begin{equation}\label{pricing:hedging}
  \rho^{\mcY}_+(f)=\sup \left \{\sum_{i=1}^N E_{Q^i}[f^i]\mid Q\in \mathcal{M}^{\varphi}_e(\mcY) \right \}>-\infty. 
\end{equation}
  Moreover, when finite, $ \rho^{\mcY}_+(f) $ defined in \eqref{super:rho} is attained.
%\end{itemize}

\end{theorem}

The proofs of Theorem \ref{FTAP:R} and Theorem \ref{duality:R} are postponed to Section \ref{proofs:R}. As a byproduct (see Section \ref{proofs:R}, Item 1) we will also obtain the following

\begin{theorem}[Closure of $K^{\mcY}$]\label{THclosure}
    Under Assumption \ref{ass2}, $K^{\mcY} \text{ is closed in } L^{0}(\Omega, \mathbf{F}_T,P)$.
    \end{theorem}

\label{discussiondifferences} A comparison with the findings of \cite{BDFFM25} is now presented.
The results in this paper hold for possibly distinct filtrations, one for each agent. Although this formulation is already present in \cite{BDFFM25}, many of the proofs therein require coinciding filtrations—a condition we do not impose here. In particular, with respect to the closure of $K^{\mcY}$, this represents a significant departure from the earlier approach.
Aside from the case of coinciding filtrations, the requirements and the approach here are generally alternative and complementary in spirit to those in \cite{BDFFM25}. Specifically, we keep defining trading strategies and their final payoffs in full generality, but we establish our results by imposing finite dimensionality on the set $\mcY$ of permitted exchanges—a condition not considered in \cite{BDFFM25}—while avoiding the scalability condition stipulated in Requirement 2 of \cite{BDFFM25} Theorem 6.11. The finite dimensionality allows us to adopt a recursion method which was not feasible in the typical setup of \cite{BDFFM25}, and was inspired by the proof of Theorem 5.1 in  Bouchard and Nutz (2015) \cite{BouchardNutz15}.  Moreover, in the dual representation \eqref{pricing:hedging}, we emphasize that our framework permits a broader range of choices for the sets of measures on the right-hand side, since the vector $\varphi$ can be selected with considerable freedom, thereby enabling the use of a rather wide range of  subsets of collective martingale measures. 





In Section \ref{sec3} we analyze when a segmented market with $N$ agent is collectively complete and prove the following collective version of the second FTAP.
\noindent Recall that a contingent claim $f^i \in L^{0}(\Omega, \mathcal{F}_T^i, P)$ is replicable for agent $i$ if $f^i \in \R+  K_i $. We shall see that the following notion of $\mcY$-collectively replicable vector of contingent claims turns out to be crucial.

\begin{definition}
 The vector of contingent claims $ f=( f^1,\dots,  f^N) \in L^{0}(\Omega, \mathbf{F}_T, P)$    is $\mcY$-collectively replicable if $ f\in \R^N+ {\sf X}_{i=1} ^{N} K_i+\mathcal Y  $.
\end{definition}

\begin{theorem}[CFTAP II]\label{completeTH} 
Under Assumption \ref{ass2}
the market is collectively complete if and only if  $\Me$  is a singleton, namely $$\text{every } f\in L^{0}(\Omega, \mathbf{F}_T,P) \text{ is }  \mcY\text{-collectively replicable}  \Longleftrightarrow \Me \text{ is a singleton}.$$
\end{theorem}


\subsection{Auxiliary results}
We first observe the following algebraic property of superhedging functional: let $\mcY\subseteq L^{0}(\Omega, \mathbf{F}_T, P)$ be a vector space containing $\R^N_0$ and $f\in L^{0}(\Omega, \mathbf{F}_T,P)$ then 
\begin{equation}\label{rhoKY}
     \rho^{\mcY}_+(f)  =\inf\left\{\sum_{i=1}^N m_i \mid m\in\R^N \text{ and }   f-m \in {K}^{\mcY} \right\},
\end{equation}
where  $K^{\mcY}$ is defined in \eqref{KyandCY}.

\begin{lemma}\label{lemmarho}
   Suppose that $\mcY\subseteq L^{0}(\Omega, \mathbf{F}_T, P)$ is a vector space containing $\R^N_0$ and $\mathbf{NCA(\mcY)}$ holds true. Then

\begin{enumerate}
\item $\mcR (0)=0$.
\item $\mcR$ is cash additive: $\mcR(f+c)=\mcR(f) +\sum_{i=1} ^N c^i$, for all  $c \in \mathbb R^N$ and $f \in L^{0}(\Omega, \mathbf{F}_T, P)$.
\item $\mcR$ is monotone increasing with respect to the partial order of $L^{0 }(\Omega, \mathbf{F}_T,P) $ and positively homogeneous.
\item $\mcR(f)<+\infty$ for any bounded from above $f \in  L^{0 }(\Omega, \mathbf{F}_T,P)  $
\item Suppose  additionally that ${K}^{\mcY}$
is closed in $L^{0}(\Omega, \mathbf{F}_T, P)$ and $f \in L^{0}(\Omega, \mathbf{F}_T, P)$. Then $\rho^{\mcY}_+(f)>-\infty$ and $\rho^{\mcY}_-(f)<+\infty$. If $\rho^{\mcY}_+(f)<+\infty$ (resp. $\rho^{\mcY}_-(f)>-\infty$) then $\rho^{\mcY}_+(f)$ (resp. $\rho^{\mcY}_-(f)$) is attained. More specifically, $$ f-\frac{\mcR (f)}{N}\mathbf 1 \in K^{\mcY}.$$ 
\item  $\rho^{\mcY}_-(f)\leq \rho^{\mcY}_+(f)$ for every $f\in L^{0}(\Omega, \mathbf{F}_T,P)$.


\end{enumerate}

\end{lemma}
\begin{proof}
    Items 1-3 were proved in Lemma 4.4 \cite{BDFFM25} and Item 4 is a simple consequence of Items 1, 2 and 3.
    Recall that $\mathbf{a}=(a,a,\ldots,a)\in\R^N$, for $a \in \mathbb R$.
    We come to Item 5.
    First we recall from Proposition 4.9 \cite{BDFFM25} that  $\rho^{\mcY}_+(f)=N\cdot \pi^{\mcY}_+(f)$ with
\begin{equation}\label{piY}
 \pi^{\mcY}_+(f)  =\inf\left\{a\in\R\mid f\leq \mathbf{a}+k+Y \;\text{for }  k\in {\sf X}_{i=1} ^{N}  K_i,\, Y\in \mcY \right\}.
 \end{equation}
 Assume that $\rho^{\mcY}_+(f)=-\infty$ so that $\pi^{\mcY}_+(f)=-\infty$. Then for every $n\in \mathbb{N}$ there exists $k_n,Y_n$ such that $f^i\leq -n+k^i_n+Y^i_n$ for every $i=1,\ldots,N$. This implies $(f^i+n)\wedge 1\leq f^i+n\leq k^i_n+Y^i_n$ for every $i=1,\ldots,N$. We have $(f+\mathbf{n})\wedge \mathbf{1}\in {K}^{\mcY}$ for every $n\in\mathbb{N}$. Moreover $(f+\mathbf{n})\wedge \mathbf{1}\to \mathbf{1}$ $P$-a.s. and therefore $\mathbf{1}\in K^{\mcY}$, which contradicts $\mathbf{NCA(\mcY)}$.
\\ Now we proceed proving the attainment when $\rho^{\mcY}_+(f)$ is finite. By definition, there exists
    a sequence $(m_n)_n$ in  $\mathbb R^N$ such that $\widehat m_n=:\sum_{i=1}^N m^i_n \downarrow \mcR (f)$ and $f-m_n \in K^\mathcal Y $. Subsequently, writing $f-m_n=f-\frac{\widehat m_n}{N}\mathbf 1 +\frac{\widehat m_n}{N} \mathbf 1-m_n $, we see that also $f-\frac{\widehat m_n}{N}\mathbf 1 \in  K^\mathcal Y$. Indeed, $(m_n -\frac{\widehat m_n}{N}\mathbf 1) \in \R^N_0 \subseteq K^\mathcal Y$. 
    The thesis follows from the closure of $K^\mathcal Y$ and $f-\frac{\widehat m_n}{N}\mathbf 1 \rightarrow f-\frac{\mcR (f)}{N}\mathbf 1. $


 We now come to Item 6. We observe that if $\rho^{\mcY}_+(f)=+\infty$ or if $\rho^{\mcY}_-(f)=-\infty$ there is nothing to prove. We can then suppose that $\rho^{\mcY}_+(f)<+\infty$ and $\rho^{\mcY}_-(f)>-\infty$ as well, i.e. the infimum in defining $\rho^{\mcY}_+(f)$ and the supremum in defining $\rho^{\mcY}_-(f)$ are both taken over nonempty sets.
 One can introduce, similarly to $\pi^\mcY_+(f)$, $$\pi^{\mcY}_-(f)  =\sup\left\{a\in\R\mid f\geq \mathbf{a}+k-Y \;\text{for }  k\in {\sf X}_{i=1} ^{N}  K_i,\, Y\in \mcY \right\}.$$ Similarly to \eqref{rem:rhopm} one can verify that $\pi^\mcY_-(f)=-\pi^\mcY_+(-f)$ and hence $\rho^\mcY_-(f)=N\pi^\mcY_-(f)$. We then just need to verify $\pi^\mcY_-(f)\leq \pi^\mcY_+(f)$ when the infimum in defining $\pi^{\mcY}_+(f)$ and the supremum in defining $\pi^{\mcY}_-(f)$ are both taken over nonempty sets.
 Observe that if $\mathbf{x}+k+Y\geq f$ and $\mathbf{z}+\tilde{k}-\tilde{Y}\leq f$ for $x,z\in\R$ $k,\tilde{k}\in {\sf X}_{i=1} ^{N}  K_i$ and $Y,\tilde{Y}\in \mcY$ 
 we have $(\mathbf{x}-\mathbf{z})+(k-\tilde{k})+(Y+\tilde{Y})\geq f+(-f)=0$ which implies $(k^i-\tilde{k}^i)+(Y^i+\tilde{Y}^i)\geq z-x$ for every $i$. Since $\mathbf{NCA}(\mcY)$ holds we must then have $z\leq x$. Taking suprema over $z$ and infima over $x$ the inequality $\pi^\mcY_-(f)\leq \pi^\mcY_+(f)$ follows.   
\end{proof}


In Proposition 4.12 \cite{BDFFM25} it was shown that if $f \in L^{1}(\Omega, \mathbf{F}_T, P)$,   $\mcY\subseteq L^{1}(\Omega, \mathbf{F}_T, P)$ is a convex cone containing $\R^N_0$, if $\mathbf{NCA(\mcY)}$ holds, if ${K}^{\mcY}$ is closed under $P$-a.s. convergence and if $\rho^{\mcY}_+(f)<+\infty$, then $\rho^{\mcY}_+(f)$ is attained. Item 5 in Lemma \ref{lemmarho} shows, using a simpler direct proof, that attainment holds also if we remove the integrability requirements on $\mcY$ and $f$.


\begin{lemma}\label{interval} Let $\widetilde{\mcY} \subseteq L^{0}(\Omega, \mathbf{F}_T,P)$, be a vector space containing $\R^N_0$ and $\mcY = \mathrm{span}\{\widetilde{\mcY},f\}$ with $f \in L^{0}(\Omega, \mathbf{F}_T,P)$ non $\widetilde{\mcY}-$ collectively replicable. If $\mathbf{NCA(\mcY)}$ holds true and if ${K}^{\widetilde{\mcY}}$ is closed under $P$-a.s. convergence then $\rho^{\widetilde\mcY}_-(f) < 0 <  \rho^{\widetilde\mcY}_+(f)$.
\end{lemma}

\begin{proof}
  Assume by contradiction that  $\rho_+:=\rho^{\widetilde{\mcY}}_+(f)\leq 0$. As  $\mathbf{NCA(\mcY)} \Rightarrow \mathbf{NCA(\widetilde{\mcY})}$, by Lemma \ref{lemmarho} Item 5 we know $\rho^{\widetilde{\mcY}}_+(f)>-\infty$ and is attained. Then we can find $\rho_+^i \in \mathbb R$, $k_+\in {\sf X}_{i=1} ^{N}  K_i$, $Y_+\in \widetilde\mcY$ such that $f^i\leq \rho_+^i + k_+^i + Y_+^i$ for every $i=1,\ldots,N$, and $\sum_i \rho_+^i=\rho_+\leq 0$. This implies
\[-f^i+ \rho_+^i + Y^i_+ + k^i_+ \geq 0 \quad \forall \,i=1,\ldots,N \]
and at least one inequality being strict, otherwise $f$ would be $\widetilde{\mcY}-$ collectively replicable. Consider now $x^i= \rho_+^i - \frac{\rho_+}{N}$, then $x^i\geq \rho_+^i$ and 
\[-f^i+ x^i + Y^i_+ + k^i_+ \geq  0 \quad \forall \,i=1,\ldots,N, \]
with one inequality being strict. Moreover $\sum_i x^i=0$ and therefore $-f+x+Y_+\in \mcY = \mathrm{span}\{\widetilde{\mcY},f\}$ which guarantees that $\mathbf{NCA(\mathcal{Y}})$ is violated. To conclude, we observe that since both $ {\sf X}_{i=1} ^{N}  K_i $ and $\mcY$ are vector spaces, $f$ is $\mcY$-collectively replicable if and only if so is $-f$. In particular, the previous argument shows that $\rho^{\widetilde{\mcY}}_+(-f)>0$ and we can use \eqref{rem:rhopm} to conclude $\rho^{\widetilde{\mcY}}_-(f)=-\rho^{\widetilde{\mcY}}_+(-f)<0$ as desired.
\end{proof}


\begin{lemma} \label{closure+Y} Let $\widetilde{\mcY} \subseteq L^{0}(\Omega, \mathbf{F}_T,P)$, be a vector space with $\R^N_0\subseteq \widetilde{\mcY}$ and $\mcY = \mathrm{span}(\widetilde{\mcY},Y)$ for $Y\in L^{0}(\Omega, \mathbf{F}_T, P)$. If $\mathbf{NCA(\mcY)}$ holds true and ${K}^{\widetilde{\mcY}}$ is closed under $P$-a.s. convergence then ${K}^{\mcY}$  is closed under $P$-a.s. convergence.
\end{lemma}

\begin{proof}
 If $Y=\widetilde{k}+\widetilde{Y}$ for  $\widetilde{k}\in {\sf X}_{i=1} ^{N} K_i$ and $\widetilde{Y}\in \widetilde{\mcY}$ then we prove ${K}^{\mcY}={K}^{\widetilde{\mcY}}$, which is closed by assumption. Indeed ${K}^{\mcY}\supseteq {K}^{\widetilde{\mcY}}$. If $f\in {K}^{\mcY}$ then there exists $k\in {\sf X}_{i=1} ^{N}  K_i$ and $\widehat{Y}\in \mcY$ such that $f\leq k+\widehat{Y}$. We can write $\widehat{Y}=W+\alpha Y$ with $W\in\widetilde{\mcY}$ and $\alpha\in\R$. Therefore $f\leq k+W+\alpha Y=k+W+\alpha (\widetilde{k}+\widetilde{Y})=(k+\alpha\widetilde{k})+(W+\alpha \widetilde{Y})$, hence $f\in {K}^{\widetilde{\mcY}}$.
\\ Now we suppose that $Y\notin {\sf X}_{i=1} ^{N} K_i+\widetilde{\mcY}$ and we prove that ${K}^{\mcY}$ is closed. Let $f_n \in {K}^{\mcY}$ converging to $f$ $P$-a.s.. Then 
\begin{equation}\label{fkx}
f_n\leq  k_n+Y_n+\beta_n Y,    
\end{equation}
for $k_n \in {\sf X}_{i=1} ^{N} K_i$ and $Y_n\in \widetilde{Y}$ and $\beta_n \in \R$. 

If there exists a subsequence which we indicate again with $(\beta_n)$ which converges to a finite $\beta$ then $f_n-\beta_n Y$ converges $P$-a.s. to $f-\beta Y$. Clearly $f_n-\beta_n Y\leq  k_n+Y_n$ i.e. $f_n-\beta_n Y\in {K}^{\widetilde{\mcY}}$ so that $f-\beta Y\in {K}^{\widetilde{\mcY}}$ i.e. $f-\beta Y\leq  k+\widetilde{Y}$ and therefore $f\in {K}^{\mcY}$.

Suppose now there exist no subsequence converging to a finite $\beta$, but that we can find a subsequence $(\beta_n)$ such that $\lim \beta_n =+\infty$. In this case we get $\frac{f_n}{\beta_n} \rightarrow 0$. From \eqref{fkx} we get 
\[\frac{f_n}{\beta_n}- Y\leq  \frac{1}{\beta_n}(k_n+Y_n)\]
Thus  $(\frac{f_n}{\beta_n}- Y) \in {K}^{\widetilde{\mcY}}$ and $\frac{f_n}{\beta_n}- Y  \rightarrow -Y$, therefore $-Y\in {K}^{\widetilde{\mcY}}$. In particular $-Y=k-l+\widetilde{Y}$, for some $\widetilde{Y} \in \widetilde\mcY$, $k \in {\sf X}_{i=1} ^{N}  K_i $, $l \in L^{0 }_+(\Omega,  \mathbf{F}_T,P)$ and  we get  $k+Y+\widetilde{Y}=l\geq 0$,  with $(Y+\widetilde{Y}) \in \mcY$. Then $\mathbf{NCA(\mcY)}$ implies $k+Y+\widetilde{Y}=0$. As $f_n\leq  k_n+Y_n+\beta_n Y$ we deduce $f_n\leq  k_n+Y_n+\beta_n (-k-\widetilde{Y})$ i.e. $f_n\in {K}^{\widetilde{\mcY}}$ and by closure $f\in {K}^{\widetilde{\mcY}}\subseteq {K}^{\mcY}$. Alternatively,  we can find  a subsequence $(\beta_n)$ such that $\lim \beta_n =-\infty$. In this case we get again $\frac{f_n}{\beta_n} \rightarrow 0$, and from \eqref{fkx} we get 
\[\frac{f_n}{-\beta_n}+ Y\leq  \frac{1}{-\beta_n}(k_n+Y_n)\]
This means $\frac{f_n}{-\beta_n}+ Y\in \mathcal{K}^{\widetilde{\mcY}}$ and therefore $Y\in \mathcal{K}^{\widetilde{\mcY}}$. In particular $Y=k-l+\widetilde{Y}$, for some $\widetilde{Y} \in \widetilde\mcY$, $k \in {\sf X}_{i=1} ^{N}  K_i $, $l \in L^{0 }_+(\Omega,  \mathbf{F}_T,P)$ and  we get $k-Y+\widetilde{Y}=l\geq 0$,  with $(-Y+\widetilde{Y}) \in \mcY$. Then $\mathbf{NCA(\mcY)}$ implies $k-Y+\widetilde{Y}=0$, which contradicts $Y\notin {\sf X}_{i=1} ^{N} K_i+\widetilde{\mcY}$. 
\end{proof}


\subsection{Proofs of Theorems \ref{FTAP:R}, \ref{duality:R} and \ref{THclosure} }\label{proofs:R}

For any finite integer $r$ we set $$\mcY^r:=\mathrm{span}(Y_m, \, m=0,\dots,r ), $$ for $Y_0:=\mathbb R^N_0 $  and for a finite number of vectors $Y_m \in L^{0}(\Omega, \mathbf{F}_T, P), $ $m=1,\dots,r $, and we define 
 \begin{equation*}\label{CY}
        {K}^r =  \Big({\sf X}_{i=1} ^{N} \big( K_i - L^{0 }_+(\Omega, \mathcal{F}^i_T, P) \big)\Big)  +\mcY^r.  
    \end{equation*}
We notice that any finite dimensional vector space $\mcY \subseteq L^{0}(\Omega, \mathbf{F}_T, P)$ containing $\mathbb R^N_0 $ can be written as $\mcY=\mcY^R$, for some fixed integer $R$.

We prove at the same time Theorems \ref{FTAP:R}, \ref{duality:R} and \ref{THclosure} by a recursive argument on the number of generating exchanges among agents. 
Thus we fix $\mcY=\mcY^R$, for some fixed integer $R$, and we proceed recursively on $r=0,1,\ldots, R$  to prove the following

\medskip 

\textbf{Claim:}
\textit{If $\mathbf{NCA}(\mathcal{Y}^R)$ holds true then for every $r=0,1,\ldots, R$
\begin{enumerate}
\item ${K}^r$ is closed under $P$-a.s. convergence;
\item $\mathcal{M}_e(\mcY^r) \not= \emptyset$  ;
\item For any $f\in L^{0}(\Omega, \mathbf{F}_T,P)$, $\mathcal{M}^{\varphi}_e(\mcY^r)\not=\emptyset$ and
$$\rho^{\mcY^r}_+(f)=\sup\left \{\sum_{i=1}^N E_{Q^i}[f^i]\mid Q\in\mathcal{M}^{\varphi}_e(\mcY^r) \right \},$$  
for any $\varphi\in L^{0}(\Omega, \mathbf{F}_T,P)$ such that  
$\max\{|f^i|,|Y^i_1|,\ldots, |Y^i_R|\}\leq \varphi^i$.    
\end{enumerate}}


Notice that we already proved in Lemma \ref{lemmarho} Item 5 that when ${K}^r$ is closed under $P$-a.s. convergence then $\rho^{\mcY^r}_+(f)$ defined in \eqref{super:rho} is, when finite, attained.
Moreover, we already know from Remark \ref{remEQ} that $\Me \not = \emptyset \Rightarrow \mathbf{NCA(\mathcal{Y})}$.
Thus Theorem \ref{FTAP:R}, Theorem \ref{duality:R} and Theorem \ref{THclosure} immediately follow from the claim.
Observe also that the assumption $\mathbf{NCA}(\mathcal{Y}^R)$ implies $\mathbf{NCA}(\mathcal{Y}^r)$ for any $r=0,\dots,R$.  \\
\paragraph{Step $r=0$.}
As we are fixing $r=0$, we have $\mcY^r=\R^N_0$. We first demonstrate that 
 \[{K}^r={\sf X}_{i=1} ^{N} ( K_i - L^{0 }_+(\Omega, \mathcal{F}^i_T, P)) +\R^N_0\]
is closed under $P$-a.s. convergence. Let $\{f_n\}\subset K^r$ such that $f_n\to f$ $P$-a.s.. Then
\[f_n\leq x_n+k_n \text{ with } \sum_{i=1}^N x^i_n =0,\]
and $k_n \in {\sf X}_{i=1} ^{N} K_i$, Observe that $\inf_n x^i_n>-\infty$ for any $i=1,\ldots,N$. Otherwise, consider for some $i$ a subsequence, again denoted by ($x^i_n)$, $x^i_n\to -\infty$. For $l_n=x^i_n + k^i_n- f_n^i\geq 0$ and $h_n=\frac{1}{1+|x^i_n|}$ we have 
\[h^n k^i_n-h_n l_n=h_n f^i_n - h_nx^i_n \to_n 1, \]
so that $1\in ( K_i - L^{0 }_+(\Omega, \mathcal{F}^i_T, P)$, which contradicts $\mathbf{NA}_i$. Since $\sum_{i=1}^N x^i_n=0$ and $\inf_n x^i_n>-\infty$ for any $i=1,\ldots,N$, we also have that $\limsup_n x^i_n<+\infty$ for any $i=1,\ldots,N$. This means that we can find a subsequence which we denote again with $(x_n)$ such that $\lim_n x_n=x\in\R^N_0$. Then $f_n-x_n\in {\sf X}_{i=1} ^{N} ( K_i - L^{0 }_+(\Omega, \mathcal{F}^i_T,P) )$ and $f_n-x_n$ converges $P$-a.s. to $f-x$ which therefore belongs to ${\sf X}_{i=1} ^{N} ( K_i - L^{0 }_+(\Omega, \mathcal{F}^i_T,P) )$, i.e. $f\in K^r$.  

Fix any $f \in L^{0}(\Omega, \mathbf{F}_T,P)$ and let  $\varphi \in L^{0}(\Omega, \mathbf{F}_T,P)$ such that
$|f|\leq \varphi$.
We first find a change of measure $\widehat P \sim P$ so that $\varphi \in L^{1}(\Omega, \mathbf{F}_T,\widehat P)$ and all processes $X^1,\dots,X^J$ are integrable under $ \widehat P$.
Thus $f \in L^{1}(\Omega, \mathbf{F}_T,\widehat P)$. The assumption of the claim implies that  $\mathbf{NCA(\mathcal{Y}}^r)$ holds true under $ P$ and thus also under  $\widehat P$.
As $r=0$, from  $\mcY^r=\R^N_0$ and from \eqref{NAiNCA}, we have that $\mathbf{NCA(\mathcal{Y}}^r)$ under $\widehat P$ is equivalent to $\mathbf{NA}_i$ under $\widehat P$, for every  $i=1,\dots,N $,  which holds, by Theorem \ref{DMW}, if and only if 
$M_e^{i,\infty}(\widehat P)\neq \emptyset $ or $M_e^{i}\neq \emptyset $,  for every $i=1,\dots,N $. 
As $r=0$, from  $\mcY^r=\R^N_0$ and from the definition of $\mathcal{M}_e(\mcY^r)$ we have $\mathcal{M}_e(\mcY^r)={\sf X}_{i=1} ^{N}M_e^i$.
We thus conclude that  $\mathcal{M}_e(\mcY^r)\neq \emptyset$.

Take $Q \in {\sf X}_{i=1} ^{N}M_e^{i,\infty}(\widehat P)$, so that $\frac{dQ^i}{d\widehat P} \in L^{\infty}$ for each $i$.
Therefore $E_{Q^i}[\varphi^i]=E_{\widehat P}[\frac{dQ^i}{d\widehat P} \varphi^i ]<\infty$, $Q \in \mathcal{M}_e^{\varphi}(\mcY^r)$ and  $\mathcal{M}_e^{\varphi}(\mcY^r) \not= \emptyset$.

As a consequence $f \in L^{1}(\Omega, \mathbf{F}_T, \mathbf Q)$.
Theorem 5.14 \cite{FollmerSchied2} implies that $E_{Q^i}[k^i]=0$ for all $Q \in \mathcal{M}_e^{\varphi}(\mcY^r)$ and for any $k^i \in K_i $ satisfying $f^i \leq m+k^i$, for some $m \in \mathbb R$. By the classical superhedging duality \eqref{superclassic}, we therefore have 
\begin{align*}
   \rho_{i,+}(f^i)&= \inf\{m\in\R\mid  m+k^i \geq f^i, k^i \in K_i \}  =  \sup\{E_{Q^i}[f^i]\mid Q^i \in M^{i,\infty}_e(\widehat P\} 
    \\ & =  \sup\{E_{Q^i}[f^i]\mid Q^i \in M^{i,\infty}_e(\widehat P) \text{ s.t. } \varphi^i\in L^1(\Omega,\mathcal{F}^i_T,Q^i)\} \\
    &\leq  \sup\{E_{Q^i}[f^i]\mid Q^i \in M^{i}_e \text{ s.t. } \varphi^i\in L^1(\Omega,\mathcal{F}^i_T,Q^i)\} \\
    &\leq    \inf\{m\in\R\mid  m+k^i \geq f^i, k^i \in K_i \}
\end{align*} 
and we conclude, for $M^{i,\varphi^i}_e=\{Q^i \in M^{i}_e \text{ s.t. } \varphi^i\in L^1(\Omega,\mathcal{F}^i_T,Q^i) \}$,
\begin{equation*}
    \rho_{i,+}(f^i):=\inf\{m\in\R\mid  m+k^i \geq f^i, k^i \in K_i \}=\sup\{E_{Q^i}[f^i]\mid Q^i \in M^{i,\varphi^i}_e \}.
\end{equation*}
Observe that since $\mathbf{NA}_i$ holds, $\rho_{i,+}(f^i)>-\infty$ for every $i$. 
When $\mcY^r=\R^N_0$ ($r=0$) $\rho^{\mcY^r}_+(f)$ coincides with the classical super-replication of $N$ claims, denoted by $\rho_+^N(f)$ in  \cite{BDFFM25}. Thus, as explained in \cite{BDFFM25} Proposition 4.3, we have $\rho^{\mcY^r}_+(f)=\sum_{i=1}^N \rho_{i,+}(f^i)$, which is always well defined, so that
\[\rho^{\mcY^r}_+(f)=\sum_{i=1}^N\sup \left \{E_{Q^i}[f^i]\mid Q^i \in M^{i,\varphi^i}_e \right \}=\sup  \left \{\sum_{i=1}^N E_{Q^i}[f^i]\mid  Q\in\mathcal{M}^{\varphi}_e(\mcY^r) \right \}.\]


%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%

\paragraph{Iteration step: $r-1 \Rightarrow r$.} Under $\mathbf{NCA}(\mathcal{Y}^R)$ we assume that the three Items 1. 2. 3. of the claim hold  for $r-1$, and prove they hold  for $r$.

\medskip

We will apply Lemmas \ref{interval} and \ref{closure+Y} to the space $\mcY^r=\mathrm{span}(\mcY^{r-1},Y_r)$. By assumption $\mathbf{NCA}(\mathcal{Y}^R)$ holds and  ${K}^{r-1}$ is closed under $P$-a.s. convergence. As $\mathbf{NCA}(\mathcal{Y}^R)$  implies $\mathbf{NCA}(\mathcal{Y}^{r})$, from Lemma \ref{closure+Y} we deduce that ${K}^r$ is closed under $P$-a.s. convergence, which proves Item 1 of the claim.

\medskip

As proved in Lemma \ref{closure+Y}, if $Y_r\in {\sf X}_{i=1} ^{N} K_i+{\mcY}^{r-1}$ 
then we have ${K}^{r}={K}^{r-1}$. In such a case it  follows by the definitions that $\mathcal{M}^{\varphi}_e(\mcY^r)=\mathcal{M}^{\varphi}_e(\mcY^{r-1}) \not= \emptyset$, so that also $ \mathcal{M}_e(\mcY^r)\not=\emptyset $.  Then from \eqref{rhoKY} we get $\rho^{\mcY^{r-1}}_+(f)=\rho^{\mcY^r}_+(f)$ for any $f\in L^{0}(\Omega, \mathbf{F}_T,P)$ and therefore the duality follows directly from the assumption. We just proved that Items 2 and 3 hold true in this case.\\

Now we suppose that $Y_r\notin {\sf X}_{i=1} ^{N} K_i+{\mcY}^{r-1}$ and
observe that from the induction assumptions, the property $\rho^{\mcY^{r-1}}_-(Y_r)=-\rho^{\mcY^{r-1}}_+(-Y_r)$, and  Lemma \ref{interval} we have
\begin{equation}
\label{inf<sup}
\begin{split}
  a&:=\inf_{Q\in \mathcal{M}_e^{\varphi}(\mcY^{r-1})}\sum_{i=1}^N E_{Q_i}[Y^i_r]=\rho^{\mcY^{r-1}}_-(Y_r)\\
  &<0<\rho^{\mcY^{r-1}}_+(Y_r)=\sup_{Q\in \mathcal{M}_e^{\varphi}(\mcY^{r-1})}\sum_{i=1}^N E_{Q_i}[Y^i_r]:=b.   
\end{split}
\end{equation}
Thus we can find $Q\in \mathcal{M}_e^{\varphi}(\mcY^{r-1})$ such that $Y^i_r \in L^{1}(\Omega, \mathcal{F}^i_T,Q^i)$ and $\sum_{i=1}^N E_{Q_i}[Y^i_r]=0$, which proves $\mathcal{M}_e^{\varphi}(\mcY^{r})\neq \emptyset$. This  implies Item 2 of the claim: $\mathcal{M}_e(\mcY^r)\neq \emptyset$.

\medskip

Finally for any $f\in L^{0}(\Omega, \mathbf{F}_T,P)$ we show
$\rho^{\mcY^r}_+(f)=\sup\{\sum_{i=1}^N E_{Q^i}[f^i]\mid Q\in\mathcal{M}^{\varphi}_e(\mcY^r)\}$,  
for any $\varphi\in L^{0}(\Omega, \mathbf{F}_T,P)$ such that  
$\max\{|f^i|,|Y_1^i|,\ldots, |Y_R^i|\}\leq \varphi^i$.
We have already shown that $\mathcal{M}_e^{\varphi}(\mcY^{r})\neq \emptyset$ and clearly 
\begin{equation}
\label{ineq1rhoy}
    \rho^{\mcY^r}_+(f)\geq\sup\{\sum_{i=1}^N E_{Q_i}[f^i]\mid Q\in\mathcal{M}_e^{\varphi}(\mcY^r)\}.
\end{equation}


 \textbf{Case 1: $\rho^{\mcY^r}_+(f)<+\infty$. } In this case we may for simplicity assume w.l.o.g. (by Lemma \ref{lemmarho} Item 2) that $\rho^{\mcY^r}_+(f)=0$. We claim that 
\begin{equation}\label{claim:0} 0\in E:=\overline{\left\{ \left(\sum_{i=1}^N E_{Q^i}[Y^i_r],\sum_{i=1}^N E_{Q^i}[f^i] \right)\mid Q\in \mathcal{M}_e^{\varphi}(\mcY^{r-1})\right\}}\subset \R^2\end{equation}
By contradiction $0\notin E$. By separation arguments then there exists $(h_1,h_2)\in \R^2$ such that 
\[\sup_{Q\in \mathcal{M}_e^{\varphi}(\mcY^{r-1})}\left\{h_1 \sum_{i=1}^N E_{Q^i}[Y^i_r]+h_2\sum_{i=1}^N E_{Q^i}[f^i] \right\}<0.\] 
In particular, without loss of generality, we may assume that  $\sqrt{h_1^2+h_2^2}=\frac12$ and this implies $\abs{h_1Y^i_r+h_2f^i}\leq \varphi^i$. Moreover by assumption
\begin{eqnarray*}
    \sup_{Q\in \mathcal{M}_e^{\varphi}(\mcY^{r-1})}\left\{h_1 \sum_{i=1}^N E_{Q^i}[Y^i_r]+h_2\sum_{i=1}^N E_{Q^i}[f^i] \right\} & = & \sup_{Q\in \mathcal{M}_e^{\varphi}(\mcY^{r-1})}\left\{\sum_{i=1}^N E_{Q_i}[h_1Y^i_r+h_2f^i]\right\}
    \\ & = & \rho_+^{\mcY^{r-1}}(h_1 Y_r+h_2 f)
\end{eqnarray*}
and by definition and using $Y_r \in \mcY^r$
\[\rho_+^{\mcY^{r-1}}(h_1 Y_r+h_2 f)\geq \rho_+^{\mcY^r}(h_1 Y_r+h_2 f)=\rho_+^{\mcY^r}(h_2 f)\]
i.e. $\rho_+^{\mcY^r}(h_2 f)<0$ which necessarily implies $h_2\neq 0$, by Item 1 Lemma \ref{lemmarho}. If $h_2>0$ then by positive homogeneity (Lemma \ref{lemmarho} Item 3) $\rho_+^{\mcY^r}(f)<0$ which contradicts $\rho_+^{\mcY^r}(f)=0$.
Then necessarily $h_2<0$. As we proved $\mathcal{M}_e^{\varphi}(\mcY^{r})\neq \emptyset$, we take  $\widehat{Q}\in \mathcal{M}_e^{\varphi}(\mcY^r)\subseteq \mathcal{M}_e^{\varphi}(\mcY^{r-1})$ and compute
\[0>\sup_{Q\in \mathcal{M}_e^{\varphi}(\mcY^{r-1})}\left\{\sum_{i=1}^N E_{Q^i}[h_1Y^i_r+h_2f^i]\right\}\geq \sum_{i=1}^N E_{\widehat{Q}^i}[h_1Y^i_r+h_2f^i]= h_2\sum_{i=1}^N E_{\widehat{Q}^i}[f^i].\]
This implies $$\sum_{i=1}^N E_{\widehat{Q}^i}[f^i]>0=\rho^{\mcY}_+(f)\geq\sup_{Q\in\mathcal{M}_e^{\varphi}(\mcY^{r})}\sum_{i=1}^N E_{Q^i}[f^i], $$
a contradiction.
\\The claim in \eqref{claim:0} leads to a sequence of $Q^n\in \mathcal{M}_e^{\varphi}(\mcY^{r-1})$ such that 
$$\sum_{i=1}^N E_{Q_n^i}[Y^i_r]\to 0 \text{ and } \sum_{i=1}^N E_{Q_n^i}[f^i] \to 0.$$ 
We now show that from the conditions in \eqref{inf<sup}
we can construct $Q_n^+,Q_n^-\in \mathcal{M}_e^{\varphi}(\mcY^{r-1})$ and $0\leq \lambda^+_n,\lambda^-_n,\lambda_n$ with $\lambda^+_n+\lambda^-_n+\lambda_n=1$, such that 
$$\widehat{Q}_n:=\lambda^+_n Q_n^+ + \lambda^-_n Q_n^- + \lambda_n Q_n \in \mathcal{M}_e^{\varphi}(\mcY^{r})$$ 
and $\lambda^+_n\to 0, \lambda^-_n\to 0$. In fact for any $\varepsilon>0$ there exists an $n(\varepsilon)$ such that $q_n:=\sum_{i=1}^N E_{Q_n^i}[Y^i_r]\in (-\varepsilon,\varepsilon)$ for any $n>n(\varepsilon)$. We choose in particular $\varepsilon>0$ such that $(-\varepsilon,\varepsilon)\subset (a,b)$ for $a,b$ given in \eqref{inf<sup}. 
For any $n>n(\varepsilon)$ such that $q_n\in (-\varepsilon,0]$ we set $\lambda_n^-=0$, $Q_n^-$ arbitrary, $Q_n^+:=\bar{Q}\in \mathcal{M}_e^{\varphi}(\mcY^{r-1})$ where $\bar{Q}$ satisfies $\bar{q}:=\sum_{i=1}^N E_{\bar{Q}^i}[Y^i_r]\in (\varepsilon, b)$. Therefore in this case we can also find $\lambda^+_n, \lambda_n\in [0,1]$ with $\lambda^+_n+\lambda_n=1$ and $\lambda_n\bar{q}+\lambda_n^+q_n=0$. $\lambda_n\bar{q}+(1-\lambda_n)q_n=0$ implies $\lambda_n= \frac{-q_n}{\bar{q}-q_n}$ and since $q_n\to 0$, then $\lambda_n\to 0$.    
On the other hand, for any $n>n(\varepsilon)$ such that $q_n\in (0,\varepsilon)$, we set $\lambda_n^+=0$, $Q_n^+$ arbitrary, $Q_n^-:=\hat{Q}\in \mathcal{M}_e^{\varphi}(\mcY^{r-1})$ where $\hat{Q}$ satisfies $\hat{q}:=\sum_{i=1}^N E_{\bar{Q}^i}[Y^i_r]\in (a,-\varepsilon)$. Therefore in this case we can also find $\lambda^-_n, \lambda_n\in [0,1]$ with $\lambda^-_n+\lambda_n=1$ and $\lambda_n\hat{q}+\lambda_n^- q_n=0$. $\lambda_n\hat{q}+(1-\lambda_n)q_n=0$ implies $\lambda_n= \frac{-q_n}{\bar{q}-q_n}$ and since $q_n\to 0$ then $\lambda_n\to 0$.     Therefore
$$\sum_{i=1}^N E_{\widehat{Q}_n^i}[Y^i_r] = 0 \text{ and } \sum_{i=1}^N E_{\widehat{Q}_n^i}[f_i] \to 0,$$
which together with \eqref{ineq1rhoy} yields $\rho^{\mcY^r}_+(f)=\sup\{\sum_{i=1}^N E_{Q_i}[f_i]\mid Q\in\mathcal{M}_e^{\varphi}(\mcY^{r})\}$.\\

 \textbf{Case 2: $\rho^{\mcY^r}_+(f)=+\infty$. }
For any $n\in\mathbb{N}$ denote with $f\wedge \mathbf{n}$ the vector of components $f^i\wedge n$ for $i=1,\ldots,n$. By Item 4 Lemma \ref{lemmarho}, $\rho^{\mcY^r}_+(f\wedge \mathbf{n})<+\infty $ and so from the previous step we have $\rho^{\mcY^r}_+(f\wedge \mathbf{n})=\sup\{\sum_{i=1}^N E_{Q^i}[f^i\wedge n]\mid Q\in \mathcal{M}_e^{\varphi}(\mcY^{r})\}$. Since $\rho^{\mcY^r}_+(f\wedge \mathbf{n})$ is increasing the $\lim_n \rho^{\mcY^r}_+(f\wedge \mathbf{n}):=L$ exists. 
By monotonicity of $E_{Q^i}[f^i\wedge n]$, we deduce

\[\sup \left \{\sum_{i=1}^N E_{Q^i}[f^i\wedge n]\mid Q\in\mathcal{M}_e^{\varphi}(\mcY^{r}) \right \}\uparrow_n \sup \left \{\sum_{i=1}^N E_{Q^i}[f^i]\mid Q\in\mathcal{M}_e^{\varphi}(\mcY^{r}) \right \}=L.\]
Note that the terms in LSH equal $\rho^{\mcY^r}_+(f\wedge \mathbf{n})$, so that we conclude: $\lim_n\rho^{\mcY^r}_+(f\wedge \mathbf{n})=L$.
If $L$ were finite 
%$L=\lim_n \rho^{\mcY^r}_+(f\wedge \mathbf{n})$, 
then for $\mathbf{p}^n=(\frac{\rho^{\mcY^r}_+(f\wedge \mathbf{n})}{N},\ldots, \frac{\rho^{\mcY^r}_+(f\wedge \mathbf{n})}{N})$,
the sequence $f\wedge \mathbf{n}-\mathbf{p}^n$ would belong ${K}^r$, by Item 5 Lemma \ref{lemmarho}. As $K^{\mcY}$ is closed, this would imply  $f-\mathbf{\frac{L}{N}}\in {K}^r$ i.e. $L\geq \rho^{\mcY}_+(f)=+\infty$, which is not possible. Hence $L=\sup \left \{\sum_{i=1}^N E_{Q^i}[f^i]\mid Q\in\mathcal{M}_e^{\varphi}(\mcY^{r}) \right \}= +\infty$ and this conclude the proof.






\section{Collectively complete markets: CFTAP II}\label{sec3}



In this section, we provide a precise definition of $\mathbf{NCA}(\mathcal{Y})$-prices for vectors of contingent claims and characterize them, in Theorem \ref{BaseFTAPII}, as expectations under equivalent collective martingale measures. Subsequently, we characterize contingent claims that are collectively replicable, demonstrating that, similarly to the classical setting, $f$ is collectively replicable if and only if $\rho_-^{\mathcal{Y}}(f) = \rho_+^{\mathcal{Y}}(f)$, as shown in Proposition \ref{prepcftap2}. Relying on the dual representation \eqref{pricing:hedging}, we then characterize collective completeness in Proposition \ref{propclosed}.

To begin with, recall that the (global) securities market comprises a zero-interest rate riskless asset $X^0$ and $J$ risky assets with discounted price processes $X^j=(X^j_t)_{t\in [0,T]}$, $j=1, \dots ,J$, $J\geq 1$. 

\begin{definition}
A vector of prices $\Pi_ f \in \mathbb{R}^N$ is called a  \textbf{NCA}$(\mcY)$-price for the contingent claims $f=(f^1,\dots,f^N) \in L^{0 }(\Omega, \mathbf{F}_T,P)$ if there exist processes $X^{J+1},\dots, X^{J+N}$ such that:
\begin{enumerate}
\item $X^{J+i}$ is adapted  to the  filtration $\fib$, $i=1,\dots, N$.
    \item $\Pi^i_ f = X^{J+i}_0$, $i=1,\dots, N$.
    \item $X^{J+i}_T =    f^i$, $i=1,\dots, N$.
    \item For all $i$, \textbf{NCA}$(\mcY)$ holds in the extended market $(X^j)_{j\in (i)\cup\{J+i\}}$.
\end{enumerate} 
Let $\Pi( f)$ be the set of \textbf{NCA}$(\mcY)$-price for the contingent claims $ f=( f^1,\dots,  f^N).$ 
 \end{definition}



\begin{theorem}
\label{BaseFTAPII}
 Let Assumption \ref{ass2} hold. 
Then, for any $ f\in L^{0}(\Omega, \mathbf{F}_T,P)$, and any fixed $\varphi\in L^{0}(\Omega, \mathbf{F}_T,P)$ such that  
$\max \{|f^i|,|Y^i_0|,\ldots, |Y^i_R|\}\leq \varphi^i$, it holds that
\[
\Pi( f) = \left\{ (E_{Q^1}[   f^1],\dots, E_{Q^N}[   f^N]) \mid Q \in \mathcal{M}^\varphi_e(\mcY)\right\},
\]
where $\mathcal{M}^\varphi_e(\mcY)$ is given in \eqref{Mfi}.
\end{theorem}
\begin{proof} 
Let $\varphi\in L^{0}(\Omega, \mathbf{F}_T,P)$ be given as in the statement.
Up to a change of measure to an equivalent one with bounded density, we can assume that $\varphi\in L^{1}(\Omega, \mathbf{F}_T,P') $, $\mcY \subseteq L^{1 }(\Omega, \mathbf{F}_T,P')$ and $X=(X^1,\dots,X^J)$ is integrable under $P'$.
Suppose that $\Pi_ f \in \Pi( f)$, then \textbf{NCA}$(\mcY)$ holds in the extended market, thus by Theorem \ref{FTAP3}, there exists an equivalent collective martingale measure $Q=(Q^1,\dots, Q^N)$ for the extended markets, with bounded densities w.r.t. $P'$, and in particular belonging to $\mathcal{M}^\varphi_e(\mcY)$ as a consequence. Then,  $X^{J+i}_t = E_{Q^i}[X^{J+i}_T | \mathcal{F}^i_t]=E_{Q^i}[ f^i | \mathcal{F}^i_t]$. By definition
\[
\Pi^i_ f = X^{J+i}_0 = E_{Q^i}[X^{J+i}_T | \mathcal{F}_0] = E_{Q^i}[   f^i].
\]
Conversely, take $(E_{Q^1}[   f^1],\dots, E_{Q^N}[   f^N])$ for $ Q \in \mathcal{M}^\varphi_e(\mcY)$. Define for $i=1,\dots,N$ the $Q^i-$ martingales $X^{J+i}_t = {E}_{Q^i}[   f^i | \mathcal{F}^i_t]$. Since $Q \in \mathcal{M}^\mcY_e$, and $Q^i$ is an equivalent martingale measure for the extended market $(X^j)_{j\in(i)\cup\{J+i\}}$, $Q$ acts as an equivalent collective martingale measure for the extended markets, which thus does not admit $\mcY$-collective arbitrages, by Theorem \ref{Th1}.
Finally, $X^{J+i}_T = f^i$ for mere measurability and integrability arguments, thus
thus $\Pi_ f \in \Pi( f)$ by definition.
\end{proof}


Suppose that $f=(f^1,\dots,f^N) \in L^{0 }(\Omega, \mathbf{F}_T,P)$ is not collectively replicable. Differently from the classical case, see for example \cite{FollmerSchied2} Theorem 5.32, the set $\Pi(f)$ is not necessarily open (see the Example \ref{notopen}). Moreover $\Pi(f)$ can not be closed, at least under weak conditions on $f$ (see Proposition \ref{notclosed}).


\begin{example}\label{notopen}


Consider the example 7.2 \cite{BDFFM25} with $|\Omega|=6$, two periods and $N=2$ agents, each investing in one single stock. Take as contingent claims $g^1=0$ and $g^2=(0,0,0,0,1,1)$, $g=(g^1,g^2)$. Using the set of collective martingale measures on page 49 \cite{BDFFM25},  we compute $E_{Q^1}[g^1]+E_{Q^2}[g^2]=\frac{1}{2}q,$ with  $0< q< 1$. Then $\rho^{\mcY}_-(g) =0$ and $ \rho^{\mcY}_+(g)=\frac{1}{2}$ and $g$ is not $\mcY$-collectively replicable. Moreover, using Theorem \ref{BaseFTAPII} $$\Pi(g)=\{(0,\frac{1}{2}q) \mid 0<q<1 \} \subset \mathbb R^2.$$
Thus this examples shows that for a non collectively replicable $g$, $\Pi(g)$ is not necessarily an open set in $\mathbb R^2 $. Clearly, by Theorem \ref{BaseFTAPII}, for any claim $g$ we have $$p \in \Pi(g) \Rightarrow \rho^{\mcY}_-(g)\leq \sum_{i=1}^Np^i \leq \rho^{\mcY}_+(g)$$ 
At the same, $\Pi(g)$ is not closed in general, as shown in Proposition \ref{notclosed}



\end{example}

\begin{proposition}
\label{prepcftap2}
 Let Assumption \ref{ass2} hold. Then $f \in L^{0 }(\Omega, \mathbf{F}_T , P)$ is $\mcY$-collectively replicable if and only if $\rho^{ \mcY}_-( f)=\rho^{ \mcY}_+( f)$.
\end{proposition}
\begin{proof}
Recall from Lemma \ref{lemmarho} Item 6 that by $\mathbf{NCA}(\mcY)$ we have  $\rho^{ \mcY}_-( f)\leq\rho^{ \mcY}_+( f)$.
We start by proving that if $f$ is collectively replicable then $\rho^{ \mcY}_-( f)=\rho^{ \mcY}_+( f)$. 
Let  $\varphi\in L^{0}(\Omega, \mathbf{F}_T,P)$ be any given random vector  satisfying 
$\max \{|f^i|,|Y^i_1|,\ldots, |Y^i_R|\}\leq \varphi^i$ for every $i$. Take $Q\in \mathcal{M}^\varphi_e(\mcY)$, which is nonempty by Theorem \ref{duality:R}. Write $f=x+k+Y$ with obvious notation from replicability. Since $f,Y\in L^{1}(\Omega, \mathbf{F}_T,\mathbf{Q})$, by definition of $\mathcal{M}^\varphi_e(\mcY)$ we see that  $(k^i)^-\in L^1(Q^i)$ for every $i$. \cite{FollmerSchied2} Theorem 5.14 implies that $E_{Q^i}[k^i]=0$ for every $i$. As a consequence, using also $Q\in \mathcal{M}^\varphi_e(\mcY)$, we can write
    $$\sum_{i=1}^NE_{Q^i}[f^i]=\sum_{i=1}^N\Big(x^i+E_{Q^i}[k^i]
    +E_{Q^i}[Y^i]\Big)=\sum_{i=1}^Nx^i.$$
    Hence $Q\mapsto \sum_{i=1}^NE_{Q^i}[f^i]$ is constant on $\mathcal{M}^\varphi_e(\mcY)$, so using \eqref{pricing:hedging}
    $$
  \rho^{\mcY}_+(f)=\sup \left \{\sum_{i=1}^N E_{Q^i}[f^i]\mid Q\in \mathcal{M}^{\varphi}_e(\mcY) \right \}=\inf\left \{\sum_{i=1}^N E_{Q^i}[f^i]\mid Q\in \mathcal{M}^{\varphi}_e(\mcY) \right \}=\rho^{\mcY}_-(f).$$
We now prove that for a non $\mcY$-collectively replicable $f$ we have
$\rho^{ \mcY}_-( f) < \rho^{ \mcY}_+( f)$.
 By the definitions, $\rho^{ \mcY}_-( f) \leq \rho^{ \mcY}_+( f)$. Assume by contradiction $\rho^{ \mcY}_-( f) = \rho^{ \mcY}_+( f)$. By Lemma \ref{lemmarho} Item 5 both these then need to be finite and  attained. Recall from  \eqref{piY} the definition of $\pi^{\mcY}_+$.  From \cite{BDFFM25} Proposition 4.9  $\rho^{\mcY}_+( f)=N\cdot \pi^{\mcY}_+( f)$ and $\pi^{\mcY}_+( f)$ is attained iff $\rho^{\mcY}_+(f)$ is attained.  Thus we also have $\pi^{ \mcY}_-( f) = \pi^{ \mcY}_+( f):=x \in \mathbb R$ and  there exists $k_\pm\in {\sf X}_{i=1} ^{N} K_i$, $Y_\pm\in\mcY$ such that 
  \[x+ k_-^i - Y_-^i \leq  f^i \leq x+ k_+^i + Y_+^i\quad \forall \,i=1,\ldots,N.\]
  As a consequence 
  \[0\leq  k_+^i-k_-^i + Y_+^i + Y_-^i \quad \forall \,i=1,\ldots,N,\]
  which by $\mathbf{NCA(\mcY)}$ implies
  \[0 =  k_+^i-k_-^i + Y_+^i+Y_-^i \quad \forall \,i=1,\ldots,N,\]
  i.e. 
  \[k_-^i - Y_-^i =  f^i-x = k_+^i + Y_+^i\quad \forall \,i=1,\ldots,N,\]
  which is not possible as $ f$ is not $\mcY$-collectively replicable.  
\end{proof}

\begin{proposition}
\label{prop:attainrepl}
Let Assumption \ref{ass2} hold. 
Take  $f\in L^{0}(\Omega, \mathbf{F}_T,P)$. Let  $\varphi\in L^{0}(\Omega, \mathbf{F}_T,P)$ be any given random vector  satisfying 
$\max \{|f^i|,|Y^i_1|,\ldots, |Y^i_R|\}\leq \varphi^i$ for every $i$.
    Suppose that both the primal problem \eqref{super:rho} and the dual one \eqref{pricing:hedging} are attained. Then $f$ is $\mcY$-collectively replicable.
    The same implication holds for $\rho^{\mcY}_-$ as well.
\end{proposition}
\begin{proof}
    Suppose $\mcR( f)=\sum_{i=1}^NE_{Q^i}[   f^i]$  for some $ Q \in \mathcal{M}^\varphi_e(\mcY)$. Since $\mcR( f)$ is finite, it is  attained (Lemma \ref{lemmarho} Item 5) and thus for some $x\in \R^N$ with $\sum_i x^i=\mcR( f)$, $k\in {\sf X}_{i=1} ^{N} K_i$, $Y\in\mcY$ we have $x^i+k^i+Y^i\geq  f^i$ for every $i$. By setting $\widehat{Y}^i=x^i-E_{Q^i}[   f^i]+Y^i$ we also have that $E_{Q^i}[   f^i]+k^i+\widehat{Y}^i\geq  f^i$ for every $i$, with $\widehat{Y}\in\mcY$. This immediately gives $E_{Q^i}[  \widehat{Y}^i]\geq 0$ for every $i$. At the same time if the inequality $E_{Q^i}[   f^i]+k^i+\widehat{Y}^i\geq  f^i$ were strict with positive ($P$ or $Q^i$ equivalently) probability for some index $h$, then $E_{Q^h}[  \widehat{Y}^h]>0$ with a similar computation. This would yield $\sum_jE_{Q^j}[  \widehat{Y}^j]>0$, a contradiction with $Q\in\mathcal{M}^\varphi_e(\mcY) $. We then infer $E_{Q^i}[   f^i]+k^i+\widehat{Y}^i=  f^i$, for every $i$, $Q^i$ (hence $P$ by equivalence) a.s..
\end{proof}


\begin{proposition}\label{notclosed}
Let Assumption \ref{ass2} hold. 
   If $f\in L^0(\Omega, \mathbf{F}_T, P)$ is not $\mcY$-collectively replicable and if $\pii( f^i)<+\infty$ and $\rho_{i,+}(-f^i)<+\infty$ for every $i$ then $\Pi(f)$ is not closed. 
\end{proposition}
\begin{proof}
Every $p \in \Pi(f) $ satisfies
$$-\rho_{i,+}(-f^i)\leq \inf \left \{E_{Q^i}[f^i]\mid Q\in \mathcal{M}^{\varphi}_e(\mcY) \right \}\leq p^i \leq \sup \left \{E_{Q^i}[f^i]\mid Q\in \mathcal{M}^{\varphi}_e(\mcY) \right \}\leq \pii( f^i) $$
and thus $\Pi(f)$ is bounded in $\mathbb R^N$. If $\Pi(f)$ were closed then it would be compact and by Theorem \ref{BaseFTAPII} together with \eqref{pricing:hedging} we would have  $
  \rho^{\mcY}_+(f)=\sum_{i=1}^N E_{Q^i}[f^i]$, for some 
 $Q\in M^\varphi_e(\mcY)$, for $\max \{|f^i|,|Y^i_1|,\ldots, |Y^i_R|\}\leq \varphi^i$. This in turns would imply by Proposition \ref{prop:attainrepl} that $f$ is $\mcY$-collectively replicable, a contradiction.
\end{proof}





Theorem \ref{completeTH} is a consequence of the following proposition. We write $e_1,\dots, e_N$ for the canonical basis of $\R^N$
\begin{proposition}\label{propclosed}
    Let Assumption \ref{ass2} hold. Then the following are equivalent:
    \begin{enumerate}
        \item Every $ f\in L^{0}(\Omega, \mathbf{F}_T,P)$ is $\mcY$-collectively replicable;
        \item Every $ f\in L^{\infty}(\Omega, \mathbf{F}_T,P)$ is $\mcY$-collectively replicable;
        \item  $1_Ae_j$ is $\mcY$-collectively replicable for every $j=1,\dots, N$ and every $A\in \mcF_T^j$;
        \item $\Me$ is a singleton;
        \item  $\rho^{ \mcY}_\pm$ coincide on $L^{0}(\Omega, \mathbf{F}_T,P)$.
    \end{enumerate}
\end{proposition}
\begin{proof}
    The implications $1\Rightarrow 2\Rightarrow 3$ are obvious. We show $3\Rightarrow 4$. Take $Q,\widehat{Q}\in \Me$. From Proposition \ref{prepcftap2} we have $\rho^{ \mcY}_-( 1_Ae_j)=\rho^{ \mcY}_+( 1_Ae_j)$. A the same time, choosing $\varphi^i=\max \{|Y^i_1|,\ldots, |Y^i_R|\}$, Remark \ref{remdegenerate}, together with Theorem \ref{duality:R} allows us to write
    $$\rho^{ \mcY}_-( 1_Ae_j)\leq E_{Q^j}[1_A]=\sum_{i=1}^NE_{Q^i}[1_Ae_j]\leq \rho^{ \mcY}_+( 1_Ae_j)$$ and the same holds for $E_{\widehat{Q}^j}[1_A]$, so that $E_{Q^j}[1_A]=E_{\widehat{Q}^j}[1_A]$. Since this can be repeated for every $j$ and $A\in\mcF_T^j$, it follows that $\Me$ (which is nonempty) also consists of at most one element.

    We come to $4\Rightarrow 5$. Pick $f\in L^{0}(\Omega, \mathbf{F}_T,P)$ and $\varphi\in L^{0}(\Omega, \mathbf{F}_T,P)$ with
$\max \{|f^i|,|Y^i_1|,\ldots, |Y^i_R|\}\leq \varphi^i$. As argued before, $ \mathcal{M}^\varphi_e(\mcY)\neq \emptyset$ by $\mathbf{NCA}(\mcY)$ and at the same time $ \mathcal{M}^\varphi_e(\mcY)\subseteq \Me$, the latter being a singleton. Thus, $\mathcal{M}^\varphi_e(\mcY)$ is itself a singleton, say $\{\widehat{Q}\}$. Since $\rho^{\mcY}_-(f)=-\rho^{\mcY}_+(-f)$, \eqref{pricing:hedging} implies $$\rho^{\mcY}_+(f)=\sum_{i=1}^N E_{\widehat{Q}^i}[f^i]=\rho^{\mcY}_-(f).$$
Finally, implication $5\Rightarrow 1$ follows immediately from Proposition \ref{prepcftap2}.
\end{proof}


\section{Examples}
\label{sec:examples}
We describe a simple market with two agents and two stocks, and where each agent $i$ may invest only in the stock $X^i$ and in the riskless asset.  In this example there exists a global arbitrage ($M_e := M_e^1\cap  M_e^2 =\emptyset$); each single market is arbitrage free and incomplete ($| M_e^1|=\infty$ and $|M_e^2|=\infty$); $\mathbf {NCA}(\mcY) $ holds true and the market is collectively complete ($|\mathcal{M}_e(\mcY)|=1$), so that there exist a unique price vector for each vector of contingent claims. 
Consider the setup described in Figure \ref{figtree}, with common filtration $$\mcF_0=\{\emptyset, \Omega\},\, \mcF_1=\sigma(A_1=\{\omega_1,\omega_2\},A_2=\{\omega_3,\omega_4\},A_3=\{\omega_5,\omega_6\}),\,\mcF_2=\mathcal{P}(\Omega).$$
We show that every vector of contingent claims is collectively replicable for $\mcY=\mcY_0\cap L^0(\Omega,\mcF_1,P)$.
To this end we first focus on the time step $\{0,1\}$. Take any $g_1,g_2$ which are $\mcF_1$ measurable. Let  $g^i=(g^i_j)_{j=1,2,3}, \,g^i_j\in\R$ on $A_j,j=1,2,3$. Similarly, $Y=(Y^1,Y^2)\in\mcY$ is such that $Y^2=-Y^1$ and $Y^1=y^1_j$ on $A_j,j=1,2,3$. We show that there exist $(B^1,B^2,h,H,y^1_1,y^1_2,y^1_3)\in\R^6$ such that
$$B^1+hX^1(\omega)+Y^1(\omega)=g^1(\omega),\quad B^2+HX^2(\omega)-Y^1(\omega)=g^2(\omega)\quad \forall\omega\in\Omega.$$
This reads:
$$\begin{cases}
    B^1+4h+0H+y^1_1+0y^1_2+0y^1_3&=g^1_1\\
    B^1+4h+0H+0y^1_1+y^1_2+0y^1_3&=g^1_2\\
    B^1+12h+0H+0y^1_1+0y^1_2+y^1_3&=g^1_3\\
    B^2+0h+16H-y^1_1+0y^1_2+0y^1_3&=g^2_1\\
    B^2+0h+8H+0y^1_1-y^1_2+0y^1_3&=g^2_2\\
    B^2+0h+8H+0y^1_1+0y^1_2-y^1_3&=g^2_3\\    
\end{cases}\text{ or } \begin{pmatrix}
    1 & 0 & 4 & 0 & 1 & 0 & 0 \\
    1 & 0 & 4 & 0 & 0 & 1 & 0 \\
    1 & 0 & 12 & 0 & 0 & 0 & 1 \\
    0 & 1 & 0 & 16 & -1 & 0 & 0 \\
    0 & 1 & 0 & 8 & 0 & -1 & 0 \\
    0 & 1 & 0 & 8 & 0 & 0 & -1 \\
\end{pmatrix}
\begin{pmatrix}
    B^1 \\ B^2 \\ h \\ H \\ y^1_1 \\ y^1_2 \\ y^1_3
\end{pmatrix}
=
\begin{pmatrix}
    g^1_1 \\ g^1_2 \\ g^1_3 \\ g^2_1 \\ g^2_2 \\ g^2_3
\end{pmatrix} $$
The rank of the matrix of the system is $6$, a solution exists. In particular, one such a solution can be always obtained even asking $B^1=B^2$, since 
$$\mathrm{det}\begin{pmatrix}
    1 & 4 & 0 & 1 & 0 & 0 \\
    1 & 4 & 0 & 0 & 1 & 0 \\
    1 & 12 & 0 & 0 & 0 & 1 \\
    1 & 0 & 16 & -1 & 0 & 0 \\
    1 & 0 & 8 & 0 & -1 & 0 \\
    1 & 0 & 8 & 0 & 0 & -1 \\
\end{pmatrix}=-128.$$
Now observe that in the time step $\{1,2\}$ each of the two markets is (separately) complete. The arguments above allow us to conclude that each $\mcF_2$-measurable pair $(g_1,g_2)$ is collectively replicable. One can easily compute the relevant sets of equivalent martingale measures:
\begin{align*}
    M_e^1&=\bigg\{\bigg(\frac12 \Big(\frac12-p\Big), \frac12\Big(\frac12-p\Big), \frac12 p, \frac12 p, \frac16, \frac13\bigg),\, p\in\bigg(0,\frac{1}{2}\bigg)\bigg\},\\
     M_e^2&=\bigg\{\bigg(\frac18, \frac18, \frac12\Big(\frac34-q\Big), \frac12\Big(\frac34-q\Big), \frac23q, \frac13q\bigg),\, q\in\bigg(0,\frac{3}{4}\bigg)\bigg\},\\
     \mathcal{M}_e(\mcY)&=\{(Q^1,Q^2)\} \not=\emptyset, \quad M_e := M_e^1\cap  M_e^2 =\emptyset,
\end{align*}
where $Q^1\in M_e^1$ corresponds to $p=\frac14$ and $Q^2\in M^2_e$ to the choice $q=\frac12$. This is clearly consistent with CFTAP II. Note that although there exists a global arbitrage ($M_e = M_e^1 \cap  M_e^2 =\emptyset$) and $Q^1\neq Q^2$ on $\mcF_2$, we do have $Q^1=Q^2$ on $\mcF_1$, which is equivalent to the polarity condition for the exchanges $\mcY$.
